window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_022"]={"n":"何景明","dyn":"明","poems":[{"t":"赠贾司教先生 其一","f":"古风","c":["春风桃李绛帐，朝日苜蓿空盘。","王公不志温饱，郑老岂为饥寒。"]},{"t":"鲥鱼","f":"七言律诗","c":["五月鲥鱼已至燕，荔枝卢橘未应先。","赐鲜遍及中珰第，荐熟谁开寝庙筵。","白日风尘驰驿骑，炎天冰雪护江船。","银鳞细骨堪怜汝，玉箸金盘敢望传。"]},{"t":"侠客行","f":"古风","c":["朝入主人门，暮入主人门，思杀主仇谢主恩。","主人张镫夜开宴，千金为寿百金饯。","秋堂露下月出高，起视厩中有骏马，匣中有宝刀。","拔刀跃马门前路，投主黄金去不顾。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，驱车折轴。","不畏折轴，但畏车覆。","芃芃者莸，生彼中衢。","虽有兰蕙，当门则锄。","同行窃金，相顾道左。","我实不知，彼则畏我。","食荼知苦，食梅知酸。","狐裘之蔽，可以禦寒。","有虎斑斑，伏于林下。","我欲射虎，愧无劲弩。","肃彼北风，渡彼中流。","岂不怀忧，与子同舟。"]},{"t":"车遥遥二首 其一","f":"五言绝句","c":["马立车遥遥，望望车尘灭。","但闻上车语，不得下车别。"]},{"t":"枣下何纂纂","f":"五言古诗","c":["种枣北墙下，枣熟委路衢。","行人竞取食，居者守空株。","忆昔枣初赤，倾路且停车。","枣当今日尽，谁能少踟蹰。","天命诚不易，荣落互相渝。","功勋本积累，倾夺在须臾。","聆我枣下言，贫贱可久娱。"]},{"t":"刺促篇","f":"古风","c":["刺促刺促，井燎不续。","虽有场苗，室则靡粟。","罗雀务获，不言其多。","见彼渊鳞，或言其苛。","跣夫逐鹿，坐者食肉。","苟一需百，百尔莫足。","譬彼乘车，弗率坦野。","驱驰不已，或败尔马。","河有伏罟，蛟龙去之。","相彼有明，孰逢其灾。","前有鼓乐，后有寇盗。","方言方笑，不敢以告。","执鼠不力，或伤其手。","彼虎彼兕，矧不以走。","有蓬其树，其腹之枵。","岂不休息，维颠在朝。"]},{"t":"秋江词","f":"古风","c":["烟渺渺，碧波远，白露晞，翠莎晚。","泛绿漪，蒹葭浅，浦风吹帽寒发短。","美人立，江中流，暮雨帆樯江上舟，夕阳帘栊江上楼。","舟中采莲红藕香，楼前踏翠芳草愁。","芳草愁，西风起，芙蓉花，落秋水。","鱼初肥，酒正美，江白如练月如洗，醉下烟波千万里。"]},{"t":"瑶瑟怨","f":"五言古诗","c":["美人竹间亭，虚帘空月华。","相思湘江曲，泪竹生斑花。","花开为谁好，花落不复扫。","出户见春风，低头怨芳草。","坐弹五十弦，起视江月残。","愁弦不堪听，手涩金雁寒。","一弹正凄切，再弹转呜咽。","三弹拨幽肠，声乱冰丝结。","西风吹芙蓉，一夜落旧红。","岂知瑶瑟音，能消青镜容。"]},{"t":"竹枝词","f":"七言绝句","c":["十二峰头秋草荒，冷烟寒月过瞿塘。","青枫江上孤舟客，不听猿声亦断肠。"]},{"t":"平埧城南村三首 其一","f":"五言古诗","c":["朝出城南村，策马入荆杞。","村中八九家，烟火自成里。","儿童候晨光，稍稍荆扉启。","四邻务收穫，时复披草语。","眤眤何所云，但言好禾黍。"]},{"t":"平埧城南村三首 其二","f":"五言古诗","c":["秋阴结林霏，细雨洒茅室。","牧放止近郊，牛羊不相失。","广园散花林，平畴蔼风日。","长幼不出门，咸知恋俦匹。","喧喧车马中，徒为慕高秩。","悬舆当何时，可使志愿毕。"]},{"t":"平埧城南村三首 其三","f":"五言古诗","c":["沉沉古陂水，日暮寒更绿。","隔陂见居人，萝蔓缠草屋。","摘禾留客饭，采薪发秋木。","童稚持竹竿，雨中放鸡鹜。","区区化外国，犹得睹淳朴。"]},{"t":"发京邑四首 其二","f":"五言古诗","c":["驱车出郊门，杖策遵古行。","返顾望城阙，引领内怀伤。","崇京概霄汉，逶迤一何长。","双观临驰道，群宫俨相当。","迅飙激棂牖，游云起纵横。","汉道值全盛，缨緌烂辉光。","侧观青云士，鸣佩倏来翔。","梁生何慷慨，辽辽悲未央。"]},{"t":"渡河","f":"五言古诗","c":["夙征肇延津，明晨临大河。","洪源下积石，砥柱屹嵯峨。","渺渺梁宋区，汗漫纵经过。","自非陵与岸，于安障其波。","扬帆赴中流，四顾莽无涯。","崇云徂广泽，迅风夕吹沙。","积阴不可测，鱼龙偃相加。","前无千尺梁，一苇胡足誇。","人生寡恒居，奚异波上槎。","岂无舟楫志，漂泊当奈何。"]},{"t":"还至别业四首 其一","f":"五言古诗","c":["鸡鸣高树杪，狗吠墟里间。","家人望车徒，远客造门端。","入门问所亲，上堂叙悲欢。","行人暮饥渴，秉烛具盘餐。","明月照西户，三星烂中天。","出门践野草，白露倏已漙。","十年苦行役，兹夕方来旋。","宁知非梦寐，忽忽心未安。"]},{"t":"还至别业四首 其二","f":"五言古诗","c":["诘晨亲友至，筐榼携所需。","各言平生欢，念子久离居。","绸缪语未毕，展席临前除。","园荣亦已抽，况有盘中鱼。","人情倦怀土，富贵岂常于。","无为泥形迹，所愿恒相俱。"]},{"t":"还至别业四首 其三","f":"五言古诗","c":["依依入乡闾，惨恻历故疆。","行迈踰几时，所见忽以更。","成人匪故识，耆齿日凋丧。","平生所同欢，转盼殊存亡。","羁魂邈遐域，旅柩归中堂。","人命不相待，奄忽如朝霜。","抚事感今昔，喟然热衷肠。"]},{"t":"还至别业四首 其四","f":"五言古诗","c":["弭驾及春暮，比屋事耘耕。","时物展遐瞩，契我遗俗情。","故林茂以密，敝庐亦将成。","芳兰冒紫葳，园柳尚垂荣。","泽葵蔓废井，瓜田依故城。","策杖衡门下，仰偃遂平生。","所愿在怡亲，馀者奚足营。","世情恶衰歇，天道递亏盈。","驷马岂不贵，翻覆坐相倾。"]},{"t":"艳曲八首 其一","f":"五言古诗","c":["御沟连上苑，大道接平沙。","紫陌三千骑，青楼十万家。","城中杨柳树，风起暮飞花。"]},{"t":"艳曲八首 其八","f":"五言古诗","c":["高台临万户，朱构耀城隈。","共藉鸳鸯绮，双持鹦鹉杯。","春风楼下度，一夜百花开。"]},{"t":"拟古诗十八首 其十","f":"五言古诗","c":["圆如天上月，光辉尚当缺。","与君非一身，安能不乖别。","关山日悠远，举步难可越。","君如双车轮，妾心如车辙。","相随万里去，绕绕何时绝。"]},{"t":"咏怀十首 其一","f":"五言古诗","c":["北陆无淹晷，岁迈阴已长。","摄衣起中夜，凛凛悲严霜。","明月丽高隅，繁宿纵以横。","徘徊仰天汉，惋彼参与商。","形影永乖隔，万里徒相望。"]},{"t":"咏怀十首 其二","f":"五言古诗","c":["烈炎灼昆冈，乃辨金石坚。","金石有恒性，销铄讵能迁。","薪樗莫伤桂，刈萧毋及兰。","薰莸不同器，清淆本殊源。","君睹高翔翼，卑栖非所安。"]},{"t":"咏怀十首 其三","f":"五言古诗","c":["英英园中槿，朱荣媚朝阳。","朝阳倏西隤，朗月借其光。","驰辉难久耀，华陨不再扬。","番番白马郎，皎皎青楼娼。","容好岂足恃，相要在衷肠。"]},{"t":"咏怀十首 其四","f":"五言古诗","c":["积薪以待燔，畜裘以御冬。","为物贵及时，馀者安足庸。","金张藉地势，卫霍承华封。","冯生守穷巷，白首不见容。","贱者日迍邅，贵者日以崇。","邈彼天上京，玉宫阍九重。","高高不可测，欲往将何从。"]},{"t":"赠边子四首 其三","f":"五言律诗","c":["戎马暗中原，嗟此远行子。","遥遥赴城阙，戚戚望桑梓。","路阻难可通，河清讵能俟。","俛仰君父间，出处良在此。"]},{"t":"出城赠韩子","f":"五言古诗","c":["晨车去遥遥，将子城之隅。","城隅何所有，有荷复有蒲。","念当与子别，思心立踟蹰。","他人岂无友，非子谁为娱。","折荷勿涉水，涉水濡子车。","安得琼瑶华，采掇为子需。"]},{"t":"古怨诗五章 其一","f":"五言律诗","c":["陨叶辞旧枝，飘尘就岐路。","迟徊决绝意，言念平生故。","泥泥行间泥，零零蔓草露。","岂不畏沾污，为子无晨暮。"]},{"t":"送崔氏四首 其四","f":"五言古诗","c":["飘飘山上葛，累累田中瓠。","苟非同根蒂，缠绵安得固。","人情易反复，结交有新故。","嗟哉夙昔好，乖弃在中路。","明珠倘无因，按剑不我顾。","深言匪由衷，白首为所误。","亮君勖恒德，永副平生慕。"]},{"t":"青石崖栈","f":"五言古诗","c":["侧行青石栈，谁能久延伫。","断板连曳云，喷泉洒飞雨。","迅流西回激，峻坂东折屡。","隤岸互倾欹，危梁袅撑拄。","饮猿骇游鳞，立马接翔羽。","慎尔千金躯，永念垂堂语。"]},{"t":"盘江行","f":"七言古诗","c":["四山壁立色如赭，盘江横流绝壁下。","惊涛赴壑奔万牛，峻坂悬空容一马。","危丛古树何阴森，寻常行客谁敢临。","徭妇清晨出深洞，虎辟白昼行空林。","沉潭之西多巨石，短棹轻舟安可适。","日光射壁蛮烟黄，雨气蒸江瘴波赤。","土人行泣向我云，此地前年曾败军。","守臣秪知需货利，将士欲苟图功勋。","英雄谟策自有术，窜妇奸男何足论。","营中鼓角连云起，阵前临山后临水。","烹龙酾酒日酣乐，传箭遗弓尚惊喜。","战马俱为山下尘，征夫尽向江中死。","遂令狐豕成其雄，屠边下砦转相攻。","千家万家鸡犬尽，十城五城烟火空。","夕阳愁向盘江道，黄蒿离离白骨槁。","魂入秋空结怨云，血染春原长冤草。","只今夷虏来归王，高墩短堑俱已荒。","牧童驱羊上茔冢，田父牵牛耕战场。","惟有行人行叹息，闻说盘江泪沾臆。"]},{"t":"雨夕行","f":"古风","c":["城头雨脚黑不断，阶下冻潦流已满。","出门咫尺无所适，积雾连云接平坂。","城中佳人沈与赵，我忽思之费招挽。","赵子闭门卧不出，沈生冲泥来独晚。","临阶下马入我堂，琅琅高咏不可忘。","瑶徽浮尘为我拭，磁罂浊酒为我尝。","西邻彭生亦豪士，四壁风雨卧一床。","隔墙深夜呼即至，三人团坐倾壶觞。","须臾檐雨乱沾席，窗风萧萧动烟柏。","照夜青缸寒向人，促曙红垆暖留客。","请君再歌我击节，晨鸡已下西城陌。","呜呼人生欢乐难再来，古人满眼俱尘埃。","何况与子异乡域，此地相逢能几回。"]},{"t":"岁晏行","f":"七言古诗","c":["旧岁已晏新岁逼，山城雪飞北风烈。","徭夫河边行且哭，沙寒水冰冻伤骨。","长官叫号吏驰突，府帖连催筑河卒。","一年徵求不少蠲，贫家卖男富卖田。","白金纵有非地产，一两已值千铜钱。","往时人家有储粟，今岁人家饭不足。","饥鹤翻飞不畏人，老鸦鸣噪日近屋。","生男长成聚比邻，生女落地思嫁人。","官家私家各有务，百岁岂止疗一身。","近闻狐兔亦徵及，列网持矰遍山域。","野人知田不知猎，蓬矢桑弓射不得。","嗟吁今昔岂异情，昔时新年歌满城。","明朝亦是新年到，北舍东邻闻哭声。"]},{"t":"长歌行赠旺兄","f":"古风","c":["兄为吾祖之长孙，能将孝义持家门。","耕凿不随时俗改，衣冠颇有古风存。","我家东冈旧乡土，谷有田场桑有圃。","诸弟喧哗逐城市，兄也萧条守环堵。","仆僮驯雅妻更良，男女膝下皆成行。","女长适人止近里，男大为农不出乡。","只今汝年六十七，我翁为叔汝为侄。","岁时相看如父子，登堂过庭礼不失。","弟昔省兄尽兄欢，夜秉灯烛罗杯盘。","兄前劝饮嫂劝餐，留我一月相盘桓。","自从离兄仕都下，都城谁是悠悠者。","万户清晨霜满裘，九衢白昼尘随马。","朱门金锁午未开，我曹不敢骑马回。","此时吾兄正稳卧，日高户外无人催。","爱兄好静谢尘网，一卷道书常在掌。","托身未肯附年少，举手何曾揖官长。","顷来生事日看微，种麻自织身上衣。","少儿从学长干蛊，我兄心中无是非。","君不见人间岁月坐相迫，胡为东城复南陌。","兄今已作白头翁，弟亦长辞青琐客。","山中桂树况逢春，谷口桃花更照人。","花前树下一壶酒，弟劝兄酬不畏贫。"]},{"t":"玄明宫行","f":"古风","c":["君不见玄明宫中满荆棘，昔日富贵今寂寞。","祠园复为中贵取，遗构空传孽臣作。","雄模壮丽凌朝廷，远势连袤跨城郭。","忆昨己巳年来事，秉权自倚薰天势。","朝求天子苑，暮夺功臣第。","江艘海舶送花石，戚里侯门拥金币。","千人力尽万牛死，土木功成悲此地。","碧水穿池象溟渤，黄金作宫开日月。","虹蜺屈曲垂三梁，蛟龙盘拿抱双阙。","城中甲第更崔嵬，亲戚弟兄皆阀阅。","撼里歌钟宾客游，排门冠剑公卿谒。","生前千门与万户，死时不得一丘土。","石家游魂泣金谷，董相然跻叹堳坞。","宫前守卫无呵呼，真人道士三四徒。","石户苍苔生铁锁，玉阶碧草摇金铺。","星宫昼开见行鼠，日殿夜祷闻啼狐。","游客潜窥翠羽帐，市子屡窃金香垆。","桑田须臾变沧海，桃树不复栽玄都。","我朝中官谁最贵，前有王振后曹氏。","正统以前不得闻，成化之间未有此。","明圣虽能断诛罚，作新未见持纲纪。","天下衣冠难即振，中原寇盗时复起。","古来祸乱非偶然，国有威灵岂常恃。","玄明之宫今已矣，京师土木何时止。","南海犹催花石纲，西山又起金银寺。","君不见金书追夺铁券革，长安日日迎护敕。"]},{"t":"崔生行","f":"七言古诗","c":["崔生自返金陵谪，骑马复走长安陌。","时危颇负经济才，海内俱识文章客。","自从盗贼近神京，四海不见烟沙清。","黄河流血日惨怛，中原战骨霜纵横。","朔方兵马又已弱，天下财赋难尽榷。","书生不得言世务，大臣谁有匡时略。","我到长安访交友，子与河内犹相厚。","感君恋故有绨袍，吐胆倾心共杯酒。","六年更见玄都花，万事空伤蓟门柳。","河内忧时未解颜，子亦谈兵不辍口。","金矿玉璞隐光曜，紫气龙泉郁盘久。","议论反遭时辈忌，形容岂免流俗丑。","王良伯乐不在御，骅骝騕袅徒能走。","人言古人未可轻，古人往往皆无成。","子云老大不晓事，殷浩当时空有名。","事去惟应嗟白首，时来未必济苍生。","即今风尘尚澒洞，羽檄飞符递相送。","西北山河战角悲，东南天地军麾动。","江海未见鲁连耻，朝廷不闻贾生恸。","尘埃早知才质殊，霄汉况睹名声重。","閟宫清庙待琴瑟，大厦明堂要梁栋。","天生公等世所须，努力他时有大用。"]},{"t":"乐陵令行","f":"古风","c":["山东郡县一百八，无有一城无战场。","到今漂血成野水，如山白骨横秋霜。","云台功高将不收，投笔亦有书生谋。","黄金大印赐豪贵，白面岂得言封侯。","唐朝公卿集如云，平原太守名不闻。","二十四城见贼走，抗城乃是平原守。","君不见前者寇盗时，县吏州官各亡命。","北梁白马终日行，济上黄旗错相映。","不闻开门战，但闻开门迎，嗟乎，平原太守乐陵令。"]},{"t":"同崔子送刘以正还关中","f":"七言古诗","c":["燕川芳草歇已久，行子西行更回首。","骏马春停渭曲花，金鞭暮指秦中柳。","看君兄弟皆豪雄，十年侧想中丞公。","东山云月卧未起，北海宾客谁相通。","荷花初红酒初碧，汝归登堂见颜色。","若问长安旧友生，崔何二子常相忆。"]},{"t":"游猎篇","f":"古风","c":["周王八骏行万里，朝游昆崙暮沧海。","驱霆策电遍天地，虎骤龙驰倏烟霭。","奔戎造父两为佐，大人王母遥相待。","千金白狐来四荒，蝼蚁下国轻天王。","君不见秦皇叱咤役九有，海东驱石石为走。","桥边孺子如妇人，博浪沙中铁椎吼。","又不见武皇旌旗日络绎，射蛟浔阳江水赤。","五陵侠少夜相遇，探丸杀吏还惊辟。","天门嵯峨城九重，虎豹为卫蛟龙宫。","紫微钩陈翼帝座，至尊秪合安高崇。","脱渊之鱼出山虎，白龙鱼服何劳苦。","沉江距河势有然，万乘反遭匹夫侮。","君不见曹家老爽诚愚蒙，平生不识司马公。","死生祸福在人手，宁能常作富家翁。","一门流血岂足惜，坐使神器归奸雄。","昨夜昌平人梦天，龙文赤日绕燕川。","城中莫辩真天子，道上传看七宝鞭。","腐儒为郎不扈从，愿奏相如谏猎篇。"]},{"t":"点兵行","f":"古风","c":["先皇简练百万兵，十二连营镇京观。","团营十万更精猛，呜呼耗减今无半。","昨传胡入白杨城，有敕点选营中兵。","军中壮丁百不一，部遣老小从征行。","自从御马还内厩，私家马肥官马瘦。","富豪输钱脱籍伍，贫者驱之充介冑。","京师土木岁未已，一身百役无不受。","禁垣西开镇国府，内营昼夜罗金鼓。","四家骁健三千人，出入扈从围龙虎。","边头城堑谁营屯，遂使犬羊窥北门。","天清野旷恣剽掠，百里之内烟尘昏。","肉食者谋无远虑，仓皇调发纡皇顾。","即今宣府大失利，杀将覆军不知数。","辽东兵马久已疲，朵颜反复非前时。","又闻迤北外连结，朝廷坐失东藩篱。","往时京边士，苦乐今顿异。","且如私门卒，食粮日高坐。","此兵昨一出，见者泪交堕。","从今荷殳趋战场，身上无衣腹饥饿。","君不见府中搥牛宰羊猪，穿域蹋鞠行吹竽。","高马肥肉留京都，可怜此兵西击胡。"]},{"t":"平溪","f":"五言律诗","c":["徙倚平溪馆，天高秋气清。","水萤光不定，山籁响难平。","夜火云间戍，寒枫江上城。","终宵无梦寐，高枕听滩声。"]},{"t":"镇远三首 其二","f":"五言律诗","c":["地僻先摇落，空亭长绿莎。","山川连蜀道，市井杂夷歌。","旅箧衣裳少，秋程风雨多。","无人相问讯，尽日抚寒柯。"]},{"t":"夜","f":"五言律诗","c":["地远柴门静，天高夜气凄。","寒星临水动，片月向沙低。","入室喧虫语，张灯住鸟啼。","自然幽意惬，不是恋深栖。"]},{"t":"雨夜似清溪二首 其一","f":"五言律诗","c":["院静闻疏雨，林高纳远风。","秋声连蟋蟀，寒色上梧桐。","短榻孤灯里，清笳万井中。","天涯未归客，此夜忆江东。"]},{"t":"九日同马君卿任宏器登高四首 其一","f":"五言律诗","c":["岁岁重阳菊，开时不在家。","那知今日酒，还对故园花。","野静云依树，天寒雁聚沙。","登临无限意，何处望京华。"]},{"t":"客至","f":"五言律诗","c":["野外逢迎少，柴门落叶稠。","人闲不扫室，客到始梳头。","且为烹茶坐，还因看竹留。","登临如有兴，更上水边楼。"]},{"t":"西郊秋兴十首 其三","f":"五言律诗","c":["野屋清秋暮，寒沙易朔风。","岁年悲老树，岐路感孤蓬。","醉岂逃名士，狂非避世翁。","寻常门自掩，无客到山中。"]},{"t":"西郊秋兴十首 其四","f":"五言律诗","c":["旧家浉水上，门向钓台边。","近市来沽酒，中流坐放船。","蒹葭开晚照，洲渚接寒天。","渔父如相识，长歌过我前。"]},{"t":"西郊秋兴十首 其八","f":"五言律诗","c":["亭古枫杉落，缘溪不奈秋。","西风怯纤绤，细雨恋重裯。","双鹭寒窥井，孤鸿晚过楼。","白鸥还有意，相逐向吾洲。"]},{"t":"西郊秋兴十首 其九","f":"五言律诗","c":["严风日以发，落叶转纷纷。","远树斜衔照，寒山半入云。","步兵常嗜酒，水部本能文。","怅望千秋上，斯人亦不群。"]},{"t":"送吕子","f":"五言律诗","c":["京洛三年客，云霄万里违。","上书俱不报，解佩独先归。","北极临燕甸，南山绕汉畿。","相将未可料，岐路断蓬飞。"]},{"t":"顾九和内翰约看花城南寺病目不赴","f":"五言律诗","c":["不赴城南约，遥传寺里篇。","看花吾未老，出郭偶无缘。","簇马低春日，啼莺隔彩烟。","风沙开病眼，愁向艳阳天。"]},{"t":"闻雁","f":"五言律诗","c":["见汝今南下，怜予一望家。","乱声求侣急，高影背人斜。","月静林无叶，云寒菊有花。","万行关塞泪，秋日堕胡笳。"]},{"t":"玉泉","f":"五言律诗","c":["行游金口寺，坐爱玉泉名。","云去随龙女，风来动石鲸。","入宫朝太液，穿苑象昆明。","却望天河水，迢迢万古情。"]},{"t":"大祀","f":"五言律诗","c":["金榜星辰幕，瑶函海岳编。","受禧同汉室，登禅异秦年。","日抱龙旂转，天流羽盖旋。","杨雄老陪从，白首赋《甘泉》。"]},{"t":"苏子游赤壁图","f":"五言律诗","c":["垂老黄州客，高秋赤壁船。","三分留古迹，两赋到今传。","落日寒江动，青天断岸悬。","画图谁省识，千载尚风烟。"]},{"t":"送杨太常归省三首 其二","f":"五言律诗","c":["锦里趋庭日，声华冠蜀都。","弟兄今二妙，父子宋三苏。","礼乐风云地，旂常日月图。","今皇念大祀，未可滞江舻。"]},{"t":"送杨太常归省三首 其三","f":"五言律诗","c":["闻道西南寇，犹多虎豹群。","过秦应有论，谕蜀可无文。","未返巴山使，空悬栈道军。","烦将父老意，归报圣明君。"]},{"t":"汝庆宅红菊二首 其一","f":"五言律诗","c":["红菊开时暮，亭亭冠物华。","亦知颜色好，不是艳阳花。","罗绮娇秋日，楼台媚晚霞。","清香如不改，常傍美人家。"]},{"t":"秋夜","f":"五言律诗","c":["暝砌凝寒色，高楼闭绮栊。","露虫吟蟋蟀，风叶下梧桐。","此夜关山月，何人怅望中。","泠然感秋思，况复听征鸿。"]},{"t":"与孙戴张三子纳凉","f":"五言律诗","c":["薄暮携三子，追凉步短宵。","水边低出月，楼上忽横箫。","久露花沾湿，微风竹动摇。","醉歌聊永夕，坐待紫宸朝。"]},{"t":"出阁过勤甫省中","f":"五言律诗","c":["竹垣通左掖，花省接仙郎。","并坐停杯晚，高谈卷幔凉。","水阴沉绀殿，山影落雕墙。","愧我同朝客，传君寡和章。"]},{"t":"寄易内翰","f":"五言律诗","c":["日日望长沙，忆君城柳斜。","风尘愁燕雀，江海叹龙蛇。","公子天边草，夫人庙口花。","故乡杯酒罢，遥亦念京华。"]},{"t":"寄三子诗","f":"五言律诗","c":["鄠杜终南曲，邠岐渭北陲。","水多龙卧处，山有凤来时。","星宿中宵动，风云万里移。","沧江问灵剑，离合少人知。"]},{"t":"城东泛舟","f":"五言律诗","c":["水郭移尊宴，沙原列骑停。","岸开平放舸，林转曲通亭。","雨意云垂白，风情柳送青。","衣冠夕临泛，东望极沧溟。"]},{"t":"过宗哲故宅","f":"五言律诗","c":["过门犹宿昔，驻马复谁留。","雨院残春竹，风庭折晚榴。","还家无二顷，归榇有孤舟。","日暮邻人笛，凄然涕泪流。"]},{"t":"八月二十八日子容过对菊","f":"五言律诗","c":["近节逢花放，开尊集异乡。","乾坤共一笑，风雨似重阳。","谁识暮蝉意，独怜秋树芳。","它时益烂熳，邀尔醉西堂。"]},{"t":"汝济夜过同以行对菊","f":"五言律诗","c":["摇落相过地，芳菲晚更亲。","酒醺留媚眼，灯色笑生春。","风雨新晴夜，江山未老身。","百年如不醉，恐负此花神。"]},{"t":"长安柳","f":"五言律诗","c":["三月长安柳，春风吹暮天。","花飞御沟水，叶傍汉宫烟。","绕岸犹堪折，临流更可怜。","故园无限树，零落战场边。"]},{"t":"中元节有感","f":"五言古诗","c":["去岁中元节，朝陵百职同。","严趋神路左，遥拜孝园东。","龙虎瞻王气，乾坤仰帝功。","未回衡岳驾，空堕鼎湖弓。","启兆龟图顺，编年凤历终。","玉衣陈画幄，宝瑟閟玄宫。","北极犹前日，南薰亦旧风。","病居逢此日，长望五云中。"]},{"t":"武昌闻边报","f":"七言律诗","c":["传闻虏骑近长安，北伐朝廷已遣官。","路绕居庸烽火暗，城高山海戍楼寒。","一时边将当关少，六月王师出塞难。","先帝恩深能养士，请缨谁为系楼兰。"]},{"t":"长安驿","f":"七言律诗","c":["暮雨萧萧云黯然，数家山下起炊烟。","窗闻早雁秋多思，门对寒流夜不眠。","远使正持三楚节，旧游曾扣九江船。","驿程南去无穷路，来往风尘阅岁年。"]},{"t":"岳阳","f":"七言律诗","c":["楚水滇池万里游，使车重喜过巴丘。","千家树色浮山郭，七月涛声入郡楼。","寺里池亭多旧主，城中冠盖半同游。","明朝又下章华路，江月湖烟绾别愁。"]},{"t":"华容吊楚宫","f":"七言律诗","c":["别馆离宫纷绮罗，细腰争待楚王过。","章华日晚春游尽，云梦天寒夜猎多。","废殿有基人不到，荒台无主鸟空歌。","西江烟月长如旧，只有繁华逐逝波。"]},{"t":"秦人洞二首 其二","f":"七言律诗","c":["闻说秦人此避秦，碧桃零落旧时春。","家移洞里难知姓，水到人间易问津。","山色溪声自今古，石床涧户空埃尘。","洞前即是南征路，来往年华容鬓新。"]},{"t":"月潭寺二首 其二","f":"七言律诗","c":["绿萝阴下到蒲团，茗叶松花进晚餐。","近水云霞晴亦雨，傍岩楼阁昼常寒。","旅怀寥落逢秋半，僧话淹留坐夜阑。","惆怅尘踪又南去，朝来钟磬隔烟峦。"]},{"t":"月潭寺二首 其一","f":"七言律诗","c":["玲珑金刹白云边，踏阁攀林一径穿。","龙出洞门常作雨，鹤巢松树不知年。","僧来殿上鸣钟饭，客到山中借榻眠。","怪底夜来难得寐，秋风窗下绕流泉。"]},{"t":"云溪驿","f":"七言律诗","c":["云溪驿里经过处，六七年间两度行。","风土不殊初到日，雨墙难认旧题名。","异方见月思乡县，远客逢秋念友生。","明日巴陵江上酒，弟兄相对不胜情。"]},{"t":"病后","f":"七言律诗","c":["病后频惊节序过，不将风景怨蹉跎。","秋来门巷依枫橘，岁晚衣裳恋芰荷。","洛下闲居辞宦早，茂陵消渴著书多。","凤凰池上三年客，騕袅空鸣白玉珂。"]},{"t":"吹笛","f":"七言律诗","c":["横笛高城弄晚飔，碧空如水雁来时。","关山月落肠应断，楼阁秋生响易悲。","杨柳天边浑折尽，梅花江畔故开迟。","武陵回首南征路，一曲那堪马上吹。"]},{"t":"秋兴八首 其一","f":"七言律诗","c":["高楼一上思堪哀，水尽山空雁独回。","万里关河迷北望，无边风雨入秋来。","故人尺素年年隔，薄暮清砧处处催。","徒有寒樽对花发，病怀愁绝共谁开。"]},{"t":"过寺访以行","f":"七言律诗","c":["今年春色倍堪思，柰尔看春病起迟。","窗瞩太行云断处，坐闻江汉雁来时。","柳香渐扑燕姬酒，草色频催谢客诗。","更欲息栖寻野寺，细萝芳杜碧山期。"]},{"t":"题严内翰赐扇","f":"七言律诗","c":["端阳綵扇百官传，每岁宫臣赐独偏。","君去翰林供奉久，始来经幄拜恩年。","颁从殿阁风先动，捧向云霄月并悬。","象毂银镮倍光宠，好扬薰吹助虞弦。"]},{"t":"长安","f":"五言绝句","c":["白云望不尽，高楼空倚栏。","中霄鸿雁过，来处是长安。"]},{"t":"晚出左掖简薛君采二首 其二","f":"五言绝句","c":["露重芙蓉馆，云轻翡翠城。","文园病司马，消渴望金茎。"]},{"t":"独立","f":"五言绝句","c":["独立对秋阴，冥冥望河渚。","只见沙上烟，不见烟中雨。"]},{"t":"白雪曲十首 其三","f":"五言绝句","c":["暗逐梁尘起，潜随烛影流。","似怜歌舞处，故故入高楼。"]},{"t":"白雪曲十首 其五","f":"五言绝句","c":["梅花开雪中，相看斗奇绝。","常教雪似花，莫遣花成雪。"]},{"t":"诸将入朝歌十二首 其二","f":"七言绝句","c":["大将龙旗朝帝京，至尊亲遣贵臣迎。","侍中独领嫖姚部，战马皆归龙虎营。"]},{"t":"诸将入朝歌十二首 其九","f":"七言绝句","c":["阙下千官侍凤楼，苑中天子建龙斿。","豹房虎圈先班赏，武帐前边赐姓侯。"]},{"t":"诸将入朝歌十二首 其五","f":"七言绝句","c":["河北诸军尽有名，云中骁骑本轻生。","金装白马翩翩出，不见长安子弟兵。"]},{"t":"诸将入朝歌十二首 其十一","f":"七言绝句","c":["少年生长在边城，介冑南征虮虱生。","马上朝来横吹曲，梅花一半是吴声。"]},{"t":"送韩汝庆还关中二首 其二","f":"七言绝句","c":["华岳云台万里情，高秋落日眺秦城。","黄河一线通沧海，身在仙人掌上行。"]},{"t":"秋日杂兴十五首 其一","f":"七言绝句","c":["寒螀啼断槿园空，万树凋伤八月中。","只有南山苍桂在，一株花发向秋风。"]},{"t":"秋日杂兴十五首 其二","f":"七言绝句","c":["雨花风叶总堪怜，海燕江鸿各渺然。","莫向高楼空怅望，暮蝉多在夕阳边。"]},{"t":"秋日杂兴十五首 其四","f":"七言绝句","c":["紫蔓青藤各一丛，野人篱落管西风。","郊扉远绝谁能到，秋日虫鸣豆叶中。"]},{"t":"秋日杂兴十五首 其十一","f":"七言绝句","c":["柏林枫岸迥宜看，杨柳芙蓉不柰寒。","最爱高楼好明月，莫教长笛倚阑干。"]},{"t":"宫词四首 其三","f":"七言绝句","c":["微霜凄凄金井栏，城头月出冻云残。","玉楼高对蓬莱雪，谁道宫中夜不寒。"]},{"t":"田园杂诗二首 其一","f":"五言古诗","c":["习宦非我长，官久计转拙。","遭斥还田庐，获与初念协。","树艺良有期，农事固堪悦。","飘飘绿原风，皛皛明川月。","披襟恣吾适，既夏不知热。","回思行役日，寒暑靡得辍。","疏懒古虽鄙，任性亦可率。","膏畴矧丰蔚，积潦复凄冽。","白日皎在兹，停云静如结。","为谢二三子，努力慰衰劣。"]},{"t":"皇告","f":"古风","c":["八月至贵，其日载旸。","龙旂既翔，龙幄既张。","大小肃肃，乃于郊迎。","既召有众，播告在庭。","皇皇恤命，罔不是将。","嗟我贵庶，荼苦孰蠲。","既加斧斨，屡罹凶年。","眷兹皇仁，如天如春。","如草斯植，莫不敷宣。","蠢蠢苗民，浩浩炎边。","是俾是承，亦共戴天。","黑齿发椎，执弩被毡。","载歌且谣，皇帝万年。"]},{"t":"溵之水","f":"古风","c":["溵之水，可以方，可以舟。","子之归矣，可以斯游。","溵之水，可以河，可以海。","子之归矣，可以斯迈。","溵水有岸，白石有烂。","斯迈斯游，桨也永叹。"]},{"t":"中林之棘 送崔子也","f":"古风","c":["中林之棘，维桃与李。","阪田之特，生也曷以。","民之无俦，曷其有巳。","王事皇皇，驾言徂行。","念子出宿，我居??。","我心之迈，与子同征。","行野蹶蹶，行国迈迈。","无草不茂，无谷不溃。","民之瘁矣，心忧用喟。","彼鱼之罭，在彼河梁。","彼兔之罝，在彼河侧。","岂不是思，进退维亟。","同贾知贪，同食知甘。","予谅子怀，如口弗爽。","予之有怀，子岂不谅。","火之方殷，不戒胥燔。","水之方割，不戒胥溺。","火之方殷，乃仇扑灭。","水之方割，弃其舟楫。","有渰斯雨，有霰斯雪。","如履坚冰，乃尚思热。","众方媚矣，莫敢独说。","如处大厦，俟其颠覆。","谓人弗言，言成祸矣。","谓人弗职，职成过矣。","孰无朋友，倡谁和矣。","子曰弗仕，子有父母。","予曰弗仕，兄弟尤予。","天子则不罪，朋友弗取。"]},{"t":"原有楚 赠韩子也","f":"古风","c":["原有楚，隰有苦。","子车驷牡，驾言徂矣，见子之父。","原有杻，隰有蓼。","子军驷?，驾言游矣，见子之母。","原有桑，隰有唐。","子车驷黄，驾言行矣，见子之兄。","子涉渭矣，渭水浟浟。","我思见子，安得北流。","子涉渭矣，渭水沛沛。","我思见子，安得北逝。"]},{"t":"淮水 送张子也","f":"古风","c":["淮水汤汤，伐鼓镗镗。","之子南行，征夫不遑。","有翮者燕，集于堂巢。","我日不谒，而旬不朝。","征夫况瘁，谁使告尔劳。","谁经营四方，谁高门翱翔。","谁粲粲衣裳，谁饥渴载行。","辰月弗振，乾月维雹。","视天之威，伊胡云虐。","弗问则退，问言谁对。","敬我友矣，式相求矣。","询于道周，维教言是由。","母琐言是谋，母戏言是流。","桓桓之罴，免罹于罗。","如彼弋鸟，维恐不加。","无执猫狸，而舍彼虎豺。","我视人之疚，如灾我躬。","勿曰行弗动，勿曰言弗用。","曰我寡，惮彼有众。","矢时弗颂，维云讽矣。","伊谁之送，孝友张仲。"]},{"t":"秋风 讽也","f":"古风","c":["秋风厉厉，中园有卉。","不植松与桧，奈彼萧艾。","秋风飘飘，中园有条。","不植松与桥，奈彼艾萧。"]},{"t":"兴隆祀丁曲","f":"古风","c":["称朱竿，扬朱弦，鸣钟朗鼓各在悬。","月建酉，日次丁，牲全礼成告于庭。","久哉斯道沦以失，天启神圣我祖出。","用夏变夷四海一，遐土之人炳文质。","昔者子欲居九夷。","百世之下，乃享于兹。","猗与斯道，垂宪靡蹦遗。","浩浩皇皇，八荒九州。","罔或靡知，罔或靡由。","曷知曷由，我祖之休。"]},{"t":"罗女曲","f":"古风","c":["罗女年十五，自矜好颜色。","山叶杂山花，插髻当首饰。","蛮方立门户，男女多生涯。","昨闻城中市，女出男在家。","上市买黄丝，染缉作花布。","裙短衫袖长，不惜双脚露。","夜行山中道，何处吹芦笙。","我歌连臂曲，曲罢动郎情。","动郎情，与郎匹，生女复长男，三年始同室。"]},{"t":"落叶哀蝉曲","f":"楚辞体","c":["寂寥兮寒闺，空帷兮昼低。","若有人兮感罗衣，蒐恍惚兮往复来。","凉风飘飖兮吹玉阶，秋叶飒兮鸣蝉哀。","有鸟嗟嗟永进乖，双栖比翼兮何时谐。"]},{"t":"剡溪歌","f":"楚辞体","c":["溪之水兮幽幽，谁与子兮同舟。","舟行暮入山阴道，月濛濛兮雪皓皓。","千载重寻戴逵宅，溪堂无人夜归早。","乘兴而来兴尽休，君不见王子猷。"]},{"t":"悼远辞","f":"楚辞体","c":["矫矫龙蛇兮，没于泥沙。","嗟苦先生兮，独罹此。","嗟逴彼修路兮，骥骤不力。","美璞弗器兮，良田不食。","嗟苦先生兮，独罹此极。"]},{"t":"倚柱操","f":"楚辞体","c":["兔则有罝兮，鸟则有罗。","国无人兮，将奈何。","心之忧兮，岂曰予未有室家。","嗟嗟室家非我营兮，我生曷荣兮。"]},{"t":"战城南","f":"楚辞体","c":["战城南，戢不息。","朝战城南，暮哭城北。","积尸累累，肉腐鸟不食。","放马泽中，雪没马腓。","沙寒草枯，不得马肥。","北风夜吹，胡兵四围。","我欲上马，马瘦不驰。","我欲射箭兮，硬不开。","但语城中亲，汝出收我骸。","战城南，君莫悲。","猛虎啮人，翔于山垂。","欲食虎肉，不避虎威。","男儿立功，横行四夷。","生当公侯，死当白骨归。"]},{"t":"巫山高","f":"七言古诗","c":["巫山高极青冥间，翠绾参差十二鬟。","神女仙裙佩缨动，行云飞入荆王梦。","含情流盼轻烟中，玉床瑶枕荐君宫。","紫罗白縠垂香风，恍惚蒐散莫与同。","微霜销落高丘树，哀猿孤吟鸟双去。","荒淫沦灭竟何为，暮雨冥冥归古祠。"]},{"t":"芳树","f":"古风","c":["芳树离离，朱华而绿滋。","华滋虽云好，秋风暮来吹。","秋风不足恤，华滋亦有时。","嗟汝枝上鸟，汝去将安归。","美人何方至，贻我江上华。","秀彩夺人目，胡为在天涯。","天涯虽荣好，不如常在家。"]},{"t":"关山月","f":"古风","c":["关山月，夜照青海头。","白骨征人怨，红颜少妇愁。","少妇含嚬望月来，月明流影洞房开。","岁暮机中缣素出，夜寒灯下剪刀催。","年年捣衣明月秋，明月还随陇水流。","闺里空教看破镜，沙场不见大刀头。"]},{"t":"琳池歌","f":"古风","c":["木兰为楫，文梓为船。","青荷为盖衣红莲，宫娃侧坐挥繁弦。","凄风袅袅飘素秋，飞花委叶承波流，霜露夜下不可留。"]},{"t":"招商歌","f":"楚辞体","c":["高馆阒兮曲池通，乘舟夜逐荷叶东。","持荷作盖不障风，持荷作衣难为缝。","金琯玉凫响秋空，歌婉声长待夜终。"]},{"t":"公无渡河","f":"古风","c":["公无渡河，河浊不见日，汝今欲往何时出。","公无渡河，河广浩无涯。","往而不返，化为泥与沙。","夸父渴走成邓林，至今丘冢犹岑崟。","河中蛟龙见人喜，纵有舟楫谁救尔。","噫嗟嗟，公无渡河，渡河而亡，不如陆死噫。","嗟嗟公无渡河。"]},{"t":"明妃引","f":"古风","c":["明妃绝色世无邻，粉黛那数三千人。","咫尺宫门接前殿，君王只向图中见。","当时自恃如花容，美丑谁知由画工。","单于日近汉日远，万里风沙魂不返。","琵琶马上再三弹，翠袖朝啼关塞寒。","皓齿明眸葬胡地，千秋遗曲犹悲酸。","燕支暮云白浩浩，胡儿吹笳雪飞早。","山前孤冢高嵯峨，岁岁春风长青草。","古来抱节本难遇，况复蛾眉人所妒。","君不见长门宫，不用黄金买词赋，纵有朱颜君不顾。"]},{"t":"短歌行","f":"古风","c":["冉冉秋序，肃肃霜露。","蓄我旨酒，召我亲故。","鸟欢同林，水欢同源。","矧我同乡，胡能弗敦。","耀灵西藏，明灯在室。","更长夜良，可以继日。","园有艺菊，庭有树兰。","秋芳是悦，春荣曷观。","高陵可升，海水可测。","出门异路，安知南北。","生年几何，去者日多。","子不我乐，听我短歌。"]},{"t":"铜雀妓","f":"五言律诗","c":["墓田望不极，松柏夕离离。","存生有欢怨，亡没讵同思。","井干日已摧，穗帷宁复施。","衰荣互相谢，身后徒尔为。"]},{"t":"苦寒行三首 其一","f":"五言古诗","c":["天地黯闭塞，冰霜皓崔巍。","寂寥高城侧，郁律见古台。","烈风夜中起，飞雪千里来。","鸟羽沉不施，兽口噤不开。","虎豹敛穴窟，蛟龙俱冻埋。","六龙衔白日，寒苦光不回。"]},{"t":"苦寒行三首 其二","f":"五言古诗","c":["石裂南山下，水结中河流。","莽莽北郭外，死骨聚如丘。","贫士被毛褐，寡妇无完裯。","宁知贵公子，丝竹宴朱楼。","方辞白羽扇，更御青羔裘。"]},{"t":"苦寒行三首 其三","f":"五言古诗","c":["天风日夕厉，海水不扬波。","飞雪被千里，层冰白峨峨。","嗟汝穷阎人，无衣当奈何。","锦裘长安儿，白马鸣玉珂。","象弧插彫韔，射兽西山阿。"]},{"t":"塘上行","f":"五言古诗","c":["蒲生寒塘流，日与浮萍俦。","风波摇其根，飘转似客游。","客游在万里，日夕望故州。","鶗鴂鸣岁暮，蟪蛄知凛秋。","暑退厌絺绤，寒至思重裘。","佳人不与处，圆魄忽四周。","房栊凄鸣玉，纨素谁为收。","白云如车盖，冉冉东北浮。","安得云中雁，尺帛寄离愁。"]},{"t":"放歌行","f":"五言古诗","c":["天命谅靡易，富贵安足陈。","自昔慕豪胜，重义还轻身。","整辔逾巩洛，驱车入咸秦。","立观青云上，驰步要路津。","射策报明主，投书干大臣。","身为五侯客，家与七贵邻。","杯酒纵经过，冠盖罗逡巡。","顾盼生光彩，吹嘘借阳春。","各矜意气好，自比骨肉亲。","时事多变异，交道亦湮沦。","要盟等金石，弃掷同灰尘。","赤心不足恃，白头更如新。","归来嗜藜藿，偃仰随松筠。","始知葵槿甘，不若兰桂辛。","愿从白屋士，请谢玉堂宾。"]},{"t":"雁门太守行","f":"古风","c":["垒垒高山，莽莽代谷。","城边风起沙漠漠，城内惟闻奏胡乐。","太守下车，买牛息戈。","陶民礼义，朝弦暮歌。","北历黄沙碛，南游白草原。","五马何秩秩，朱英导文轩。","嗟哉太守亦孔武，时时较猎西山下。"]},{"t":"梁甫吟","f":"古风","c":["君不见泰山高高梁甫在其半，古来封坛禅地无宫馆。","崖崩壁坼铁锁断，秦碑汉碣何人看。","自从生人开九州，九十六帝行权谋，虎豹啖食龙蛇忧。","朝翻暮覆作云雨，立谈坐笑生戈矛。","鬼神来往仙不死，尘埃万变扶桑流。","君不见田疆论功争二桃，齐门三丘埋野蒿。","又不见鲁连辞赏轻千金，却秦救赵何雄豪。","眼前无人辨曲直，身后声名更何益。","拂袖空怜蹈海心，护车枉负排山力。","梁生五噫歌莫哀，东绝梁甫观蓬莱。","千年云开锦绣壁，五色日抱金银台。","瀛洲方丈列仙占，文成五利何能验。","徐生入岛竟不回，博士儒生尽坑堑。","我吟梁甫君振衣，世路崎岖多是非。","琅玕芝草海岱曲，钓竿拄杖从今归。"]},{"t":"采莲曲三首 其一","f":"七言古诗","c":["青荷昼舒白露睎，朱光照耀含素蕤。","绿房翠盖偃参差，红妆皓腕映涟漪。","齐声一气歌艳辞，桂舟兰楫纷屡移，佳人罗带宜风吹。"]},{"t":"采莲曲三首 其二","f":"古风","c":["岸上有柳，隰中有荷，舟中女儿胜吴娥。","为君先唱绿水歌，起揽长带垂纤罗。","鸳鸯双栖翡翠过，下渚日暮多风波，叶密花稀愁奈何。"]},{"t":"采莲曲三首 其三","f":"七言律诗","c":["急歌太短缓歌长，清风夕回素云翔。","双凫飞起向横塘，荷花不言空断肠。","明月宛转流四方，月中白露沾衣裳。","红颜青鬓安能常，万岁为乐莫相忘。"]},{"t":"白纻歌七首 其一","f":"七言古诗","c":["齐纨越罗霜雪辉，吴刀并剪为君裁。","鸣珰垂佩行相催，且步云馆升月台。","珠缨列座琼筵开，秦筝慷慨赵瑟哀，含凄敛叹君莫猜。"]},{"t":"白纻歌七首 其二","f":"七言古诗","c":["凤楼十二连绣衢，雕楹刻桷耀城隅。","朱檠绛蜡艳红蕖，金盘玉羞奉君需。","美人隔坐曳华裾，主称万年为欢娱，上客翠盖停踟蹰。"]},{"t":"白纻歌七首 其三","f":"古风","c":["千金买笑，万金买歌，明珠白璧岂足多。","长眉窈窕扬秀蛾，轻身起舞垂纤罗。","悲弦急管鸣相和，三星低户月沉波，银箭金壶奈夜何。"]},{"t":"白纻歌七首 其四","f":"七言古诗","c":["吴娥白纻为舞衣，镂花缀叶纷葳蕤。","青春烂熳白日辉，轻带一举长袖施。","皎如流霰随风飞，游龙宛转翔鹄回，倾城绝代人共希。"]},{"t":"白纻歌七首 其五","f":"七言古诗","c":["手中色丝旧所治，青红碧绿当自知。","众中不语心向谁，感君厚恩私念之。","东流之水不西驰，泰山在前不可移，红颜白首奚足辞。"]},{"t":"白纻歌七首 其六","f":"古风","c":["北里挝钟，东邻搥鼓，吴歈越吟鄞郸舞。","恩义如山金如土，遗簪堕珥不复数。","穷冬夜长乐未阑，流风回雪满楹前，不惜皎洁为君妍。"]},{"t":"白纻歌七首 其七","f":"七言古诗","c":["白玉锁闼黄金堂，兰烟蕙火薰象床。","雕屏罗列组帷张，繁膏列炬舒华光。","横箫挟瑟步曲房，朱唇素齿发浩倡，愿为比翼云间翔。"]},{"t":"苦热行二首 其一","f":"七言律诗","c":["火云峥嵘连赤阪，白日苦长不得冕。","庭前井乾生赭烟，炎埃昼起高塞天。","侯家阴洞带流水，纱帏白昼凄风起。","美人冰盘荐朱李，道上行人多渴死。"]},{"t":"苦热行二首 其二","f":"古风","c":["昼眠苦多蝇，夜眠苦多蚊。","炎霞热雾蒸絪缊，四体拘促何由伸。","仙人桂官接兰苑，下望青松踏幽巘。","我欲从之谅非远，尘世何堪遂仰偃。"]},{"t":"鸣雁行","f":"古风","c":["鸣雁鸣斯，其音嘹嘹。","江路远遥，念汝离漂。","鸣雁于飞，肃肃其羽。","遵彼脩渚，实维汝所。","洞庭增波，沙朔多风。","何宁往来，无恤尔躬。","飞斯鸣斯，求蒲与稗。","无俾霰雪，及尔游迈。","高山有石，高木有枝。","我思我朋，嗟哉可遗。"]},{"t":"行路难四首 其一","f":"古风","c":["床有织绮，箧有织素。","请君视绮还视素，怜新不如莫弃故。","樽中有酒盘有飧，听我为歌行路难。","众中欢乐多志气，岂知他人不得意。","白日有时不照地，安得保君常不弃。"]},{"t":"行路难四首 其二","f":"七言律诗","c":["天河荧荧西北转，织女牵牛不相见。","由来天上亦别离，何怪人间有悲怨。","世情磷薄恶衰贱，驾车骑马有人羡。","少年不得君爱惜，红颜胜人亦何益。"]},{"t":"行路难四首 其三","f":"古风","c":["高树鸟不集，常有东西南北风。","君子众所畏，好恶不合常相攻。","拔剑欲有边，前有虎兕后虺蜮。","抵节徒歌行路吟，高飞未有横天翼。"]},{"t":"行路难四首 其四","f":"古风","c":["我发行路歌，诸君请勿哗。","严冬霜雪虽可畏，三春草木自荣华。","人生富贵各有时，不劳辛苦更咨嗟。","百年冉冉宁复多，白日速如东流波。","眼中世事只如此，生前不乐将奈何。"]},{"t":"河水曲","f":"五言绝句","c":["河水何溅溅，暮采河边兰。","君随河水去，我独立河干。"]},{"t":"车遥遥二首 其二","f":"七言律诗","c":["寒鸡喔喔知夜半，邻翁舂粱妇炊饭。","仆夫闻鸡趋车起，欲明未明行十里。","火轮飞出扶桑霞，羲和骑龙鞭日车。","君看日亦无闲时，我车安得常在家。"]},{"t":"陇头流水歌三叠送刘远夫行 其一","f":"五言绝句","c":["我欲望长安，陇坂高蔽天。","陇坂高可陟，陇水鸣溅溅。"]},{"t":"陇头流水歌三叠送刘远夫行 其二","f":"五言绝句","c":["盘盘上陇车，斑斑下坂马。","我非虎与兕，使我行旷野。"]},{"t":"陇头流水歌三叠送刘远夫行 其三","f":"五言绝句","c":["长安有高楼，不见陇西州。","可怜陇头水，日夜东北流。"]},{"t":"下陵曲","f":"五言律诗","c":["上陵风以雨，下陵月星露。","不见西陵宫，但见松柏树。","朝行西山曲，暮至长安道。","长安车马多，风吹陵上草。"]},{"t":"直路行","f":"古风","c":["直路难行，直言难受。","邪径捷足，莠言悦口。","直言如矢，闻者畏惮。","如射曲巷，鲜不折干。","直路坦坦，不可避难。","大夫史鱼，死以尸谏。","汲黯抗言，不冠不见。","轮扁之言，桓公是悟。","焦不避烹，秦皇霁怒。","猛虎在前，不为我言。","虺蛇在后，不为我告。","二世自閟，遭害于宫。","虢君怒御，枕块道中。","不忍其惮，宁忍其乱。","苟畏尔耻，必视尔死。","如药弗溃，其疾必遂。","如矢不直，不能贯革。","小人恶直，君子是持。","神之听之，终获其釐。"]},{"t":"海山谣","f":"古风","c":["断鳌立浪海水裂，蜃鱼食日日五色。","海中灵气变莫测，白昼须臾风雨黑。","彭祖夭，巫咸灭，龙伯死，精卫绝，山亦可摇水可塞。"]},{"t":"黄头郎","f":"古风","c":["黄头郎，尔母侮。","殿上天子怜，府中丞相怒。","尔虽有铜山，运去铜如土。","黄头郎，尔母侮。"]},{"t":"黄鹄歌","f":"五言古诗","c":["请君勿諠哗，奉君黄鹄歌。","黄鹄一飞去，翱翔天之涯。","我欲玫此鸟，云中无网罗。","安得生羽翼，从彼凌丹霞。","山川辽以邈，不归当奈何。"]},{"t":"乌夜啼","f":"七言绝句","c":["哑哑乌啼宫井霜，残月半落明星光。","城头吹笳已复罢，宫中击鼓殊未央。"]},{"t":"采葛篇","f":"古风","c":["野风吹葛葛逾好，绾雾萦烟青袅袅。","溪回水白云石苍，石根吊蔓百尺长。","越妇腰镰赤双足，褰裳行歌入中谷。","朝日未出雾露寒，花繁叶密采掇难。","年年绩丝作絺绤，奉以服君君莫斁。","君知衣葛好，不知采葛苦。","白日畏逢蛇，月黑畏逢虎。","君不见吴王宫中细腰女，日向歌筵著白苧。"]},{"t":"霹雳引","f":"古风","c":["石湫黝黝黑云夕，蛟龙夜起随霹雳。","盘空殷地出绝壁，骤雨飘风怒相击。","空中将将下矢石，千戈万马俱辟易。","飞鸟堕地委如积，古桧长松尽遭劈。","吁嗟乎阿香深山巨海胡弗往，短蜮脩虺兼魍魉。"]},{"t":"处州别驾行","f":"古风","c":["处之地，山水回，处州别驾贤且才。","别驾来，邮吏驰，骑连连，鼓雷雷，城门大开别驾来。","别驾来，御驷马，双麾在前，高盖娜娜。","入有列戟，出有负弩，吁嗟别驾才且武。","江之水，去悠悠，两帆扬，别驾舟，处人来迎申人留。","嗟别驾，安以适彼，安以去我。"]},{"t":"种瓠词","f":"七言古诗","c":["种瓠东园内瓠叶，从风翻绿蒂飘长。","带素花密以繁虽，无百尺根枝蔓自。","缠绵雨露冒时泽，阳晖被朝暄窃比。","女萝草附身托高，垣绿畛齐结食岂。","贵充盘飧愿为连，理杯长以奉君欢。"]},{"t":"双燕篇","f":"五言古诗","c":["双燕何翩翾，飞去仍徊翔。","依依止画闺，缱绻鸣东厢。","昔来届阳节，今去易寒凉。","秖恐秋风高，海路多烟霜。","双飞入君户，双栖在君梁。","被蒙君仁惠，弹射不相防。","养雏毛羽成，送雏还故乡。","虽无黄雀报，岁愿巢君堂。"]},{"t":"去妇词","f":"古风","c":["袅袅竹竿，钓鲂及鲤。","鲂鲤可食，竹竿何以。","子有锦衣，莫忘布裆。","子有旨酒，莫忘糟糖。","贱姜嫁君，所期偕老。","红颜难长，倏已白首。","白首虽可出，不念红颜日。"]},{"t":"种麻篇","f":"五言古诗","c":["种麻冀满丘，种葵冀满园。","孤生易摇悴，独立多忧患。","当行思故旅，当食思故欢。","先机失所豫，临事徒嗟叹。","升萧艾乃至，锄桂致伤兰。","物理有相附，畴能识其端。","断金俟同志，抱玉难自宣。","交结良匪易，君当图未然。"]},{"t":"月食篇","f":"古风","c":["仲夏月食月半缺，仲冬月食食之既。","皇皇下民，亦孔之悸。","烨烨其魄，有物薄之。","彼盈而微，实度之宜。","今此下民，孰使告尔灾，嗟嗟亦悸孔哀。","有烈其风，自伊天阻。","云旗载扬，朦瞽奏鼓。","率彼下土，诉于帝所。","诉于帝所，光复于天。","光复于天，其明罔愆，照临尔下民。"]},{"t":"国士行","f":"古风","c":["漆身为厉，吞炭为哑。","更名入官，厕变形伏。","桥下虽不褫，雠魄犹得斩。","雠衣生有国士名，死为壮士哀。"]},{"t":"谁谓河广行","f":"古风","c":["谁谓河广，浊不见泰山。","盂水之清，可别媸与妍。","清浊苟异，小大安足言。","君子知之，众人皆茫然。"]},{"t":"下宫行","f":"古风","c":["下宫兵来围朔妻，置儿裤中儿不啼。","一索不得当再索，孤儿那可活。","嗟杵臼，尔为朔客我为友，立孤诚难死何有。","嗟程婴，女当徐死难当事，尔疆为难我为易。","千金诈卖赵氏子，真孤乃存杵臼死。","复赵社，婴刎头，报死者。"]},{"t":"易水行","f":"古风","c":["寒风夕吹易水波，渐离击筑荆卿歌。","白衣洒泪当祖路，日落登车去不顾。","秦王殿上开地图，舞阳色沮那敢呼。","手持匕首摘铜柱，事已不成空骂倨。","噫嗟嗟燕丹，寡谋当灭身。","光也自刎何足云，惜哉枉杀樊将军。"]},{"t":"君子有所思行","f":"古风","c":["猗，君子，有所思。","居高无民，不如守卑。","衣锦负薪，入市见?。","神龙在潦淖，反为鱼鳖讥。","凤凰不得地，翻身避群鸡。","骐骥虽能千里，逐鼠堂上不如狸。","丈夫秉性天所定，流俗是非何足移。","水中马与陆地之鱼，曷谓失所置能久须。","宁为地上特生之野草，不能为茂树负岩墙而居。"]},{"t":"燕衔泥","f":"古风","c":["君不见燕衔泥，为巢哺雏常苦饥。","雏有羽翼各自去，安能久在梁上飞。","丈夫出处亦如此，贫贱富贵皆人为。","燕衔泥，不虑哺雏劳，但虑众雏飞不高。"]},{"t":"养蚕词","f":"古风","c":["桑叶青，蚕始生。","桑叶莫莫，蚕白满箔。","今年女儿道蚕早，昼夜照蚕恐蚕老。","浮萍生叶麦落花，风檐缲丝斗鸣车。","君不见簇上蚕乾死，老蚕成蛾又生子。"]},{"t":"嗟哉行","f":"古风","c":["老乌能啄牛能触，嗟哉世人互倾覆，自彻其藩盗入屋。","同病者怜，同忧者叹。","枭子夺凤，众鸡不安。","何得同类反相残，彼梁可逝阱可避。","祸福由人岂天意。","君不见虎虽有爪鸿有翅。"]},{"t":"双雁篇","f":"五言古诗","c":["双雁云中来，雍雍扬鸣音。","念子中路散，一飞与一沉。","冥冥江湖道，思归苦不早。","昔为并栖禽，今为特飞鸟。","飘沙恋故浦，别流思故河。","奈何同沟水，翻作异派波。","鸟悲多苦音，客悲多苦言。","弦尔孤桐琴，操我双雁篇。"]},{"t":"莫罗燕","f":"古风","c":["罗雀莫罗燕，燕飞在高殿，殿高且深谁得见。","主人垂幕高殿中，燕来徘徊不敢通。","杨花落，燕出啄，童子张罗逐黄雀，黄雀入罗燕入幕。"]},{"t":"牧犊行","f":"古风","c":["黄牛遇虎南山下，夜见白石心中怕。","牧童牧犊畏虎欺，挽弓逻之不敢离。","削竹为簇蒿为箭，射虎恨不穿虎皮。","嗟汝虎尔勿欺我犊，我犊有日头生角。"]},{"t":"城略阳","f":"楚辞体","c":["扶风令，城略阳，贼来略阳令走藏。","扶风令为登城唤，抽刀誓众众不散。","三日抗城一日战，战不利兮生缚见，见贼骂贼危不变。","略阳城人尽为鬼，略阳令生扶风死，守臣上奏惊天子。","君不见扶风令死封公卿，嗟尔略阳之令胡为生。"]},{"t":"潘节妇","f":"古风","c":["二十君辞房，六十妾在堂。","红颜为妇白首孀，昔日抱女今已亡。","风火炎烟黑，邻里相救失颜色。","未亡之人安所从，义不避火天返风。","噫嗟嗟，妾虽有身君无子，身未化石心不死。"]},{"t":"高城行","f":"古风","c":["高城巀巀山百堵，白日树旗夜悬鼓，将军戒严太守武。","城下贼来，城上彀弩。","楼军转石，城人负土。","噫嗟嗟，城完家可全，城破家为虏。","传与城中人，但保城，莫闭户。"]},{"t":"南山篇","f":"古风","c":["朝采南山，白石盘盘。","风来吹葛，葛叶幡幡。","岂无枝蔓，念我本根。","翘翘栗薪，靡考谁爇。","缉缉葛丝，考则靡服。","筛筛涧鱼，在罶丽丽。","昔用为飧，今用为祭。","上陵折松，下坂折柳。","遥遥游子，勿以行久。","月不恒处，日则有酉。","瞻彼日月，思我父母。"]},{"t":"辕下驹","f":"古风","c":["辕下驹，鸣声一何悲。","岂无万里志，局蹐安能施。","诘曲羊肠坂，累累太行谷。","车轮不行白日殁，仰思玉山意超忽。","君不见八骏日行万里，驰烟掠景谁能拘。","吁嗟乎，辕不驹。"]},{"t":"武陵","f":"五言古诗","c":["武陵一何长，辽远不可测。","高林多悲风，惨澹日无色。","黄熊啼我前，白狐跳我侧。","蛟螭蟠深渊，下见奔云黑。","沙蒸水亦毒，我仆饥且踣。","辞家忽踰秋，适此万里国。","土风日以殊，川域邈无极。","伏波有遗响，吟馀转悽恻。","何因托横吹，一写千载忆。"]},{"t":"桃川宫四首 其一","f":"五言律诗","c":["神宫矗飞观，结构俯层丘。","上翳万年树，下映千尺流。","仙踪久已没，百代传其由。","荒涂横白云，寥寥安可求。"]},{"t":"桃川宫四首 其二","f":"五言律诗","c":["溪谷多青氛，朝暮不可知。","鸡鸣洞中树，轻暾散华池。","白石流丹液，灵葩耀朱蕤。","谁能学丹术，遂使尘网离。"]},{"t":"桃川宫四首 其三","f":"五言律诗","c":["石洞无遗构，空岩长松桂。","入深忽已阴，升高稍知霁。","山光晚多姿，谷响秋转厉。","缅怀避秦者，一往成永逝。"]},{"t":"桃川宫四首 其四","f":"五言律诗","c":["溪中何所有，磊磊多白石。","紫参生其阳，青松植其北。","远林商气清，绝巘夕光白。","何当发云奏，招我吹箫客。"]},{"t":"自武陵至沅陵道中杂诗十首 其一","f":"五言古诗","c":["承明播宸涣，西适蛮夷州。","艰哉武陵山，古道何悠悠。","狭谷不容幰，水中无行舟。","仰探虎豹窟，俯瞰蛟龙湫。","徘徊迟吾马，中心怀懔忧。","脩程尚延亘，我行何时休。"]},{"t":"自武陵至沅陵道中杂诗十首 其二","f":"五言律诗","c":["群山何逶迤，环峙如百城。","其上干青霄，其下浮云征。","出没千万态，倏忽殊阴晴。","抚兹豁心目，颇慰羁旅情。"]},{"t":"自武陵至沅陵道中杂诗十首 其三","f":"五言古诗","c":["亭午入大谷，烈阳经中天。","树木多郁蒸，石坼起焦烟。","屈地饮我马，数尺不得泉。","仆夫告饥渴，挥汗堕马前。","安得万间厦，坐使清风延。"]},{"t":"自武陵至沅陵道中杂诗十首 其四","f":"五言律诗","c":["暮投界亭驿，候吏迎我前。","息徒茂林侧，饮马山下泉。","落日四岩阴，馀映高树颠。","坐久吏人散，浊酤聊自延。"]},{"t":"自武陵至沅陵道中杂诗十首 其五","f":"五言古诗","c":["驱马山上行，山高何巍巍。","修阪接飞翼，百步仍九回。","俛视烟霭中，众山郁何垒。","茫然望四海，万物亦已衰。","昔我别京国，朱华犹未希。","岁节忽复易，何时当旋归。"]},{"t":"自武陵至沅陵道中杂诗十首 其六","f":"五言古诗","c":["大壑百馀尺，流水浩汤汤。","我行路中断，欲渡无桥梁。","谁为理舟楫，石乱不可航。","改辙上危栈，登兹千仞冈。","临深古有戒，侧足以傍徨。"]},{"t":"自武陵至沅陵道中杂诗十首 其七","f":"五言律诗","c":["丛薄被烟皋，径路纡且微。","秋风振乔柯，绿叶渐以稀。","日入群动息，林深众响归。","君看栖枝鸟，大小必相依。"]},{"t":"自武陵至沅陵道中杂诗十首 其八","f":"五言古诗","c":["山深多树木，百里人民稀。","时有四五家，茅茨隔山陂。","沙田不可耕，何以禦岁饥。","门前数亩园，秪收蓬与藜。","平明出汲涧，薄暮始得炊。","童稚那敢出，但畏逢虎罴。","草黄纳晚禾，桑绿催官丝。","嗟尔远方人，辛苦谁具知。"]},{"t":"自武陵至沅陵道中杂诗十首 其九","f":"五言古诗","c":["山势行转促，连峰相贯输。","窈然林莽中，乃复得坦途。","青壁结烟霭，缥缈凌虚无。","层阿秀嘉禾，下覆清水渠。","夙志好幽僻，览兹耳目娱。","公车虽少延，顾盼忽已踰。","安得鼓清瑟，日坐山之隅。"]},{"t":"自武陵至沅陵道中杂诗十首 其十","f":"五言古诗","c":["谷转冈渐平，策驾循陂陁。","遥望辰阳城，枕山带长河。","飞甍若鳞次，居人亦何多。","按节驻江馆，登眺崇山阿。","南衢闻夜弦，北里杨朝歌。","谁云接夷域，文物殊中华。"]},{"t":"怀化驿芭蕉","f":"五言古诗","c":["芃芃芭蕉叶，植此园中央。","繁绿布重幄，层阴盖高堂。","孟夏日初赫，萧森蔽炎光。","众宾御华馆，四座借虚凉。","四序互更谢，南陵回朱阳。","穷秋多风雨，寒冬多雪霜。","危丛旦夕茂，绿叶日夜黄。","本无松柏固，安用誇其长。","徘徊视草莽，零落同一伤。"]},{"t":"花崖梧桐","f":"五言古诗","c":["桐生何猗猗，其叶何油油。","白云荫崇阿，朝日照高丘。","感此雨露滋，愧彼蔓草俦。","凤凰久不至，琴瑟谁可求。","吾将縆繁弦，庶以宣我忧。"]},{"t":"清平令","f":"五言古诗","c":["清平县之令，不识何为者。","庭前长野桑，庭后长山槚。","猛虎上我城，青狨啼我舍。","昨日出城去，骑马到部下。","部民道遮之，持刀杀其马。","入门顾妻子，所居无完瓦。","秋风吹树木，白日落原野。","永夜空城中，哀哀泪如泻。"]},{"t":"平越","f":"五言古诗","c":["清晨发平越，雾暗山益密。","仆夫各相戒，路远恐迷失。","薄午游气清，参差众峰出。","鸡鸣溪谷中，始见崖上日。","云叶分杳冥，高原被华实。","秋风起丛林，兴怠乃非一。","悠悠远行游，历险难具述。"]},{"t":"新添","f":"五言古诗","c":["朝登七盘坡，复下九折坂。","长风飘落日，杳杳前山晚。","佂夫行取薪，夜入涧中饭。","仰视飞鸟还，载观浮云卷。","还顾望乡邑，日与亲爱远。","公家尚有程，安能速言返。"]},{"t":"普定","f":"五言律诗","c":["鼓绝掩山城，空堂思超忽。","孤灯明夕帷，悄悄凉风发。","落叶何飘萧，飞萤互明没。","客窗临古寺，坐待微钟歇。"]},{"t":"城南妇行","f":"五言古诗","c":["城南有寡妇，见客泣数行。","自言良家女，少小藏闺房。","青春娇素手，白日照红妆。","父母偏见怜，嫁我不出乡。","前年弥鲁乱，腥秽入我堂。","弟兄各战死，亲戚俱阵亡。","嗟哉华艳质，忍耻罹凶强。","忧愁云发变，辛苦朱颜伤。","昨闻故夫在，息消通两方。","百金赎我身，三年归旧疆。","归来门巷异，人少蓬蒿长。","转盼夫亦死，儿女空在傍。","薄田无耕犊，寒腊无完裳。","人生固有命，妾独遭此殃。","况复官军至，烧焚庐井荒。","主将贪贿赂，百死不一偿。","朝廷自有法，出师亦有名。","妾身何足道，无乃乖天常。"]},{"t":"平夷二首 其一","f":"五言律诗","c":["滇南八月中，绿林何萋萋。","居人亦相辏，数里闻鸣鸡。","路转无诘曲，山行少攀跻。","回瞻贵阳道，咫尺蹊壑迷。"]},{"t":"平夷二首 其二","f":"五言律诗","c":["夜宿平夷馆，风悲气始凄。","月光皎东壁，白露寒螀啼。","凭高视中原，但觉众星低。","长路心益壮，浩歌天之西。"]},{"t":"涪万","f":"五言古诗","c":["孟冬气始萧，叶落北风凉。","寒水敛沟壑，馀辉照桥梁。","方舟下涪万，所历非一疆。","崇朝越千里，川涂渺苍苍。","浮云带城邑，壮丽逶且长。","况多古人迹，览之心慨慷。","登游岂不美，滞淫非我乡。"]},{"t":"泊云阳江头玩月","f":"五言古诗","c":["扁舟泊沙岸，皓月出翠岭。","开窗鉴清辉，照我孤烛冷。","高林散疏光，远渚接馀景。","纵横银汉回，三五玉绳耿。","弦望几更易，客行尚殊境。","佳期邈山岳，端坐令人省。"]},{"t":"涿鹿道中","f":"五言古诗","c":["高城郁莽苍，永路多荆棘。","日气夕冷阴，游氛浩无极。","城边古时丘，宿草蔓于域。","树木何萧萧，狐狸鸣其侧。","访古思轩辕，嵚崟何由陟。","伊昔奋龙战，明明庶邦式。","神驭飘鼎湖，乌号缅玄德。","遗踪迈荒野，盛烈存兹国。","谁云戡乱功，不俟干戈力。","风云变俄顷，明晦古难测。","薄暮穷林中，惄焉长太息。"]},{"t":"渡白沟","f":"五言律诗","c":["春行伤旅思，单车怅蹉跎。","晨眺黄金台，夕渡白沟河。","求贤不可见，血战竟如何。","落日古原下，悲风入浩歌。"]},{"t":"丛台","f":"五言律诗","c":["邯郸多侠士，赵地产名娼。","日夕高台上，欢宴殊未央。","黄金饰舞榭，白璧缀砍梁。","安见千年后，空令春草长。"]},{"t":"五平五仄体","f":"五言律诗","c":["秋原何萧萧，耳目去杂茸。","枯荷犹穿塘，苦瓠尚抱陇。","寒风吹空林，落日照古冢。","徘徊观陈踪，露下发忽竦。"]},{"t":"迎霜降","f":"五言律诗","c":["烈风扬云旗，鼓角悲广路。","庭前玉树枝，昨夜微霜度。","幽人蹑葛屦，出户履寒素。","胡当戒坚冰，及此岁将暮。"]},{"t":"冬雨率然有二十韵","f":"五言古诗","c":["北风吹零雨，冬热雪不作。","二仪黯澹交，百川莽回薄。","沙霾翳白昼，远望何由豁。","六龙堕青冥，万象沦玄朔。","羲和扶日行，纡辔竟焉托。","神娲补天裂，鍊石恐遗落。","雨伯谁为诛，云师尔何恶。","前者十月交，震雷轰城郭。","岸条俱含柔，园卉乱吐萼。","农家忍朝饥，岁暮食篱雀。","岂无数亩禾，狼籍委秋雹。","徵求皮肉尽，枯骨待削剥。","妻孥在眼前，四季不得乐。","胡因见阳春，所虑转沟壑。","閒居值泥淖，展瞩翻萧索。","虽无长者辙，自闭寒士阁。","长阴下脩麓，暝色起孤岳。","喧啾后栖鸦，怅望暮归鹤。","世途纷转蓬，生计倚丛藿。","永怀昔人驾，冥心付寥廓。"]},{"t":"发京邑四首 其一","f":"五言古诗","c":["弱冠游皇邑，抽翰预时髦。","出入承明地，四海皆同袍。","浮岁奄七徂，徇名虚所遭。","夙痾纠纤质，褊性惮形劳。","驾言返初服，行矣遂林皋。","转蓬恋本根，羁鸟思故巢。","自顾无脩翼，安能久游遨。"]},{"t":"发京邑四首 其三","f":"五言古诗","c":["亲交远集送，敛策西山阴。","前瞻太行道，却顾上苑林。","青阳蔼废墟，春气感鸣禽。","所遇岂殊故，即事自成今。","平时等荣乐，一旦异浮沉。","昔者同袍友，邈若辰与参。","山海去靡极，年运日相寻。","仓卒杯酒间，宁不伤离襟。"]},{"t":"发京邑四首 其四","f":"五言古诗","c":["行迈越长甸，历历怀苦辛。","岖嵚陟丘陇，髣髴望郊闉。","墟里接鸡犬，井邑无閒人。","暄阳入广陌，膴膴周原新。","百城岂不美，风土非我邻。","遥遥盼乡域，言念故所亲。","代越各有性，所愿还其真。","胡为去桑梓，郁郁冒风尘。"]},{"t":"许下","f":"五言古诗","c":["伊昔炎汉季，西京方遘患。","宫室烧燔尽，乘舆播草间。","劫迁留兹域，荆棘满颓垣。","横流一以滥，大厦宁复元。","豺虎互驰噬，鸱鸮厉飞翻。","日月屡薄食，风云变无端。","嗟哉众君子，杖策起周旋。","荀公诚伟士，弘思济其艰。","陈琳自南至，王粲亦西还。","从戎藉雄辩，腾步有荣观。","良蹇岂同御，凤鹜不共餐。","功名安足为，明义乃高贤。"]},{"t":"七夕二首 其一","f":"五言古诗","c":["逝节忽不处，佳夕复我临。","神飙汎光蕙，渥露沾华林。","缅彼牛女会，兹端竟难谌。","形影憯相望，胡由接徽音。","飘飖翠龙驾，髣髴青瑶簪。","长河坐移转，素波敛西沉。","灵彩欻以晦，游云起层阴。","同欢恋胶漆，异处悲辰参。","翘思慕远匹，感此涕流衿。"]},{"t":"七夕二首 其二","f":"五言古诗","c":["举俗慕良旦，好尚各有趋。","高楼曝纨绮，贫女无缯襦。","移时曜灵没，素月复已舒。","群居侈欢宴，长坐独愁吁。","愁吁亦何为，同裯与我殊。","春徂秋未返，膏沐谁为娱。","仰视河汉女，相违复来俱。","要知比翼乖，各阻天一隅。","乖离有重觏，母使寸心渝。"]},{"t":"水曲纳凉","f":"五言古诗","c":["乘月玩清夜，漱流涤烦痾。","竹柏夹脩水，微风扬泽荷。","苔阴皓露溽，素鳞跃于波。","柔条纷敛结，劲叶亦陨柯。","优游荡情志，俯仰丘中阿。","虽无朋侪和，兴言自成歌。","娱乐当及时，千秋岂复多。"]},{"t":"杂诗二首 其一","f":"五言古诗","c":["西陆移脩晷，素节多寒阴。","端居屏营虑，凄气惨人心。","浮飙委时卉，零露伤青林。","仰见孤雌翔，玄鸟无遗音。","蟋蟀何愁苦，终夜长哀吟。","感物兴慨叹，忧思孰能任。"]},{"t":"杂诗二首 其二","f":"五言古诗","c":["驰辉在西山，返景流东隅。","群欣被光灼，何能待须臾。","重阴肃万物，树木日夜疏。","丛蕙植幽闼，含荣耀前除。","佳人眇云端，何由致区区。","常恐霜霰至，委弃不我需。"]},{"t":"六子诗六子者皆当世名士也予以不类得承契纳辅志励益者多矣病归值秋寤叹中夜有怀良友作六子诗","f":"五言古诗","c":["王君青云姿，志岂屑丘壑。","名家出杜鄂，少日游宛洛。","奋身匹文鹓，战羽巢鸾阁。","兴文烛雕龙，挥翰凌玄鹤。","雅志在四海，随时偃经略。","驰情继谢眺，日晏吟红药。"]},{"t":"康脩撰海","f":"五言古诗","c":["矫矫龙头士，胜跃在明时。","群游慕豪放，栖志固有期。","赤骥鸣烟霄，不受黄金羁。","挥毫御清宴，浩思随风飞。","镫前激高倡，顾盼孰与希。","究古摘遗编，颇好班马辞。","良史久无称，斯文当在兹。"]},{"t":"何编脩瑭","f":"五言古诗","c":["中州产名俊，河内天下士。","平生饱藜藿，学道历壮齿。","至朴敛华蔚，徽文陋雕绮。","守渊安可窥，驰辩讵能止。","洞悟超先几，微言析玄理。","曲高难为和，行独寡知己。","古辙多蓁芜，非君谁予起。"]},{"t":"李户部梦阳","f":"五言古诗","c":["李子振大雅，超驾百世前。","著书薄子云，作赋追屈原。","新章益伟丽，一一鸾凤骞。","华星错秋空，爝火难为然。","摛文固无匹，投义罕比肩。","抗志冀陈力，危言获罪愆。","握瑜不得售，宝弃谁为怜。","仲舒贬胶西，贾生亦南迁。","古来有遗愤，非君独哀叹。"]},{"t":"边太常贡","f":"五言古诗","c":["世士多戚促，器识寡萧散。","太常何瑰玮，坦然破崖岸。","祥烟拂瑶坛，瑞日转华观。","出入谐鹓鸾，颉颃在霄汉。","芳词洒清风，藻思兴文澜。","阳春诚独步，清庙独三叹。","金奏响不亏，玉树开逾灿。","闲居检遗篇，启箧得尔玩。"]},{"t":"王职方尚綗","f":"五言古诗","c":["职方吾益友，契谊鲜与同。","少龄负奇气，万里飘云鸿。","手中握灵芝，高操厉孤桐。","读书迈左思，识字过杨雄。","为辞多所述，结藻扬华风。","寸心素相许，抚志惭微躬。"]},{"t":"十三夜对月","f":"五言古诗","c":["閒居爱明月，良节复与俱。","金魄丽秋闉，皓彩扬云衢。","澄空敛霜烟，清飙荡中区。","徘徊广庭内，改席临方除。","顾景怵衷虑，兴心念居诸。","天道递消长，戒之在须臾。","怀谦可久安，盛满岂恒居。","孰云质靡盈，所贵光不渝。"]},{"t":"十四夜同清溪子对月","f":"五言古诗","c":["林塘枉佳客，待月欣举觞。","今夕胜昨夕，已见生东方。","离离绛霄侧，冉冉素云扬。","踰时灏气澈，县耀天中央。","仰视渺难即，忽觅在我傍。","清池含微波，左右浥流光。","月行固当望，人会何能常。","与子各乡域，邂逅临此堂。","良时不屡值，明月安可忘。","醉歌荅永夕，和我窈窕章。"]},{"t":"十五夜高铁溪同沈清溪赵雪舟马百愚过敝居对月","f":"五言古诗","c":["端居抚盛节，眷兹金素中。","上客弭飞盖，惠然慰幽衷。","圆景舒东隅，忽复周层空。","重轮烂五色，缤纷结文虹。","流辉接瑶席，绛气郁以葱。","众宾侈佳玩，联篇挹华风。","情好在明月，安问膳靡丰。","弦望有恒度，明阴变无穷。","人生非比翼，岂得常相同。","所愿御此觞，聊以娱夜终。"]},{"t":"十六夜月","f":"五言古诗","c":["日夕城烟敛，列宿出复多。","开轩望明月，展席流素波。","圆辉虽少亏，犹能遍天涯。","单居不为乐，念远徒咨嗟。","美人越崇京，高楼结绮霞。","浮云暮长征，何由睹光华。","迅飙万里至，霜雾日以加。","坐忧桂枝歇，委落同泥沙。","清辉苟相照，岂虑天路何。"]},{"t":"十七夜月二首 其一","f":"五言古诗","c":["夕望月已减，云飙荡其侧。","月减不足忧，盈虚本相值。","胡为蔽氛霾，坐使清光匿。","踟蹰久延待，惨景郁无色。","灯前理鸣弦，瑶徽为谁拭。","思我平生友，道远不可即。","素书委箧笥，安得云中翼。","沧海多波涛，长阴浩难测。","何当广馀辉，一照万里域。"]},{"t":"十七夜月二首 其二","f":"五言古诗","c":["更深月复明，扬秀青云端。","浮飙倏以寂，长川静波澜。","徘徊广除下，白露栖崇兰。","仰见城西楼，回光照文轩。","楼中织绮女，延颈独哀叹。","哀叹未终已，素河横西山。","逝魄不长望，玉貌宁久妍。","君母吝光惠，使我芳岁阑。"]},{"t":"捣衣","f":"五言古诗","c":["凉飙吹闺闼，夕露凄锦衾。","言念无衣客，岁暮芳寒侵。","皓腕约长袖，雅步饰鸣金。","寒机裂霜素，繁杵叩清砧。","哀音缘云发，断响随风沉。","顾影惜流月，仰盼悲横参。","路长魂屡徂，夜久力不任。","君子万里身，贱妾万里心。","灯前择妙匹，运思一何深。","裁以金剪刀，缝以素丝针。","愿为合欢带，得傍君衣襟。"]},{"t":"悼往","f":"五言古诗","c":["行云不归山，逝水难重回。","与子一为别，流光倏如推。","形神往无存，梦想弗克谐。","孤冢日荒秽，幽泉翳穷埃。","重扃一以闭，千秋宁复开。","时至展遐沉，倾醑浇黄菜。","还思平生居，岁久生夕苔。","寒风吹空闺，彷佛鸣玉哀。","人生重恩义，况兹比翼乖。","何能眷新欢，弃掷故所怀。"]},{"t":"赠望之五首 其一","f":"五言古诗","c":["遥遥京洛客，承命发华辀。","朝辞冀州野，夕泛黄河流。","双旟翔汝侧，驷马登故丘。","故丘郁以长，冈陇茂松楸。","车徒耀城郭，亲戚迎道周。","丈夫事四方，州闾宁久留。","王程在须臾，顾念但怀愁。","前有盈觞酒，为我且绸缪。"]},{"t":"赠望之五首 其二","f":"五言古诗","c":["清晨送远人，弭驾北城隈。","北城一何脩，前临古时台。","俛仰故乡域，一如平生怀。","季冬严风发，积雪皑皑皑。","念子徂远路，郁结不能开。","中林寒卉寂，树木何摧颓。","安得春华敷，采掇以相贻。"]},{"t":"赠望之五首 其三","f":"五言古诗","c":["驱车策良驷，北上遵太行。","升高睇崇京，宫观郁相望。","前瞻碣石湍，俯见东海疆。","壮观局宇内，高志何激昂。","孤鸿暮南翥，奋翅起随阳。","黄鹄游四海，湖为悲故乡。","何能有羽翼，从子俱翱翱。"]},{"t":"赠望之五首 其四","f":"五言古诗","c":["昔子当北徂，值予复南旋。","相违踰几时，世事倏推迁。","访旧半存亡，谁能不摧颜。","浮云岁暮征，馀曜御西山。","居人念川涂，行子恋乡关。","平生双龙剑，乖别何时还。","志士重明德，穷达奚足叹。","愿君勖令名，相期在盛年。"]},{"t":"赠望之五首 其五","f":"五言古诗","c":["人生寓大块，聚散如飙尘。","昔为同裯好，今为异乡人。","孤兽鸣索偶，翔鸟求其群。","恋故各有慕，何况脊肉亲。","子当被华绂，结束事明君。","我当守蓬室，聊甘贱与贫。","去住各努力，良觌会有因。"]},{"t":"除夜二首 其一","f":"五言古诗","c":["今夕复何夕，偃仰兹岁周。","恋膏耀室隅，中馈进芳馐。","虽无车马客，亲戚自相酬。","游鱼安深渊，翔鸟止故丘。","所欢在桑梓，馀者何复求。","逝节不重至，来者难预谋。","长跪奉此爵，延年乐千秋。"]},{"t":"除夜二首 其二","f":"五言古诗","c":["閒居知时节，习静观卷舒。","日月无恒处，念往寡欢娱。","岁徂浮云阴，积雪皓中衢。","豫章产江滨，孤蕙敷山隅。","芳烈虽靡亏，遐远宁见需。","所愿勖明德，庶以酬居诸。"]},{"t":"艳曲八首 其二","f":"五言古诗","c":["日出洛城里，歌钟起四邻。","朝游桃李蹊，暮踏车马尘。","游丝罥白日，冉冉愁阳春。"]},{"t":"艳曲八首 其三","f":"五言古诗","c":["秦氏字罗敷，冯家名子都。","妆成临劝酒，曲罢坐当垆。","白马金吾子，青丝提玉壶。"]},{"t":"艳曲八首 其四","f":"五言古诗","c":["明姿称二八，生长紫罗帷。","对客舞垂手，邀人看画眉。","今朝仲春日，照影临芳池。"]},{"t":"艳曲八首 其五","f":"五言古诗","c":["粲粲东城子，盈盈南陌姝。","自矜夫婿贵，翻笑使君愚。","日暮采桑去，空回五马车。"]},{"t":"艳曲八首 其六","f":"五言古诗","c":["翩翩五陵儿，藉绮冠华簪。","常怀双宝剑，讵惜千黄金。","驰马章台下，红尘不可寻。"]},{"t":"艳曲八首 其七","f":"五言古诗","c":["兰灯列满座，繁炬灼朱光。","富贵倾南国，佳人出北方。","画堂翡翠帐，夜夜郁金香。"]},{"t":"拟古诗十八首 其一","f":"五言古诗","c":["冉冉岁逾迈，念君长别离。","别离在万里，道远行不归。","鹣鹣慕俦匹，鸾鸟东西飞。","思展双羽翼，奋起凌天涯。","向风长哀吟，欲举中徘徊。","川途浩无轨，霜雪怆以悲。","愿因驻驰景，得觐君光仪。"]},{"t":"拟古诗十八首 其二","f":"五言古诗","c":["婉㜻城东姝，怀春一何早。","朝游采桑陌，暮止垂杨道。","自矜全盛时，复恃颜色好。","玉貌随年化，安得不枯稿。","昔为园中英，今为路傍草。","路傍多车马，采掇难自保。"]},{"t":"拟古诗十八首 其三","f":"五言古诗","c":["名都有高楼，上入青云端。","脩城延曲隅，阿阁交重栏。","佳人理清曲，当户横朱弦。","扬音綵霞里，令颜谁不观。","宾客会四座，丝竹哀且繁。","日中车马至，薄暮皆言还。","听曲各言好，知音良独难。","谁为同心人，并起乘双鸾。"]},{"t":"拟古诗十八首 其四","f":"五言古诗","c":["垒垒北邙山，松柏何脩脩。","松柏有时摧，人命安可留。","朝为华屋客，暮没归山丘。","洛中多豪贵，蔼蔼皆王侯。","高台临九衢，上有百尺楼。","宅第俨相望，轩车络如流。","存亡不预保，富贵安所求。","不如邀我友，乘马被轻裘。","遨游百年内，永以忘戚忧。"]},{"t":"拟古诗十八首 其五","f":"五言古诗","c":["蔼蔼东园内，绿林萋以繁。","车马自成径，桃李终无言。","昔日东陵侯，种瓜青门前。","既贵亦反贱，变化更无端。","俗夫寡恒态，志士多苦颜。","岂不策高路，高路远且艰。","良无万里风，孤翼谁当援。"]},{"t":"拟古诗十八首 其六","f":"五言古诗","c":["朝日照中庭，杲杲春载阳。","东风吹绿草，蝴蝶双飞扬。","岁华坐婉娩，白露憯以伤。","予美不在兹，所怀浩难忘。","岂无芳桂枝，含香谁为明。"]},{"t":"拟古诗十八首 其七","f":"五言古诗","c":["凄凄仲秋日，百卉腓以残。","凉风入阶树，零露摧庭兰。","明月皎东壁，昆虫鸣草间。","孤鸿暮安适，哀音扬云端。","言眷平生友，振翮起孤骞。","遗我若逝波，望子如高山。","托忱在终始，蓄久谅逾宣。","寸心不可移，磐石谁谓坚。"]},{"t":"拟古诗十八首 其八","f":"五言古诗","c":["郁郁山上松，高枝布天涯。","上有女萝草，缠绵誓不移。","葛生蒙于楚，浮萍寄清池。","贵贱虽殊途，附托各有宜。","伊昔侍君子，朝夕奉恩私。","驰心在皓首，何意中暌离。","穷年守房室，常恐踰良时。","思君如日月，所冀光不遗。"]},{"t":"拟古诗十八首 其九","f":"五言律诗","c":["汎汎东流河，袅袅河上柳。","春风暮飘摇，花飞不相守。","柔条欲攀赠，何堪入君手。","惟有南山桐，可以遗我友。"]},{"t":"拟古诗十八首 其十一","f":"五言古诗","c":["清晨株鴽马，整驾遵路衢。","迟徊览故物，憯侧心以纡。","昔时千室邑，今为百年墟。","郛郭蔽枌槚，狐兔翔城隅。","人生寓大块，飘泊寡恒居。","谅无金石寿，终与草木俱。","一身不自恤，安用顾其馀。","营营慕富贵，辛苦诚为愚。"]},{"t":"拟古诗十八首 其十二","f":"五言古诗","c":["长安多豪侠，白马一何骄。","金鞍竞络绎，宝剑相招邀。","招邀狭斜道，青楼郁岧峣。","楼中妖艳女，轻绮扬飘飖。","皓齿激清倡，逸响干层霄。","浮云散城邑，白日随惊飙。","荧荧桃李颜，华早仍先凋。","结交苟弗宜，谁谓能久要。"]},{"t":"拟古诗十八首 其十三","f":"五言古诗","c":["人生百年内，胡为形所役。","登高览九原，但见松与柏。","徘徊故里闾，念我平生戚。","斗酒相存问，度阡复逾陌。","上堂展殷勤，华灯永今夕。","何必倾馐庶，浊酤聊与适。","朱颜难可常，须发会当白。","遍观四海人，谁为不死客。","良时弗为欢，衰暮叹何益。","死者长不作，生者长不息。","日月更相送，万古安所极。","素丝有苍黄，岐路多南北。","在家常相问，出门安可测。","落木归本根，飞鸟战羽翼。","客游在万里，终当还故域。"]},{"t":"拟古诗十八首 其十四","f":"五言古诗","c":["朝宴高堂上，宾友相追游。","厨人进丰膳，妙妓扬清讴。","处世无百龄，为乐苦不周。","多财为患害，驷马招愆尤。","安如王子乔，高举凌九州。"]},{"t":"拟古诗十八首 其十五","f":"五言古诗","c":["岁暮寒风至，蟋蟀夜鸣悲。","高楼有思妇，叹息不自怡。","良人行未适，孤妾守空闺。","衾裯卷不寝，罗帷谁为施。","君如东流水，妾如西驰晖。","形势不相及，彼此何由谐。","结发重自念，携手期同归。","秋华殒故林，尚复扬光辉。","顾兹各努力，母忘荣盛时。"]},{"t":"拟古诗十八首 其十六","f":"五言古诗","c":["迢迢孟冬夜，悲风鸣北林。","严霜被野草，宛转时欲沉。","佳人久隔越，旷若辰与参。","方舟不利涉，欲往江湖深。","客从南方至，遗我绿绮琴。","愿因云中翼，寄子瑶华音。","胶漆不为固，金石安足谌。","明义苟不亏，殁齿当一心。"]},{"t":"拟古诗十八首 其十七","f":"五言古诗","c":["青鸟来北方，徘徊朝南翔。","美人传书至，开缄烂生光。","贻我机中锦，宛转成文章。","上织比目鱼，下织双鸳鸯。","物厚意不薄，感激独彷徨。","裁为衾与裯，置在黄金床。","君子不为御，三岁闻馨香。","一心奉光惠，常恐君遗忘。"]},{"t":"拟古诗十八首 其十八","f":"古风","c":["繁霜降秋夜，膏火寒无光。","凄风举帷幄，素月流中房。","客行在殊境，独处谁与将。","仰视天上星，罗列皆成行。","牛女独何辜，??守河梁。","嗟无凌风翼，欲去不得翔。","引领长太息，泗涕徒沾裳。"]},{"t":"鲁连","f":"五言律诗","c":["仲连初历国，排难能解纷。","飞书下燕将，立谈却秦军。","不受万户侯，长揖千乘君。","始称天下士，终为海上民。"]},{"t":"张良","f":"五言律诗","c":["子房号人杰，像貌非魁伟。","报韩志已成，翊汉功亦美。","出奇掉三寸，决胜在千里。","一遇黄石公，还从赤松子。"]},{"t":"望郭西诸峰有怀昔隐兼发鄙志","f":"五言古诗","c":["游龙战渊鳞，翔鹭振云翮。","潜姿媚幽深，遐羽忌拘迫。","顷来税尘衔，秉性嗜探历。","连山秀我里，幸兹眷昕夕。","横天岩峦叠，映日苍翠积。","涉波缅洄沿，攀岑若咫尺。","流目施远坰，写悰翼孤石。","嘉遁怀伊人，俯仰慨今昔。","霞构象丹厓，烟萝袅青壁。","倾耳谷中昔，希踪云外迹。","兴性感弥深，即景无与适。","岂徒藉虚觏，终然契冥寂。"]},{"t":"游西山二首 其一","f":"五言古诗","c":["晨登山上楼，暮望河上道。","飘风塞埃尘，积雨浩行潦。","山人苦相留，此道何扰扰。","虎狼夹路啼，鸿鹄逝不早。","石泉聊足饮，粝饭亦可饱。","引乃平生亲，绸缪叙中抱。","行游白云林，倘遇瑶华草。","携手托相赠，岁寒永为好。"]},{"t":"游西山二首 其二","f":"五言古诗","c":["胜地不可多，良游岂在屡。","兹山秀灵域，旷望契心许。","岧峣碧岩际，缥缈青莲宇。","鸣泉泻丹壁，白沙亘回渚。","眺心伫冥寂，况有尘外侣。","吾当与尔曹，翩翩接高举。"]},{"t":"立春日作二首 其一","f":"五言古诗","c":["蔼蔼春候至，天气和且清。","端居抚流化，久惬静者情。","浮阳起丛壑，流烟散孤城。","岸条发潜颖，园奔含初荣。","写襟旷明霁，览物纡游行。","目悦双飞雉，耳感孤鸣莺。","形运自相代，神理谁为名。","往规与时逝，来虑随年并。","心存汉阴灌，躬敩南阳耕。","疏还念知止，庄论持达生。","自非秉昭旷，能不婴世营。"]},{"t":"立春日作二首 其二","f":"五言古诗","c":["鸟鸣知天曙，冰泮知天和。","寒崖变吹律，阳渚发鸣葭。","温风戒旦至，淑气应时加。","申瞩暨昏旦，驰情赴幽遐。","连峰睇初景，木杪眺孤霞。","阴雪被高岑，暄波泻平沙。","辨候气有异，触物理无涯。","抚已寡朋与，怀侣独长嗟。","徒攀春岸条，未采中林华。","情惬赏不遗，心旷迹自赊。","久矣敦夙游，不愧在涧歌。"]},{"t":"田园杂诗二首 其二","f":"五言古诗","c":["去官今七暑，渐与农务亲。","随宜谙土性，言话群野人。","时或溯微风，行歌响空榛。","先民邈何扳，慨焉伤我神。","慨伤遹谁知，所有三二宾。","文论日往来，烱烱高义申。","炎雨回众壑，凉飙起脩畛。","兀然林木下，日人忘归轮。","玄蝉夕益聒，去鸟一何频。","野行畏多露，无使侵衣巾。"]},{"t":"水营墅治田圃种树","f":"五言古诗","c":["樵隐安于山，农隐乐耕畔。","由来事不同，各以性所玩。","倚扉憩南冈，负杖行春岸。","时泽冒原隰，远水增波澜。","方塘菰蒲映，回渚凫鹜乱。","插柳期息阴，列竹冀成竿。","缘坡引行条，依墉植颓干。","筑堤屏棼秽，激流代携灌。","疏慵外经济，卑贱鲜忧患。","谅怀原生耻，庶悟孔父叹。","汲古缀遗言，欣焉秉柔翰。"]},{"t":"与贾郡博宿夜话","f":"五言古诗","c":["世故相纠缠，人生剧如系。","予方值忧艰，子亦念淹滞。","邂逅胡不频，兹岁忽将逝。","苍苍季冬夕，悄悄昆虫闭。","积雪委沙曲，回风薄林际。","繁星烂高寒，明月皓初霁。","闻鸡起中夜，扪虱谈当世。","萧条时事危，寂寞古人计。","天地悲疮痍，江湖愧经济。","怀哉式微诗，泫然出双涕。"]},{"t":"除夕述哀四首 其一","f":"五言律诗","c":["世事相倚伏，日月更代谢。","百年能几时，一岁秪今夜。","逝者岂复回，有生无不化。","惨恻孤灯前，悲啼数行下。"]},{"t":"除夕述哀四首 其二","f":"五言律诗","c":["别离今几何，墓树亦已青。","徒褰素帷泣，奈此玄室扃。","古城积阴雪，虚牖临寒星。","岁暮兴慨念，愁立空屏营。"]},{"t":"除夕述哀四首 其三","f":"五言律诗","c":["去年值今夕，庭闱奉颜色。","今年值今夕，空奠几筵侧。","苍苔翳幽隧，翠柏开灵域。","顾望西山阴，风云为悽恻。"]},{"t":"除夕述哀四首 其四","f":"五言律诗","c":["忧人不能寐，起践中夜霜。","城笳绝仍响，室灯惨不光。","所亲半重泉，有姊各一乡。","附书与鸿鹄，岁晚路更长。"]},{"t":"赠别孟望之四首 其一","f":"五言古诗","c":["束发事交结，白首以为期。","以兹女萝质，托彼青松枝。","重聚故乡园，殷勤慰我私。","忽复远行迈，况值秋风时。","我有一樽酒，送君浉水涯。","酒酣思无极，临岐理桐丝。","谁知清商苦，一弹一生悲。"]},{"t":"赠别孟望之四首 其二","f":"五言古诗","c":["迢迢望夏日，肃肃戒仆夫。","金飙吹明星，行李已届途。","亲戚各相送，万里在斯须。","喈喈中林鸟，日出相鸣呼。","人生各有役，安能长相娱。"]},{"t":"赠别孟望之四首 其三","f":"五言古诗","c":["仲秋物色惨，游子生离颜。","朝辞义阳陌，夕宿武胜关。","遥望武昌路，汉水何潺湲。","愿为比翼鸟，逸翮杳难攀。","愿言终令德，努力济时艰。","同心苟不亏，岂在离并间。"]},{"t":"赠别孟望之四首 其四","f":"五言古诗","c":["公子事远游，离别无复云。","丈夫万里志，焉能恋故群。","我有千金剑，经天决浮云。","龙光久未试，姑以持赠君。","愿言终永佩，勿令埋尘氛。"]},{"t":"游西山二首 其一","f":"五言古诗","c":["清晨命予驾，飘飖远游迈。","愿言历岖嵚，况此春华在。","林条纷可结，石秀行当采。","道逢谐俗士，谓予尔何隘。","人命未可期，河清讵能待。","纵羽思山林，潜鳞慕江海。","富贵人所欲，吾志不可改。"]},{"t":"游西山二首 其二","f":"五言古诗","c":["郁郁西山岑，遥遥山上阪。","俯观清涧流，仰觑白云返。","处世亦何促，谁能遂仰偃。","夷齐归首阳，黄绮在商巘。","此道久不复，斯人苦难挽。","扼衣谢尘涂，吾驾日已远。"]},{"t":"元日言志","f":"五言古诗","c":["北杓建寅月，东谷发首旦。","气转青阳暧，日映丹霞烂。","群物欣向荣，万象倏改观。","自予脱朝簪，及兹谢尘干。","世事鉴倚伏，节候感回换。","岩耕慕长往，渊纶恣永玩。","俯羡潜波鳞，仰惭薄霄翰。","钦此无闷言，忘彼高飞叹。","勉怀日新志，庶以慰朝旰。"]},{"t":"观春雪","f":"五言古诗","c":["腾空布柔云，荡日溢繁吹。","素雪千里来，飘扬九衢内。","积阴改玄节，新阳献青岁。","永辞寒卉寂，甘并春华媚。","缤纷散广陌，皛耀敞尘界。","既随游霰集，复与流飙会。","临牖玩靡足，陟槛望逾迈。","参差百甍接，崒屼层台对。","佳人御棂轩，上客倚飞盖。","旖旎结华缨，离纵飘素带。","郢中有希倡，阳阿岂恒态。","君胡慕高卧，沉冥独无类。"]},{"t":"仲春雨霁出游郊麓览物叙怀兴言自歌四首 其一","f":"五言律诗","c":["旬阴豁初霁，临眺城四洲。","决决松上溜，潺潺石间流。","积霖晦平陆，春云弥崇丘。","眷彼农人谈，写我终岁忧。"]},{"t":"仲春雨霁出游郊麓览物叙怀兴言自歌四首 其二","f":"五言律诗","c":["崔巍南山郭，宛彼沙上道。","荷筱赴脩垌，采萍涉流潦。","怀贤顾已后，适已每不早。","缅兹山中人，含念郁中抱。"]},{"t":"仲春雨霁出游郊麓览物叙怀兴言自歌四首 其三","f":"五言律诗","c":["幽人久见招，解薜俟中林。","山行岩光暝，水息霞气阴。","随行委流止，寓物观浮沈。","达人贵忘我，奚用存知音。"]},{"t":"仲春雨霁出游郊麓览物叙怀兴言自歌四首 其四","f":"五言律诗","c":["举目怡清和，周览究昏昼。","众壑积庭阶，攒峰罗户牖。","攀林摘丛颖，越巘采孤秀。","日暮天际云，忽与飘风遘。"]},{"t":"赠梁宗烈二首 其一","f":"五言古诗","c":["珊瑚产南海，翡翠生炎洲。","丰林多异干，石璞皆良璆。","瑰材植遐域，万宝聚岩幽。","岂无千金贾，亦有万斛舟。","此物匪为易，惜哉不见收。","玉英匿龙渊，黄金沈浊流。","辉瑩久已閟，未蒙知己求。","徒归丘者愆，用负和氏羞。","谨子握中璧，时哉母闇投。"]},{"t":"赠梁宗烈二首 其二","f":"五言古诗","c":["飘风顷刻至，征云万里游。","与子非风云，欲遘良无由。","川涂限山海，音问邈中州。","升高望广域，极眺沧溟流。","浮烟隐榛树，白日蔽岑丘。","飞鸿不我顾，逝鹄不我留。","宁无轻舟志，浩渺安可求。","桂树茂炎隩，芝草翻灵洲。","独处慕朋侣，攀赠谁为酬。","倘荷衷眷言，慰此平生忧。"]},{"t":"赠王文熙四首 其一","f":"五言律诗","c":["空堂夕灯明，离思漫浩浩。","冷冷朱丝弦，听我别鹤操。","出门难久留，各言慎所好。","江湖迥且深，鸿雁几时到。"]},{"t":"赠王文熙四首 其二","f":"五言律诗","c":["行子夜中起，月没星尚烂。","天明出城去，暮薄长河岸。","草际人独归，烟中鸟初散。","解缆忽以遥，川光夕凌乱。"]},{"t":"赠王文熙四首 其三","f":"五言律诗","c":["光风转柳枝，宛宛路之傍。","濛濛苑中花，朝日耀其英。","停车欲有赠，攀条折春芳。","春芳亦消歇，但使故意长。"]},{"t":"赠王文熙四首 其四","f":"五言古诗","c":["息马中林树，烟霭何氛氲。","迟迟仲春日，丛薄华且芬。","上有单飞翼，哀鸣振层云。","冉冉征途客，踟蹰不忍闻。","嗟哉彼何物，日夜求其群。"]},{"t":"恽功甫悼亡二首 其一","f":"五言律诗","c":["捐弃不待年，幽魂渺仙峤。","庭下孤鸣鸾，悬镜耻自照。","帐冷凝素尘，窗虚耿熠耀。","平生白头吟，空然发悲调。"]},{"t":"恽功甫悼亡二首 其二","f":"五言律诗","c":["芙蓉望秋零，幽兰歇芳早。","不作双头花，翻为断肠草。","戚戚怀所思，悠悠感衷抱。","眷兹白发心，穷年以相保。"]},{"t":"悼亡三首 其一","f":"五言古诗","c":["冬夜一何长，展转难及晨。","念彼重泉下，杳杳隔千春。","中闺月皎皎，纨素委流尘。","驰光安可追，往者无复陈。","悽悽向隅泣，无乃女子仁。","丈夫自有志，忍哭虞伤神。","沉思结中抱，恨恨不能申。"]},{"t":"悼亡三首 其二","f":"五言律诗","c":["鸣鸡报早朝，出户履长霜。","仰视东方星，三五不成行。","念子当此时，灯前理衣裳。","恍然失所在，零泪空滂滂。"]},{"t":"悼亡三首 其三","f":"五言古诗","c":["皎皎机中绢，拂拭明如雪。","裁为双中衣，罗带纷绾结。","亲持向我前，与我言结发。","岂足佩下体，聊以奉娱悦。","执此百年心，叹息一朝绝。","人故物自留，欲视不忍发。","藏之箧笥中，馀香日以歇。"]},{"t":"挽叶进士","f":"五言律诗","c":["矫矫松柏枝，在彼丘中阿。","上盘青云端，苍翠郁嵯峨。","惜哉千尺干，严霜摧其柯。","本为大厦用，不竟当如何。"]},{"t":"赠李献吉三首 其一","f":"五言古诗","c":["西方有佳士，于世寡所谐。","横风整脩翰，倏忽超九逵。","天门限重关，屡扣阍者辞。","济济列仙子，冠裳竞追随。","青云蔽阊阖，仰视何逶迤。","皎日匿西陆，驰光难遽回。","世无鲁阳子，坐惜朱颜衰。"]},{"t":"赠李献吉三首 其二","f":"五言古诗","c":["东风吹我衣，白日何杲杲。","整驾出郭门，脩涂浩横潦。","登山采幽兰，日暮不盈抱。","采之欲何为，遗我平生好。","岂无艳阳花，言子好香草。","丈夫有本性，安得不自保。","寸心苟弗移，可以鉴穹昊。"]},{"t":"赠李献吉三首 其三","f":"五言古诗","c":["烈女守闺室，忧日怀寸阴。","横琴写妙曲，繁商激阳林。","悠悠行路子，谁为识其音。","人生处世间，贵在相知心。","所以采薇士，甘饿西山岑。"]},{"t":"荅献吉二首 其一","f":"五言古诗","c":["郁郁双凤阙，翱翱飞云间。","我皇乘六龙，平明开九关。","下有敢死士，批鳞犯其颜。","白日运苍昊，薄暮浮云还。","一朝启光耀，忠诚良可宣。"]},{"t":"荅献吉二首 其二","f":"五言古诗","c":["吾君古尧舜，垂衮蓬莱宫。","止辇受群善，小太必有容。","缅怀燕邹子，悲号诉苍穹。","彼苍亦何神，五月飞霜风。","至诚变金石，何惧不感通。"]},{"t":"游鲁山城南舍二首 其一","f":"五言古诗","c":["猗彼方外客，逍遥城南墅。","初夏苗始盛，荷笠事田圃。","他僻寡邻居，弥旬绝车马。","红葵生井上，青榆荫堂中。","前冈后有岑，原泽何膴膴。","清风林下酌，狼藉列樽俎。","翻思在朝市，役役徒劳苦。"]},{"t":"游鲁山城南舍二首 其二","f":"五言古诗","c":["溪行日亭午，暑气稍见侵。","脱巾坐芳草，前有嘉树林。","白云澹清景，绿叶垂繁阴。","喜无鸣蝉聒，幸有好鸟吟。","久厌区中缘，抚兹意弥深。","浩歌答良友，聊用开吾襟。"]},{"t":"中秋十七夜留康德涵饮二首 其一","f":"五言古诗","c":["飘风会浮云，白曜奄西藏。","羁人惜短晷，眷此秋夜长。","长夜无与晤，所怀浩难忘。","君子枉光驾，嬿婉情未央。","披轩待流月，展转错华觞。","临觞惨不御，对景久徬徨。","郁雾暧庭阴，黯黯如降霜。","流波委颓魄，兹岁渐以更。","消长互相谢，盛满安可常。","勖哉君子心，谦谦道弥光。"]},{"t":"中秋十七夜留康德涵饮二首 其二","f":"五言古诗","c":["客心悲夕阴，相顾增烦忧。","麾杯浩歌起，欲去不可留。","屏营独抚膺，仰观熠耀流。","倏焉四宇豁，众星烂以稠。","游气降大谷，浮飙扇清秋。","昊天舒华魄，御耀西南楼。","朱门歇笙竽，绮帞车马休。","嗟尔晨明月，烛烛安所求。"]},{"t":"咏怀十首 其五","f":"古风","c":["知鸟去?木，蝼蚁恋腐茎。","复隍启危满，为山忌将成。","泛观瀛海内，巨细各有情。","哲夫炳身后，昧者营其生。","千金买一壶，为豫当及早。","江湖多风涛，舟楫不可保。"]},{"t":"咏怀十首 其六","f":"五言古诗","c":["寂寂沅湘流，长江上有枫。","青蕙缘广隰，绿衡被洲中。","扬舲溯烟沚，遥曕二妃宫。","二妃何婉㜻，搴馨振微风。","解佩遗下女，将以明我衷。","光采不易合，精诚渺难通。","浮云蔽江皋，白日忽已晚。","还顾苍梧原，何时翠华返。"]},{"t":"咏怀十首 其七","f":"五言古诗","c":["飞鸿遵故渚，长鸣有馀哀。","北地多悲风，霜雪日以催。","灵乌集君舍，君反见疑猜。","忠信苟不显，杀身亦何为。","始知山梁雉，欲下仍徘徊。"]},{"t":"咏怀十首 其八","f":"五言古诗","c":["长安有绮楼，文窗结朱疏。","俯视千万甍，遥临十二衢。","楼中弹瑟女，容采耀城隅。","岂无吉士诱，失身良为愚。","回风入穗帐，倏忽白日徂。","玉颜易销铄，不久当何如。"]},{"t":"咏怀十首 其九","f":"五言古诗","c":["白露晞朝日，苕荣委清秋。","长风吹野草，飞藿不自谋。","猥彼众多子，安知良士忧。","覆水置平地，一散永不收。","鼍错忧汉室，翻为六国仇。","祸机苟不测，谈笑生戈矛。","留侯信人杰，逝从赤松游。"]},{"t":"咏怀十首 其十","f":"五言古诗","c":["白玉本自白，苍蝇乱其真。","谗言解胶漆，况匪平生亲。","烈士死道傍，贪夫登要津。","自古皆有然，兹恨何当申。","蓬丘眇烟雾，贝宫郁嶙峋。","列仙如可期，吾将蹑清尘。"]},{"t":"东皋","f":"五言律诗","c":["蔼蔼东皋村，中有幽人宅。","茅堂入空林，草径无来客。","林中桂树英，容采耀月夕。","寒香有时匮，秋来望攀折。"]},{"t":"赠边子四首 其一","f":"五言律诗","c":["自予辞京邑，念子守南服。","岁序阻欢觏，川涂积遐瞩。","北骛方自兹，东轘偶相值。","联鏕始宋中，解缆及河曲。"]},{"t":"赠边子四首 其二","f":"五言律诗","c":["同车越梁晋，览历多古疆。","纡迟卫流汭，转盼淇水阳。","感来意不浅，道故言已长。","辛勤眷途语，怆恻悲别章。"]},{"t":"赠边子四首 其四","f":"五言律诗","c":["欢聚理无恒，悲离情有伤。","况兹征途閒，讵能久相将。","浮云兴岁暮，素雪翳晨光。","挥手自兹别，后期应母忘。"]},{"t":"赠望之四首 其一","f":"五言古诗","c":["袅袅孤生杨，迢迢河水汭。","平生骨肉亲，婉㜻相谐悦。","思心起欢燕，何况当乖别。","浮萍寄清流，聚散有欢惙。","与子同枝叶，胡为忍离阔。","愧匪根与株，莫能相固结。","德人重行义，志士轻诀绝。","慎子万里躯，慰我长饥渴。"]},{"t":"赠望之四首 其二","f":"五言古诗","c":["良时不克俱，悠悠子行迈。","行迈之何方，乃在万里外。","汎舟涉江湘，道远阻湍濑。","我心思桂林，倚立增叹嘅。","河清岂无期，奈此日月逝。","所愿芳未歇，及兹采荃蕙。"]},{"t":"赠望之四首 其三","f":"五言古诗","c":["瓜生施于葛，枝蔓自缠纠。","念我同胞人，是子结发友。","少小钟慈育，各言常相守。","出门有羽翼，忽尔离隔久。","戚戚去兄弟，思我父与母。","种瓜莫种棘，种棘恐伤手。","恩爱苟不亏，离隔复何有。"]},{"t":"赠望之四首 其四","f":"五言古诗","c":["绝裾不为忍，叱驭宁顾危。","念子奉明君，结义良在兹。","虽怀垂堂戒，委质我所知。","白日岂不察，浮云蔽于斯。","孤葵慕太阳，倾心量不移。","勿谓长弃捐，终当有返期。"]},{"t":"送王宗哲少卿","f":"五言古诗","c":["肃肃出郊干，行行涉河甸。","子身被王命，驷马辉云电。","览岳停华阴，观都指秦殿。","思子卫泉流，渭浐一以缅。","平生共肝胆，何云异乡县。","况我离骨肉，子也常眷恋。","忆我连枝树，感子同洲雁。","子行四方志，努力思见面。"]},{"t":"过吕仲木宅同吕道夫马君卿","f":"五言古诗","c":["夏访吕子居，乃在北城阴。","门临古墙渠，上有高树林。","展席流南薰，开轩睇北岑。","况谐同心友，听此和鸣禽。","佳人出素帙，高词播名琛。","亮哉清庙瑟，凄其白头吟。","一弹意不足，三叹有馀音。","因之览玄古，寥寥伤我心。"]},{"t":"鸣蝉","f":"五言律诗","c":["菀菀庭中柳，蝉鸣在高柯。","上有西飞燕，下有东流河。","美人堂上坐，忘却门前道。","举头见鸣蝉，低头惜芳草。"]},{"t":"冬至","f":"五言古诗","c":["北杓指玄朔，南景留严冬。","中衢返羲驭，淑气扇黄钟。","微阳惧不力，固阴密且重。","至尊怵时令，端拱象钦恭。","闭关关遏行，旅玉罗勋庸。","天乃群物祖，日为众阳宗。","眇兹一线晷，邈彼九渊龙。","泰登自此肇，复来岂无从。","圣人谨元始，君子履攸终。"]},{"t":"赠田子三首 其一","f":"五言古诗","c":["蓬途眷行旅，绸缪永兹夕。","之子溯大江，方舟自此适。","蔼蔼皇邑游，鸣鏕并京陌。","同袍四五人，君为远行客。","婉㜻一室内，安知形影隔。","人生重贞固，岂必金与石。","念彼胶漆友，喟然怠今昔。"]},{"t":"赠田子三首 其二","f":"五言古诗","c":["苍苍季冬夕，积雪委中衢。","三星出东户，纤月扬西隅。","主人乐行觞，众宾且停车。","何况平生友，夙昔共欢娱。","惨恻高堂上，为子重踟蹰。","山川缅以邈，岐路在须臾。","出门慎自爱，慰我恒相于。"]},{"t":"赠田子三首 其三","f":"五言古诗","c":["凤鷟去南国，徘徊翔紫庭。","毛羽纷葳蕤，霜雪日以零。","一鸣已旷世，奋翅排清冥。","崔巍南山下，脩竹何亭亭。","文采忽遐远，伫立望尔形。","依依北堂隅，俦侣念伶俜。","相聚不须臾，一散如晨星。","我欲从尔去，但愧无脩翎。"]},{"t":"七夕刘子纬宅次君卿韵","f":"五言古诗","c":["良时届今夕，欢觏谐兹方。","流飙委芳卉，清池激微凉。","仰观牛女星，荧荧河汉傍。","纤月扬西隅，浮云起中央。","合离一以怆，明晦古难量。","絷子场下驹，慰我长思望。"]},{"t":"断绝词","f":"五言古诗","c":["孔雀慕俦侣，回翔恐相失。","罗雉为雄雌，反覆不成匹。","白沙搏清水，谁能作胶漆。","本非骨肉亲，心志安得一。","牵缠无已时，断绝有终毕。"]},{"t":"玉冈黔国地种竹","f":"五言古诗","c":["玉冈一精舍，五华东南首。","崔嵬瞰城郭，旷缅开林阜。","球琳美梁域，筱荡卑扬亩。","峥嵘将军第，潇洒文儒囿。","霜凝戟门寒，日上铃阁昼。","褰帷散琴书，缓带接宾友。","风林清夏簟，云石静秋牖。","参差万琅玕，照耀双琼玖。","连城价自高，倾国貌俱丑。","缪倚惭芜葭，先凋谢蒲柳。","上公勋不忘，君子名讵朽。","蛮夷钦镇静，风俗化温厚。","比德亮无瑕，抱饰诚可久。","圭璋寡雕琢，瑚琏重典守。","至宝天所悭，珍产地非偶。","阆颠神仙宅，瑶水蛟龙薮。","安知王母觞，复为周王寿。","献从万里馀，种已千年后。","灵秀萃于兹，积累固所有。","乐只邦家光，斯韵播人口。"]},{"t":"赠君采效何逊作四首 其一","f":"五言律诗","c":["霜空雁绝响，风庭叶罢飞。","念尔别离日，凄然芳岁微。","城隅明星晰，晓闼残月辉。","不见携手好，宵行谁与归。"]},{"t":"赠君采效何逊作四首 其二","f":"五言律诗","c":["平生寡所谐，与子中邂逅。","宴语殊未厌，弦柱促离奏。","目断川上云，念攒天边岫。","河山邈以绵，伫立阻欢觏。"]},{"t":"赠君采效何逊作四首 其三","f":"五言律诗","c":["居人日缚束，行人逝飘飖。","山栖怜雾夕，水泛悦霞朝。","违俗势靡合，遗名迹自超。","愧随衣冠侣，振佩青云霄。"]},{"t":"赠君采效何逊作四首 其四","f":"五言律诗","c":["岁晏客来归，车马一何乱。","新妆下机笑，白发倚门看。","未俟春林敷，且玩冬花灿。","闲居有徽音，倘付云中翰。"]},{"t":"酬赠王德徵","f":"五言古诗","c":["北方有一士，云冠瑶华簪。","抗身服高义，奋趐翔天林。","一鸣远见斥，弃置南海浔。","飞黄本冀产，顾盼无千金。","绝景迈流电，岂与泥沙沉。","邂逅顷三接，一言荷知深。","投赠古锦篇，宛聆哀玉音。","大雅久寥寂，斯文竟谁谌。","皎皎空谷驹，生刍劳我心。"]},{"t":"江畬行","f":"五言古诗","c":["树谷江上田，三年免饥饿。","富贵苟非道，千驷秪一唾。","匹夫一夺志，旷士鲜无过。","蛾眉召谗妒，西子蒙诟涴。","铄金惧众口，怀璧诚贾祸。","蛇龙蟠泥沙，鲲运海水簸。","子今还山中，食谷且高卧。"]},{"t":"咏衣","f":"五言古诗","c":["凄凄絺绤风，惨惨葛履霜。","无衣叹豳奏，同袍怠秦章。","物微申有赠，德音亮难忘。","新缣托故素，温燠念寒凉。","体裁合情志，拂拭生辉光。","虽云异黄里，愿言同褧裳。"]},{"t":"古怨诗五章 其二","f":"五言律诗","c":["抗义一何明，结志誓不解。","对面有背弃，何言万里外。","陟疆朝采葑，陟畛暮采菲。","所重在德音，容色安足恃。"]},{"t":"古怨诗五章 其三","f":"五言律诗","c":["白玉虽光辉，瑕疵在其内。","徙看色笑亲，讵识肝胆异。","势夺恩爱移，交离谗毁至。","弃捐岂我伤，卑薄乖情义。"]},{"t":"古怨诗五章 其四","f":"五言律诗","c":["寸心抱贞固，投一安有它。","讵知所同欢，散聚倏朝霞。","昔为山上石，今为浪中沙。","孰云无转移，漂荡令心嗟。"]},{"t":"古怨诗五章 其五","f":"五言律诗","c":["清晨临御沟，御沟东西流。","垂杨夹广路，躞蹀行紫骝。","挥鞭不顾返，斗酒谁能留。","嘅焉中道情，覆水倘可收。"]},{"t":"情诗","f":"五言律诗","c":["出门景将夕，入门露已瀼。","徘徊只户间，灿烂三星上。","玉颜艳明魄，一别阻弦望。","讵能轻诀绝，徒令重惆怅。"]},{"t":"咏裘","f":"五言律诗","c":["羔裘故人物，持赠何殷勤。","俭表素丝质，光回锦绣文。","豹祛未称美，孤白安足云。","意比绨袍恋，恩同纩絮温。"]},{"t":"饮酒","f":"五言古诗","c":["平生多意气，四海盛交游。","列筵亘长夜，谈辩雄名流。","杯酒一言合，遽将肝胆投。","入门顾儿女，忸怩但怀羞。","齿年逮今兹，世故多所由。","兴言念亲戚，骨肉婴我忧。","寒宵寡欢悰，浊酤聊自谋。","明灯耀室内，盘蔬代庖羞。","岂必朋与宾，妻子前劝酬。","语笑率真性，无嫌亦何尤。","人生贵止足，吾志卑公侯。","数觞已复醉，颓然万情休。","寄言驰骛子，从今任去留。"]},{"t":"送刘御史按淮扬诸郡","f":"五言古诗","c":["台臣令按地，圣祖旧开疆。","白云万里来，千载还帝乡。","伊昔草昧初，血战尘茫茫。","一马渡天堑，六龙飞淮扬。","尧阶起三尺，禹迹遗八荒。","江海控形劫，邦家存纪纲。","遐哉百年馀，世变隳其常。","城社穴孤鼠，当途走豺狼。","君埋都亭轮，再睹司隶章。","述职属兹岁，巡狩代我王。","泛舟淮泗急，褰幕风日凉。","鹰隼在寥阔，一击乘秋霜。"]},{"t":"游洪法寺塔园土山","f":"五言古诗","c":["塔园郁森萃，土山莽回互。","迹陈慨往躅，心赏谐秋晤。","时惟冬气交，零木爽登顾。","袅袅拾层级，盘盘折脩步。","凭危眺倒景，俯槛惊流雾。","空王涌庙卫，贵者留墟墓。","三门上岌嶪，玉柱撑云露。","白日宝光垂，风昼金响度。","徒兴雍门哀，未暇首丘虑。","珠藏北邙毁，石罅南山锢。","怛焉伤逝心，川汜激东骛。"]},{"t":"赠时亮","f":"五言律诗","c":["戴子有仙癖，时荷金门遇。","辟谷游人间，嗜酒尚玄素。","白日指五岳，笑我不能去。","尔未生羽翼，何时向烟雾。"]},{"t":"赠子言","f":"五言律诗","c":["张生神骏骨，一蹶在衢路。","虽有万里才，未蒙千金顾。","腰佩白玉环，手掷金声赋。","堂堂烈士身，勿为名所误。"]},{"t":"冬夜","f":"五言律诗","c":["膏火含朱光，玉樽泛清醴。","閒房密以静，雪流窗户里。","良友不我适，室阻怅伊迩。","异人非我俦，聊酌娱妻子。"]},{"t":"十二月朔日大驾观牲","f":"古风","c":["玄云翳广陌，素霰雰层城。","万乘屯兰甸，六辔俨天行。","轻飙转芝盖，重霄扬翠旌。","??剑佩合，锵锵龙凤鸣。","牺人脱衡楅，膳宰翼房楹。","牛羊上廪贮，鹿豕大庖盈。","馨香流秬鬯，肥腯奏牷牲。","宫阙回帝览，钲鼓感皇情。","至敬肇兹达，大礼须时成。"]},{"t":"简君采","f":"五言古诗","c":["夕会星已罗，昼接景将落。","见面不须臾，何以展契阔。","侧耳金玉章，音响时间作。","假寐晤清颜，倾光岂虚托。","枉骖怅云辔，命席耻尘爵。","徘徊翳云日，伫立眺城郭。","骈居淹晨暮，庶俾私心豁。"]},{"t":"送崔氏四首 其一","f":"五言古诗","c":["行车在门端，送宾集城隅。","辕骥难久停，振策中路衢。","盘盘大行谷，往念高堂居。","还顾望西山，层阜蔽皇都。","回飙赴迅响，飘云奔长徂。","昔予背乡域，眷言返田庐。","驱车赴燕蓟，兹岁淹七踰。","何因附羽翼，翘首南翔凫。"]},{"t":"送崔氏四首 其二","f":"五言古诗","c":["畴昔衣冠士，同游若云烂。","欢宴未及终，存亡在转盼。","亡者长沉埋，存者各飘散。","俯仰天地间，念之一惋叹。","出门送我友，言返故乡县。","登高望古疆，河卫浩以漫。","山川白日冥，匹鸟鸣相乱。","怆恻怀征途，令我肠中断。"]},{"t":"送崔氏四首 其三","f":"五言古诗","c":["结发与君友，附骥思一鸣。","君子扬休景，遘世垂荣名。","伊予守屯蹇，学宦寡所成。","握瑜俟知己，知己谁为明。","良时展嬿婉，之子复远行。","冲飙起阊阖，浮云翳太清。","层城罗宫殿，跃马振緌缨。","长啸歌五噫，投策出汉京。","慨念古人士，去之一何轻。","终焉从子逝，富贵非我营。"]},{"t":"寄赠王子衡四章 其一","f":"五言律诗","c":["昔饯迈伊始，今怀缅犹故。","城憩屡淹薄，舟游一洄溯。","弭节指颓景，摇车首东路。","仓皇抗手别，邈绝赏心晤。"]},{"t":"寄赠王子衡四章 其二","f":"五言律诗","c":["赏心眷景光，川汜渺徂征。","窜身穷海上，卧痾天边城。","倾歌岛岸坼，蹙汨波楼惊。","飘音承来讯，颇叙栖泊情。"]},{"t":"寄赠王子衡四章 其三","f":"五言律诗","c":["栖泊倦淮堧，量移遂山郭。","沈迷谢簿领，褰开尽岩崿。","云翔叶县凫，风唳华亭鹤。","困谐宣城兴，复枉临海作。"]},{"t":"寄赠王子衡四章 其四","f":"五言律诗","c":["临海叠灵巘，洞壑丹霞林。","名胜纪图牒，仙圣秘幽深。","俗营迕微尚，旷怀俟同心。","倘追凌风步，灭响升云岑。"]},{"t":"集吴子寺馆","f":"五言古诗","c":["首夏憩祇园，游息解冠簪。","窗楹抗疏敞，殿宇閟深沉。","绿竹带阴渠，丹葩缀阳林。","既枉高人躅，亦协静者心。","琴书散烦虑，钟磬发幽音。","清言忘朝昃，玄思超古今。"]},{"t":"夏夜薛子宅","f":"五言古诗","c":["飘风激疏牖，飞雨散高庭。","白云荫华月，青天垂列星。","褰裳望西苑，园树发青荧。","阴馆辟炎埃，峻槛临岩嵉。","泠泠朱夏井，肃肃玄夜扃。","披雾聆霏谈，逍遥畅神形。","游心娱竹素，此乐诚可经。"]},{"t":"赠君采","f":"五言古诗","c":["萧散综琴书，疲疾谢回乱。","清云汎阑暑，白水激文澜。","于心怀我友，翩翩振词翰。","比室谐言晤，抚景悦流玩。","孔公赞龙蠖，庄生明吹万。","理感由神诣，情赏非虚叹。","鄙哉辨雌霓，安知睹河汉。","愿投忘形契，去适无穷岸。"]},{"t":"高桥","f":"五言古诗","c":["飞梁何袅袅，袅袅飞涧中。","窈窕入青霭，蜿蜒垂白虹。","俯壑聆迅湍，攀崖挹回风。","阑干既重复，结构亦玲珑。","穿石凿坤艮，架阁凭虚空。","羽填乌鹊岸，力坼鼋鼍宫。","设险固天造，扶神岂人工。","圣代文轨一，绝域宾主同。","梯航无外至，筐篚倏然通。","怀哉绝栈智，逝矣当关雄。","钦诫慕在德，其亡守无穷。"]},{"t":"姜子岭至三岔","f":"古风","c":["出岭上云霓，入溪下烟岚。","高高不可极，杳杳讵能探。","朱崖秀夏木，石壁?寒潭。","千林览葱茜，百丈窥澄涵。","崩奔谷响赴，隐曜川光含。","登陟力不辞，险阻情已谙。","潜渊羡垂纶，越巘思停骖。","振策岷峨西，扬帆江汉南。","临深匪忘惧，履坦但怀惭。"]},{"t":"寄粹夫四首 其一","f":"五言律诗","c":["伊昔京室娱，安知岐路戚。","君就河内栖，予从关西役。","同源异流上，抚事乖心迹。","终尔返轮鞅，音尘慰岑寂。"]},{"t":"寄粹夫四首 其二","f":"五言律诗","c":["肥遁世久钦，苦节晚逾峻。","悬萝邈莫攀，翠壁迥千仞。","冥心道与超，晦迹名反近。","将遂谐龙蠖，混然保贞顺。"]},{"t":"寄粹夫四首 其三","f":"五言律诗","c":["昔闻孙登啸，千载识其音。","岧峣百门上，髣髴三湖阴。","鸿举已寥廓，鸾响犹空林。","旷哉既往古，契此徵于今。"]},{"t":"寄粹夫四首 其四","f":"五言律诗","c":["阮公虽旷达，于道未真见。","石髓不可餐，赤文讵能辨。","服理昧情性，眩物矜神诞。","傥君示中行，遥垂大人撰。"]},{"t":"送刘笔峰暨从子黄岩赴省应试","f":"五言古诗","c":["年少刘家郎，绿鬓颜色鲜。","大者气孤卓，小者骨奇权。","珊瑚碧玉树，照耀森我前。","相看如二阮，俱为竹林贤。","向人长揖别，白马垂只鞭。","朝出长安门，夕至晋水边。","晋水生秋风，桂叶吹香绵。","迢迢月中楼，夜冷蟾兔眠。","二子独先登，举头叩遥天。","衣裳结綵雾，金粟枝联翩。","众人望高躅，飘如云中仙。","丈夫生有才，即使功业传。","君看竹下人，落魄空自怜。","春风杏园花，拟待双车还。"]},{"t":"乞巧行","f":"古风","c":["鹊桥崔巍河宛转，织女牵牛夜相见。","岳阳女儿迎七夕，乞巧楼高高百尺。","华灯明月光窈窕，结綵蟠花绮罗绕。","富家女儿恃娇小，年年乞巧不得巧。","贫家女巧世所稀，只为他人缝嫁衣。","须臾露湿金剪刀，只星渐没河渐高。","人间天上两迢遥，步袜仙裙空寂寥。","君不见古来巧拙何足语，岁岁楼前竞儿女。"]},{"t":"古松行","f":"七言古诗","c":["岳州地多古松树，千株万株植官路。","故老犹能记岁年，行人不解知朝暮。","临江西来烟雾起，夹谷连山一百里。","黛色寒通七泽云，秋声夜捲三江水。","郡城之北江水东，鄂王祠庙丹青空。","英雄为谟本宏远，古水至今多烈风。","忠魂义魄杳何在，故物依然见遗爱。","繁枝百世人不剪，直气千寻我当拜。","六年前过蒲圻城，古松阴中三日行。","空山倒挂雷雨黑，盛夏常贮炎风清。","邮亭传舍总萧瑟，郁抱烦襟亦飘逸。","回岩峭壁奔洪涛，老蔓长藤翻白日。","只今复向巴立道，野草渐多松渐少。","仄径孤根半蚀苔，夕阳几树空垂茑。","昔时所见合抱材，断枝落叶随蒿莱。","过客山中想清籁，行徒道上愁黄埃。","辇山舆岭万千重，半作豪家楼上栋。","古人之力今人劳，大厦明堂不得用。","年年官吏催斧斤，故老虽怒那敢嗔。","傍枝出地子成树，野妇山樵摧作薪。","驿前数干聊可数，我忽见之再三抚。","霜皮露甲如虬蟠，雾鬣烟鬟学龙舞。","阴森气象凛犹昔，翠色长标不可侮。","荒林旷野识者稀，终为谁家起廊庑。","回首鄂庙秋山阿，庙前之树无高柯。","鬼神诃护亦徒尔，英灵不返将如何。","达人且勿怨摇落，志士胡为伤轗轲。","君看世事尽如此，拔剑听我松前歌。"]},{"t":"津市打鱼歌","f":"七言古诗","c":["大船峨峨系江岸，鲇鲂鱍鱍收百万。","小船取速不取多，往来抛网如掷梭。","野人无船住水浒，织竹为梁数如罟。","夜来水长没沙背，津市家家有鱼卖。","江边酒楼燕估客，割鬐砍鲙不论百。","楚姬玉手挥霜刀，雪花错落金盘高。","邻家思妇清晨起，买得兰江一双鲤。","筛筛红尾三尺长，操刀具案不忍伤。","呼童放鲤潎波去，寄我素书向郎处。"]},{"t":"偏桥行","f":"古风","c":["城头日出一丈五。","偏桥长官来击鼓。","山南野苗聚如雨。","饥向民家食生牯。","三尺竹箭七尺弩。","朝出射人夜射虎。","砦中无房亦无堵。","男解蛮歌女解舞。","千人万人为一户。","杀血祈神暗乞蛊。","沙蒸水毒草根苦。","上山下山那敢?。","蠢尔苗民尔母侮。","虞庭两阶列干羽。"]},{"t":"省中公宴","f":"七言古诗","c":["今日何日公宴会，紫薇垣下填车盖。","总戎太监争邀呼，御史中丞立相待。","坐花馔玉绮席陈，愧我何能居上宾。","劝酬尽是文武士，列坐俱为藩臬臣。","广堂潭潭长百武，堂前挝钟复搥鼓。","击石弹丝逐横吹，清歌缓节随轻舞。","酒阑起酌明烛前，横金鸣玉声珊珊。","交衢夹道灯火乱，仰看月出楼台间。","诸公豪俊世希有，协恭同寅重边守。","幸时夷方不用兵，簿书之暇得饮酒。","只今天子布洪仁，九州四海俱同春。","清风想见唐虞出，玉座欣曕日月新。","诸公于此复何虑，矢志盟心思致身。"]},{"t":"大石关行","f":"古风","c":["青山千仞城百尺，云中嵯峨列万石。","关门控险铁不如，万人可望不可踰。","蛮兵一朝杀关吏，驱马入关履平地。","山头矛戟多于草，弩箭射甲如射缟。","当关秪用一夫力，胡为万卒犹难保。","君不见山上城堞毁，楼倾四壁立。","青狸苍兕朝对啼，白蒿黄云暮愁入。"]},{"t":"栖凤亭","f":"七言古诗","c":["将军园中何所蓄，十尺亭子四面竹。","亭中一榻千卷书，将军昼游夜还宿。","元勋甲第高入云，奇珍异玩穷海陆。","将军雅性不苟嗜，只爱亭边万竿绿。","旧家风节传累世，见此胜如见乔木。","根株盘据几十年，出地皆成老龙骨。","旧干扶疏已作林，新梢复见高于屋。","新梢旧干森相向，百丈空云寒突兀。","先公开圃一何勤，引水分畦费营筑。","石间斸雨移紫琼，沙上耕烟长青玉。","至今遗爱思莱公，万古看诗想淇澳。","将军能武兼能文，展卷一目数行读。","只今世守清白操，春风如温霜如肃。","闲时高卧园之中，此君亭亭对幽独。","月轩夜坐呈夏箪，风榭凉熊除暑服。","空冥缥缈闻笙竽，户牖清虚映签轴。","昆池歌动黄鹄高，洞庭笛横白云哭。","瑶瑟一鼓潇湘亭，冰绡再写筼筜谷。","忆昨路经岭徼来，佳植全稀多朴遫。","山深苦竹啼鹧鸪，地僻枯篁宿麋鹿。","何期得到将军园，一洗胸中十年俗。","清晨邀我促席看，半日捲帘犹不足。","我闻竹生玉河湄，开花结食凤凰啄。","将军文采真凤凰，凡树安能动高目。","愿将音响入箫韶，奏我亭中栖凤曲。"]},{"t":"黄陵庙","f":"七言古诗","c":["黄陵峡中滩水多，黄陵庙下难经过。","峨峨巨舸牵百丈，橹折樯摧不得上。","江风萧飒笳鼓哀，庙门遥向枫林开。","往来落帆泊江口，俎牲咒神酾神酒。","南船下峡疾如箭，岸草汀花看不见。","巉岩乱石撑如麻，云间浊浪迷三巴。","千里舟中坐超忽，回首天西断心骨。"]},{"t":"关索岭","f":"楚辞体","c":["噫嘻吁，崄巇何天设之危艰。","下有奔雷喷雪之飞壑，上有悬崖石栈百折而造天。","嵚崟兮巉岩，面复兮盘盘。","行人雁陈而鱼贯，计分寸兮跻攀。","飞鸟兮折翼，猴猱兮无援。","苟失足殒岩而落箐兮，曾不足以充虎蛇之餐。","朝不见日，夕不见月，云烟惨惨兮昼夜寒。","噫嘻乎，何天设之危艰，我来倚绝壁而长望，盖不知蜀道之为难。"]},{"t":"大梁行","f":"古风","c":["朝登古城口，夕藉古城草。","日落独见长河流，尘起遥观大梁道。","大梁自古号名区，富贵繁华代不殊。","高楼歌舞三千户，夹道烟花十二衢。","合汨轮驺交紫陌，鸣钟暮入王侯宅。","红妆不让掌中人，珠履皆为门下客。","片言立赐万黄金，一笑还酬只白璧。","带甲连营杀气寒，君王推毂将登坛。","弯弧自信成功易，拔剑那知报怨难。","已见分符连楚越，更闻飞檄救鄞郸。","一朝运去同衰贱，意气雄豪似惊电。","杨花飞入侯嬴馆，草色凄迷魏王殿。","万骑千乘空云屯，绮构朱甍不复存。","夜雨人归朱亥里，秋风客散信陵门。","川原百代重回首，宋寝隋宫亦何有。","游鹿时衔内苑花，行人尚折繁台柳。","繁台下接古城西，春深桃李自成蹊。","朝来忽见东风起，薄暮飞花满故堤。"]},{"t":"蔡州行","f":"七言古诗","c":["蔡州城高高且壮，四十年间兵不向。","旌旗忽乘雨雪入，一夜开门纳兵仗。","请降尽是洄洄军，拒戢不睹牙城将。","鞬橐将军拜道左，绯衣小儿来天上，州人始识裴丞相。"]},{"t":"流萤篇","f":"七言古诗","c":["广储六月清无暑，流萤暗逐薰风举。","始见昏连万户星，更看夜照千门雨。","千门万户竞高低，拂槛萦廊乱复齐。","碧莎映水光初迥，绿柳栖烟影乍迷。","水光烟影飞还歇，肯使炎精易沦灭。","带火终须避太阳，含辉却自亲流月。","长信宫中一叶秋，玉阶金阁见萤流。","贵嫔罗扇开香箧，侍女珠帘捲画楼。","谁家怨妇缝缣素，当窗忽见流萤度。","蟋蟀床空宝瑟寒，鸳鸯机暗孤灯暮。","萤飞萤度自年年，却笑明珠按剑前。","莫言腐草无生意，莫道寒灰不再然。","还将斥鴳鹍鹏语，三复庄生第一篇。"]},{"t":"观涨","f":"七言古诗","c":["五月十日雨如射，西山诸溪水皆下。","大陆朝迷牛马群，疾雷夜破蛟龙罅。","洪涛冥冥夕风急，白浪闪闪山水亚。","浮波喷沫来崔巍，巨丘欲没高岸颓。","咫尺莫辨天宇阔，仓卒但忧坤轴摧。","固知一苇不可济，虽有万弩何由回。","农家夜起筑堤障，妇女走观色沮丧。","恶少迎人争渡喧，父老携幼登城望。","门前秪讶海劫翻，井中暗觉潮声上。","忆昨曾为万里行，洞庭滟滪何渺冥。","鲸吞鳌横那可测，盘涡骇浪谁能平。","只今忧寐时作恶，闻此终夜令心惊。","旋看雨霁劫亦止，沙嘴忽落千尺水。","杂花濛濛夏壖静，细草青青夕洲靡。","行人褰裳掇菱荇，稚子垂竿取鲂鲤。","眼前喜愕俱已忘，就中消息谁为此。"]},{"t":"寄赠张方伯","f":"七言古诗","c":["君侯风神有奇格，秀髯方瞳兼广额。","少年甲第已峥嵘，壮岁功名更辉赫。","长淮之西古蔡州，我侯清风千载沭。","行人尚闻歌叔度，童子犹思迎细侯。","出参方岳声雷动，复道中州又栖凤。","大省才贤岂易推，巨卿名位由来重。","黄河清洛静风埃，少室乔嵩云雾开。","行见虞廷咨岳典，共看商室济川材。","忆昔别公汝水上，太行西来隔千嶂。","抱病还依故里居，有怀空向夷门望。","夷门道接大梁东，车轮日日度春风。","道傍为问南来使，早晚朝端召寇公。"]},{"t":"木槿花歌","f":"七言律诗","c":["朝见花开暮见落，人生反覆亦相若。","夜来白露洒园藿，已是繁华不如昨。","朝花枝上斗绰约，暮花辞枝竟何托。","持花为谢青楼女，镜里容华不待汝。"]},{"t":"听琴篇","f":"七言古诗","c":["美人横琴坐我堂，酒阑为鼓三四行。","灯孤月明客不发，弦悲调急秋夜长。","吾家瑶琴久不拭，金徽玉轸无颜色。","感君对此如有情，一弹使我三叹息。","樵歌响答山涧幽，楚歌慷慨云夜愁。","潇湘猗兰稍平逸，四座但觉清商流。","始闻白雪停翠竹，烈飙吹我溪上屋。","忽然翻作广寒游，知是霓裳羽衣曲。","含宫移羽何舂容，泠泠万壑吟风松。","烟岑一夕怨鸣鹤，江天何处惊蟠龙。","我初好音惟好此，横笛短箫徒聒耳。","平生颇抱钟期怀，四海难逢伯牙子。","今夕何夕愿不违，为君击节泪沾衣。","高歌雅和人世稀，河转参横君莫归。"]},{"t":"怀三吉士","f":"七言古诗","c":["黄河西来走蜿蜒，睢漳之水相荡泊。","少室王屋俱峥嵘，太行林虑朝中岳。","含灵萃异几百年，中产三士诚磊落。","神标秀骨自殊众，水之文蛟山之鹤。","十年戢鳞在烟海，一日比翼栖云阁。","蔡君通朗及众艺，马氏多才步前作。","昂藏崔子抱群经，径操巨舸从伊洛。","文昌郁郁高中天，出入彼此同辉㸌。","玉京神仙皆有侣，茅斋野人少相托。","平生契谊怀数公，眼底安得常相乐。","眼底安得常相乐，联床并辔今如昨。"]},{"t":"观打鱼用东坡韵","f":"古风","c":["大鱼跳波如掷块，溪日溶溶照金背。","小鱼呴沫沿岸行，潜向沙边翻荇蒂。","家僮举网欣得鲜，持向庖丁割为鲙。","磁罂始见红尾摇，霜刃旋看锦鳞碎。","我虽爱此不忍食，悔不先教放溪濑。","自爱含生天地间，宁知失意波涛外。","嗟哉小物尚有然，人间得丧谁能会。","君不见鲲与鲸，钓者持纶空尔思，倏忽乘云下沧海。"]},{"t":"孤雁篇","f":"古风","c":["孤雁北来来几时，穷冬无侣鸣声悲。","云长路渺去安极，日暮天寒飞更迟。","洞庭潇湘落秋水，苦竹黄芦一千里。","清怨时从鸣笛生，断行暮逐哀筝起。","尘沙关塞愁转蓬，随风且落江湖中。","微躯幸免庖人俎，短翮长辞猎士弓。","君不见陇山鹦鹉解人语，一生自恨黄金笼。"]},{"t":"北风行","f":"七言古诗","c":["古申城边秋风落，北风惨惨夜复作。","玄冬烟雾卷寒沙，白昼雷霆出阴壑。","寒沙阴壑画难开，万里悲风何壮哉。","高空落木下不止，长路断蓬吹更回。","严威著地坤维裂，鹰隼入谷龙蛇结。","寒云冻月光杳冥，荒台古林气慄冽。","郭西村舍虽近城，萧条尽日无人行。","门前但闻衰柳折，墙外秪听枯桑鸣。","邻翁岁暮缺衣褐，茅屋欹斜用绳缚。","尘生釜甑暗不扫，寒入肌肤利如割。","堂上书生感岁侵，临风三叹不成吟。","暮花飘扬不可见，病叶憔悴伤人心。","出门黯淡天无色，冲飙四来山为黑。","黄河欲度波浪阴，沧海无梁星斗仄。","严霜大雪来几时，葳蕤朱凤号南极。"]},{"t":"白雪篇","f":"七言古诗","c":["玄飙作雪龙沙窟，万里吹花度南麓。","千门九衢堆已遍，翠崖丹壑沾应足。","曙辉寒素积崔巍，中天照耀琼瑶台。","羲和不知六龙在，仙人遥乘万鹤来。","依楼傍槛坠深院，轻罗白纻谁曾见。","已将弱舞斗回风，未遣明姿让流霰。","城中车马不动尘，党家金帐暖围春。","岂知穷巷衡门里，亦有当时高卧人。"]},{"t":"雨雪呈望之","f":"七言古诗","c":["北风萧萧天雨雪，洪川大陆冰嶙峋。","城闰咫尺不可越，念子郁郁伤我神。","十年骨肉更知己，四海兄弟今何人。","夫子风流本绝世，致身况在万里津。","顷聆清辞叩哀玉，复暏高价收名珍。","愚弟病归卧丘壑，山中日与蓬蒿亲。","喜看结驷来天上，又许题诗到水滨。","嗟哉十日不一见，眼底胜会真难频。","茅薝白日苦太短，秪有长夜堪留宾。","瓦垆木檠亦不恶，梅花柏叶俱鲜新。","只须对此共歌笑，莫使离别成逡巡。"]},{"t":"宝剑篇","f":"古风","c":["我有双龙之宝剑，重之不灭只吴钩。","雄游九天横素秋，雌鸣匣中声啁啾。","扶风豪士邯郸侠，千金在傍不敢酬。","雪花星文照玉玦，赠汝慰我心所求。","汝今年才二十四，北上长安见天子。","手翳凤凰跨骐骥，肝胆义气无与比。","古花江头春风起，绿袍青绶带秋水。","想见提携白日前，更看结佩青云里。","我初铸此良已劳，昆吾铁冶风雷号。","宝鞘玉珥黄金错，何以系之赤锦绦。","砍地翻虞沧溟倒，倚天未觉虹蜺高。","十年在匣尚未试，尝恐弃置成铅刀。","君不见丰城紫氛埋古狱，星辰夜摇魍魉哭。","奇器逢人自有时，肯使尘沙竟湮没。","又不见蓝田宝山空突兀，顽石却指神锋秃。","平生虽有不炼钢，一用不谨为弃物，吁嗟戴生尔无忽。"]},{"t":"寄王职方","f":"七言律诗","c":["故人王郎天上客，一岁寄书凡两束。","山中病夫俦侣稀，念子不见心转郁。","长淮浪高河无梁，我无羽翼到尔傍。","京师南来四千里，春鸿秋雁每相望。"]},{"t":"寄李空同","f":"七言律诗","c":["黄河腊月冰十丈，纵有鲤鱼那得上。","楚天鸿雁避霜雪，未得逢春难北向。","康王城边沙草曛，梁王台上多暮云。","野人岁晚谁相对，桐柏山中空忆君。"]},{"t":"嫦娥图","f":"七言古诗","c":["月宫峨峨冷光射，桂树长生花不谢。","玉宇琼楼闭早秋，金蟾银兔啼寒夜。","夜寒露下步瑶台，罗袜仙裙冉冉来。","屏障乍开云母隔，帘栊遥望水精开。","明星迢渺斜银汉，谁拟丰神传素练。","霓裳羽衣世莫闻，雾鬟雪貌人难见。","灵药空疑后羿妻，吹箫跨鹤几人迷。","君欲遨游广寒殿，直攀万丈青云梯。"]},{"t":"胡生行","f":"七言古诗","c":["近时逢人论术数，胡生相法称独步。","闭户时看人相篇，然灯夜读石室赋。","吾观此术非荒唐，异人历代各有长。","我朝名家亦不少，神妙无过袁柳庄。","君学本从袁氏出，识鉴至今如画一。","为客十年凡几更，阅人四海无一失。","初从燕市度生涯，一日声誉传京华。","衣冠每动公卿座，车马争迎贵戚家。","自从仗剑离京域，当时朝士无相识。","已往豪华不可论，只今形貌犹能忆。","漂泊江湖不自伸，袖中书在半埃尘。","穷途反遭俗眼士，末路难逢好事人。","昔闻燕邸招艺匠，袁生抱术金门上。","文皇自有天子须，群臣尽是封侯相。","君臣千载当一时，雅鉴风神犹在兹。","才殊未可寻常得，数偶还教际会奇。","古来相心不相体，眼前贫贱那能拟。","志士翻居草泽中，贵人多在尘埃里。","胡生谓我颜色奇，顾我已是云壑姿。","希夷不识钱若水，麻衣道士应当知。"]},{"t":"袁惟武山水图","f":"古风","c":["源潭窈窕开层岛，叠岭撑空互倾倒。","人家万树隔村原，细雨冥冥春更好。","清江柴扉映春草，樵歌渔唱归林早。","帆色遥随返照回，岸沙却被垂杨扫。","袁侯此图爱藏护，画手莫识马与顾。","挂壁盘纡见岩壑，开窗拂拭生云雾。","呜呼此图侯当珍重留壁间，万金莫买真江山。"]},{"t":"归来篇","f":"古风","c":["君不见陶公饮酒负奇气，平生下笔五千字。","不肯上书干明主，安能束带见小吏。","归来不愿千顷田，但须囊中有酒钱。","男儿委身事权贵，摧眉折腰诚可怜。","朱君雄豪气如虎，风期直与陶公伍。","青袍银带不复视，壮年弃官如弃土。","雅性好酒兼好文，眼中富贵岂足论。","五花换酒召宾客，千金买书遗子孙。","人生百岁终萧索，如子从容胡不乐。","未似原生少宿储，却比苏家多负郭。","长安陌上久离群，子亦还山卧白云。","南岩桂树花自发，岁晚相看一望君。"]},{"t":"雪中宴袁挥使惟武宅","f":"七言古诗","c":["四郊飞雪暗高城，北风怒号天杳冥。","将军宅中昼击鼓，哀筝鸣笛罗后庭。","我时冻吟在西野，忽见将军送书者。","开书读罢喜即行，邀我入门方下马。","凝辉绚素开帘栊，流风回霰满堂中。","青毡帐高雪不湿，兰灯夜照氍毹红。","卿家父子皆好客，能留对雪欢今夕。","已看称寿奉千金，况复徵歌出双璧。","梁园宾客多交游，谢家兄弟尽风流。","古人胜事长已矣，吾辈优游亦尔俦。"]},{"t":"鸿门行","f":"古风","c":["沛公昔日分义军，旌旗十万西入秦。","山东诸侯皆后至，咸阳万姓思为臣。","项王东来怒如虎，置酒朝会鸿门下。","门前壮士拥盾入，座上小臣拔剑舞。","争雄较胜未可量，相看杯酒成仓皇。","挥刀醉击玉斗碎，揽带空悬宝玦光。","沙丘城边祖龙死，芒砀山傍匿天子。","泽中夜闻白蛇断，灞上朝看赤云起。","君不见刘郎供帐出秦宫，宫中火照三月红。","英雄为谟自有术，亚父徒知杀沛公。"]},{"t":"垓下行","f":"古风","c":["咸阳原上失秦鹿，戍夫入关竞驰逐。","君王自负十尺躯，傍人更讶重瞳目。","横行按剑一何威，叱咤四海随指挥。","诸侯西向受金印，壮士东归尽锦衣。","阴陵道中夜失援，垓下孤军独迎战。","百万王师来震天，八千子弟随飞电。","自言百战当一身，宁知一败损威神。","美人帐下看无主，骏马江边弃与人。","楚歌声高暮云伫，孤灯对酒惨不语。","盖世英雄力拔山，一夕悲哀泪如雨。","君不见三军缟素行负戈，乌江不渡愁风波。","古来失道众所弃，父老虽怜将奈何。"]},{"t":"短歌行赠贾西谷","f":"古风","c":["城西草堂日无事，广文先生骑马至。","先生雅性嗜林壑，为爱吾庐有幽意。","长溪风起寒日冥，晚云含白冬树青。","山城沽酒不易得，为尔且系双银瓶。","先生好吟近颇酷，手书佳句已盈轴。","灯前朗咏三十篇，一一徽音中金玉。","顾予疏陋非良俦，感君过野常优游。","城中岂无万户侯，金盘玉馔不少留。","从来富贵安足慕，水上浮沤草头露。","君不见贾生自负洛阳才，南迁且作长沙傅。"]},{"t":"汉将篇","f":"七言古诗","c":["汉家西北烟尘起，烽火夜照西京里。","胡虏奔腾一万骑，关塞逶迤本千里。","飞符插羽募精强，连营列阵扫边疆。","已见将军屯细柳，更闻天子猎长杨。","长杨羽猎兵威振，叠鼓鸣钲闻远近。","龙虎遥分天上军，鱼蛇遍阅云中阵。","长安骢马侠少年，金鞍玉辔铁连钱。","共看拔剑追骄子，自许弯弓射左贤。","惊风昼起边沙涨，疏勒黄云迷所向。","饮马寒临月窟傍，躯兵夜度天山上。","降旗款节树戎城，卷旆回旌入帝京。","征人半死龙庭战，壮士俱标麟阁名。","麟阁功名不易得，贵臣良相徒颜色。","威胡尽道李飞将，还汉谁言苏属国。","玉门关外朔云愁，燕颔书生亦白头。","君王自忆廉颇辈，义士羞称万户侯。"]},{"t":"孤鹤篇","f":"七言古诗","c":["我家孤鹤李侯赠，霜仪皎洁三尺高。","向人似矜短羽翼，失侣岂免长呼号。","赤霄青云暮延伫，天长路远飞不去。","日来秋塘啄苦蓼，时向空墙倚脩树。","忆昔初在山人家，雌雄和鸣闲且嘉。","夜寒对舞庭中月，日暮双栖岭上霞。","李侯平生重幽德，致此远自东吴国。","金栊玉槛脱相送，异种奇毛惜不得。","一自天涯失旧行，垂头战羽空徬徨。","朝闻横笛音相和，夕对鸣弦影自伤。","荒阶雨湿多泥滓，毛翮摧颓风不起。","奋迅那推一鹗先，昂藏且在群鸡里。","吁嗟人世是还非，华表千年更一归。","蓬莱宫内青瑶树，会接文鹓比翼飞。"]},{"t":"冬雨叹三首 其一","f":"七言律诗","c":["季冬十日雨不娓，寒烟冻雾何凄凄。","城头无由见白日，坂下秪是愁黄泥。","乡中饿叟纳官赋，白头赤脚行中路。","薄暮临河望郡城，水深岸滑何由渡。"]},{"t":"冬雨叹三首 其二","f":"七言律诗","c":["一冬枯槁雪不集，细雨冥冥高岸湿。","天边鸿雁安所归，岁晚蛟龙不得蛰。","昨闻汝北多死亡，横尸委骨官道傍。","我里四邻久已出，到今不知死何乡。"]},{"t":"冬雨叹三首 其三","f":"七言律诗","c":["西望千峰万峰连，出门朝暮生云烟。","日傍雨脚下平地，风外涛头冲远天。","急飙北回振林薄，白昼孤狸行近郭。","城下饥乌啄死人，苍鹰侧来怒相攫。"]},{"t":"怀旧吟赠阮世隆","f":"七言古诗","c":["君家高楼对芳树，开宴曾留三日住。","铜槃绛爉煖照春，金壶银漏寒催曙。","知君重义多豪游，满门宾客为我留。","珊瑚不避铁如意，骅骝皆缠金络头。","尔时北上与君别，蔡州城外花如雪。","梦里犹寻汝上云，醉中却忆淮西月。","丈夫富贵各有因，如君立身亦不群。","行年四十未白发，生儿十八期青云。","君从秋日遥分手，我向东风一回首。","山下长搴旧薜萝，楼前应长春杨柳。"]},{"t":"官仓行","f":"七言古诗","c":["长棘周袤三丈垣，高门铁锁缄两关。","黄须碧衫下廒吏，白板朱书十行字。","帐前喧呼朝不休，剪旌分队听唱筹。","富家得粟堆如丘，大车槛槛服两牛。","乡间饿夫立墙下，稍欲近前遭吏骂。"]},{"t":"除夕醉歌二首 其一","f":"七言古诗","c":["今岁相逢惟此夕，美人金樽莫虚掷。","千金一刻真可惜，夜久衾帷望河汉。","寒星欲没明灯烂，长歌坐待东方旦。"]},{"t":"除夕醉歌二首 其二","f":"七言律诗","c":["孤城岁徂叹幽独，举觞醉饮城西曲。","野风萧条山雪暮，寒梅无花柳难绿。","今年今日不可留，明日明年更可愁。","山中纵有如渑酒，春花烂熳与谁游。"]},{"t":"醉歌行赠柴逸士","f":"七言古诗","c":["今年中秋与君共，举觞待月城西宅。","良夜清尊逢故人，空堂明烛留远客。","山城暮云黯未收，流烟何时散高楼。","清风徐来劝我饮，明月不至令人愁。","君是长安旧相识，坐论旧事还相忆。","金市豪华如梦寐，玉京仙侣无消息。","人生去住安有同，有如长风吹断蓬。","得随江湖扁舟外，不恨关山横笛中。","酒中云散天如洗，月明忽堕金樽里。","起看皓彩发青峦，坐见流光盈绿水。","阔舞高歌夜未央，揽衣击节为君起。"]},{"t":"和献吉送公顺","f":"古风","c":["君不见池中鱼，君不见泽中蛇，一朝羽翼起烟雾，向时头角盘泥沙。","神物舒卷各有时，男子岂得常在家。","君今年才四十馀，双?驷马高盖车。","手中持文符，腰下佩辘轳。","登山采球琳，涉水采珊瑚。","吁嗟至宝今岂无，莫使和氏空号呼。"]},{"t":"古峰画梅歌","f":"七言古诗","c":["空江月堕孤山晓，直干横枝疏更好。","夜来梦破碧窗虚，残雪半庭寒不扫。","小桥水浅影初斜，野径风清香未老。","霜蒐月魄独俜停，玉骨冰肌自枯槁。","溪头数点瘦花明，坞云漠漠林烟渺。","逋翁湖山诗思闲，寂寂柴门春醉倒。","山亭昼午鹤飞还，一声长笛江门悄。"]},{"t":"登山吟","f":"古风","c":["风吹葛蔓石磊磊，萝薜摇烟映山鬼。","我行登山采石耳，长歌捎林暮风起。","君不见侍傍桃李飞如霰，青春已破白日晏。","万事尽付东流波，高飞且叹南来雁。"]},{"t":"落花叹","f":"古风","c":["君不见树上花，东风吹始开。","东风吹开更吹落，世间有乐宁无哀。","汝南何生未三十，头发未白心已灰。","见此落花三叹息，东风吹去何时来。"]},{"t":"复见阮生行","f":"古风","c":["阮生别我尚总角，三月不见冠峨峨。","未知华实竟何似，眼看玉树成枝柯。","君不见世间日月翻如波，昨日黑发今则皤。","龙驹千里汗成血，道傍老马空蹉跎。","人生少时不努力，齿大身长嗟奈何。"]},{"t":"古井篇","f":"古风","c":["君不见城边古井荆棘荒，沙崩雨塌官道傍。","当时碧甃映朱阁，黄金阑干银作床。","美人铜瓶响哀玉，宁知委弃同悲凉。","梧桐花乾藓花涩，鹭鹚侧窥蚯蚓入。","百丈寒泉尚堪饮，心长绠短空愁立。"]},{"t":"古松歌","f":"古风","c":["贤隐寺傍之古松，奇绝可比徂徕峰。","问之故老迷岁月，但见皮肉屈疆苔藓裂。","高枝上掣玄冥风，回柯反扫阴崖雪。","藤翻蔓卷空林黑，集霰流烟岂终极。","斧斤相顾畏盘错，梁栋谁来誇正直。","昔予山游驻车马，行吟屡憩兹松下。","松根老僧为开径，野色岩姿坐生暝。","叶暗秋灯梵殿深，花香晚饭斋厨静。","一年幽忧不到此，宁知摧折空山里。","龙盘虎拿终有神，白骨苍鳞半枯死。","沧波古岸霜气夕，硉矹犹看数千尺。","石上连朝走云雨，山中十月飞霹雳。","千灵百怪相护诃，过客居人尽怜惜。","君不见泰山五大夫，零落今看在何处。","沧海空流使者槎，悲风暮起将军树。","呜呼人生富贵竟何益，松乎松乎，吾当为尔诛茆傍青壁。"]},{"t":"陇右行送徐少参","f":"古风","c":["陇右地，长安西行一千里。","秦日长城号塞垣，汉时故郡称天水。","圣朝扫荡无烽烟，射猎之地为桑田。","熟羌卖马常入塞，将军游骑不出边。","知君风采古遗爱，扬策传符度关内。","父老三秦望节来，犬戎诸夷遮马拜。","开藩分道镇边尘，居守巡行历几春。","熊轼朱幡今岳伯，豸冠白笔旧台臣。","瓦亭之西半山谷，土室阴阴连板屋。","落月孤城清渭源，寒云古碛黄河曲。","十年此地曾游歌，别来风物今如何。","竹花秋临鸟鼠穴，杨叶夕渡鱼龙波。","回看万里风云色，少小趋庭泪沾臆。","相送悲吟不尽情，关山陇坂高无极。"]},{"t":"游西峰示四子","f":"七言古诗","c":["今我不乐游西峰，喜有四子来相从。","日长古寺风景静，蜀葵始青榴始红。","彭生旧时同游者，每遇游山先跨马。","徐生爱山欲留宿，朝见青山独开目。","自云邑城尽原野，颇恨无家傍林谷。","陈阮二牛皆少年，陈生家亦近此山。","阮生志不在山水，骑马欲行乃复还。","吁嗟汝辈各努力，此身会见生羽翼。","乘风高举或远游，安得久为山人留。","他时倘愿骑黄鹄，随我江边伴白鸥。"]},{"t":"甄邦治行乐图","f":"古风","c":["黄金虽有馀，不如常乘下泽车。","紫绶结腰下，不如常骑款段马。","人生富贵皆有忧，岂必只愿封公侯。","君今出有骏马更轻裘，及此壮年当出游。","西飞日月如东流，君不见，马少游。"]},{"t":"长安大道行","f":"七言古诗","c":["长安大道如弦直，车马相逢不相识。","金鞭玉毂共争先，日日红尘大道边。","七贵门前罗将相，五侯座上列神仙。","五侯七贵同杯酒，万骑于夫尽奔走。","一言得意贱可贵，百计奉身无亦有。","杯酒经过日共游，比权并势暗相谋。","才见黄金结兄弟，忽看白刃起仇雠。","薰天灼地期长久，覆雨翻云亦随手。","富贵谁言福作门，骄奢终与祸为邻。","瑶台歌舞新更主，金谷池亭别与人。","豪宾贵客如风霰，鞍马当时倏雷电。","得饱空闻鞲上鹰，附炎不见梁间燕。","寻常只道太山安，顷刻宁知沧海变。","秋来春去互推迁，物理相寻是等闲。","岂知盛满衰仍至，岂识忧从乐极还。","独怪梁生何感慨，拂袖长歌辞汉关。"]},{"t":"入京篇","f":"古风","c":["轩车若水流，宫阙似云浮。","畿田一千里，山河十二州。","城中甲第共崔巍，别起云甍接露台。","旭日才临万户动，飞尘遥见九关开。","九关鸡鸣竞车马，百僚已集金门下。","入卫皆为龙虎军，来朝尽是貂蝉者。","天子乘春览物华，霓旌羽扇五云车。","六龙不驻千官仗，匹骑常过七贵家。","七贵家连凤城里，转日薰天势无比。","池榭春来锦绣围，楼台日暮歌钟起。","复有蒙恩过董仇，执柄持权得自由。","不使府中除将相，直教门下谒王侯。","王侯贵人慕豪富，意气相看益骄妒。","未惜朱闲騕袅驹，岂论金谷珊瑚树。","托身日月有光辉，举翼风云多会遇。","可怜汉室盛衣冠，扬雄蓬巷独饥寒。","终岁校书空闭阁，十年执戟不迁官。","公孙射策取卿相，李广冯唐徒自叹。"]},{"t":"送熊廷振之楚藩","f":"七言古诗","c":["燕京春色花太半，豫州杨柳风吹断。","南雁新冲汝雪来，北车久待河水泮。","与君结绶俱明时，送君执手如前期。","丈夫勋业岂必少，四十遭逢犹不迟。","即今君身更磊落，义气如山谁可夺。","同榜衣冠照乡里，十年名位登方岳。","帝城朝开罗旆旌，欲发未发明星明。","麒麟献纳遥相忆，江汉风流须此行。"]},{"t":"送顾锦衣赴广东佥宪","f":"古风","c":["君不见锦衣白马若雷电，当朝气势人争羡。","顾君出入身不移，心看富贵同贫贱。","二三贵人随至尊，冠冕剑佩如云屯。","青袍自向将军幕，款段不叩诸侯门。","外台新捧广州檄，青冥斧钺生霜日。","海峤诸城发鼓迎，江天万里褰帷出。","丈夫不言自立身，清水白石何粼粼。","金张门客不足数，峣峣赫赫何为人。"]},{"t":"送樊生","f":"古风","c":["翩翩南图鸟，昔是北溟鲲。","才见搏风一日起，忽看垂趐九天云。","樊生此行览吴越，大江石城通日月。","岧岧南京十二楼，波浪蹴踏金银阙。","尔上金陵望帝关，星河北极开幽燕。","丈夫常怀金海志，才人亦赋两都篇。","排空万里有毛质，再接扶摇上九天。"]},{"t":"彭生行","f":"古风","c":["岷峨山根江水坼，万里波涛混吴越。","倾湖倒海不可量，仰看一线青天上。","郁蓝秀色盘三巴，间产锦石兼丹沙。","王严扬马各挺出，异才岂必生中华。","彭生昂昂千里驹，少年骑马来成都。","飞黄騕袅未即试，已觉奇气排长途。","君不见岷山不崩江不枯，古之高才何代无。"]},{"t":"黄河篇","f":"古风","c":["黄河昆崙源，九曲与天通。","银汉贯箕尾，左盘日月宫。","奔流下龙门，喷薄沙海风。","三山万里倚穷发，鳖极虹梁开恍惚。","排空雪赣垂银城，便可因之向溟渤。","郭生少年观上都，还家且泛黄河舻。","读书岂必破万卷，览胜何须行九区。","蓬池已在梁园里，啸歌绿水洪波起。","扬帆他日乘高秋，见尔星槎挂斗牛。"]},{"t":"三清山人歌","f":"古风","c":["山人佩剑冠远游，腰间鞶囊垂虎头，七星照耀金银钩。","东行策杖指卢霍，逝将沧海寻丹丘。","三清西南龙虎连，攒峰叠翠盘石莲。","千崖万壑不可以径度，玉梁倒挂银河前。","青蜺下望熊云烟，石璧中开日月悬。","傍通七十二福地，白玉楼台罗洞天。","此中栖身炼大药，宝笈灵书启五岳。","骑鹿时见南斗君，闻笙夜候缑山鹤。","我今游目送冥鸿，欲访名山入越中。","飞梁万丈倘可接，共尔青天蹑彩虹。"]},{"t":"昔游篇","f":"古风","c":["三星烂夜河汉流，觞行瑟作中堂幽。","李君勿叹息，薛君且停讴。","英英孟夫子，听我当筵歌昔游。","昔游少年观上都，并辔骄嘶只紫骝。","云中十二楼，罗绮照燕州。","夹槐复道临仙苑，垂柳通阛对御沟。","平明向帝宅，半醉过王侯。","游梁词赋那称数，入洛声名未足俦。","自言与我共联翩，塌翼宁知落九天。","折花别青门，挥袂渡湘川。","班竹古魂垂泪雨，苍梧遥梦结愁烟。","南岭越江坳，东城移海郊。","不记流年几抛掷，五见杨柳垂青梢。","鸿雁散他县，鹪鹩栖故巢。","君从岐路悲转蓬，我在长安嗟系匏。","金门上书久不报，云阁题诗空自嘲。","以兹守蹉跎，旧客罕经过。","日与李薛辈，诗酒纵欢歌。","春风宛转青丝鞚，夜月留连金叵罗。","笔翻翠虹霓，手掣生蛟鼍。","三千艳女罗紫宫，倾城一笑扬双蛾。","星分雾散去长安，岂意天垂云雨欢。","龙剑雄雌忽复合，朝天再睹汉衣冠。","帝京宫观一如昔，盘龙曲凤青云间。","九衢车马流如水，五侯甲第峙如山。","星枢常不转，海岳自回环。","昔日绣衣一何贵，今看窜逐宰河关。","可怜旧宾友，逝者谁复还。","二三壮士力搏虎，转盼埋骨黄泉湾。","荣华闪烁若电露，俛仰今古凋朱颜。","君不见汉季广，威名万里匈奴闻。","弯弓贯白石，射虎生黄云。","一朝谢病逢醉尉，灞亭不识故将军。","君不见秦范雎，折胁摺齿随王稽。","一言夺相印，七国趋关西。","雄豪赵魏二公子，徒使虞卿从魏齐。","贵贱倾覆如旋风，王侯岂异鸟与虫。","鲁连独蹈沧海去，张良仍从黄石公。","孟夫子，总角与君戏，共许非凡伦，万金騕袅腾天云。","子今胡为在风尘，低头腼向男子身。","笑子落魄亦如此，痛饮狂歌非隐沦。","回首向崧岳，少室高嶙峋。","寂寥紫芝曲，空负桃花春。","会须约尔同归去，为招李薛两才人。"]},{"t":"赠商三","f":"七言古诗","c":["去冬雪雨留蓟门，开筵谑浪倒金樽。","今春灯火到长安，过门不肯回银鞍。","燕山花隔平山柳，马上东风几回首。"]},{"t":"大梁吟送李进士","f":"古风","c":["大梁擅豪华，钜野生龙蛇。","顷乘曹李辈，擢秀冠诗家。","神驹并逐两超绝，凡马百万空咨嗟。","李邕门下多奇士，曹是贤甥李高弟。","登龙自昔忝通家，附骥相看总名世。","梁王台馆罢歌钟，兔园宾客有遗踪。","侯嬴旧隐夷门里，李渤今归少室峰。","回望嵩高瞻岳首，即寻玄圃问河宗。","可怜二子诗家秀，吾生已愧卢王后。","司马黄金赋未逢，杨雄白首书空就。","李当春日别燕川，曹也诵诗神黯然。","蓬池更忆阮公啸，肠断洪波绿水篇。"]},{"t":"东海太守行赠徐以敬","f":"古风","c":["西曹大夫，东海太守，且停尔车饮我酒。","二十读书饱经术，腰下组绶无一尺。","一朝天子赐五马，十年官至二千石。","汉家盗贼满山东，十城九城荆杞中。","玉食常怀股肱郡，苍生久慕循良风。","况君兄弟皆甲第，出入光辉无与比。","兄飞仙舄宰王畿，弟握侯符长千里。","四世五公自此始，不见关西杨伯起。"]},{"t":"石斋歌","f":"七言古诗","c":["濯锦江中锦为水，白石粼粼映江底。","江头斋阁石嵯峨，卜筑题名总因此。","崖撑壑拄盘天地，产秀生神岂人意。","日月宵通滟滪根，风云昼吐岷峨气。","明公少年天下奇，琅玕五色动光辉。","扶疏太华仙人掌，照耀银河织女机。","明堂大厦要梁栋，不独文章翰林重。","恋磬真谐韶濩音，国琛困献圭璋用。","公登云阁望云林，霄汉长歌白石吟。","功成思袖补天手，力在宁忘障海心。","卫公德业怀应满，李相风流今不远。","海内完名已玉成，平生贞志同金断。","万里桥边绿竹园，百花潭畔平泉馆。","待公一起慰苍生，还卧西山未应晚。"]},{"t":"五马行","f":"七言古诗","c":["使君五马来月氐，方瞳夹镜光离离。","长身峻耳高七尺，锦云窣地王花赤。","杏鞯蹙镫只盘龙，文羁翠刻金玲珑。","青丝游缰绾不住，铁色蹄翻锦苔地。","天闲沙苑贮几时，一朝分赐使君骑。","使君行春常露冕，组鞚张油下山县。","朱文露网动轻车，四野人家望通幰。","去年来时楚江秋，长鞭驰过黄鹤楼。","楚城骏马千万匹，解鞍坐视不敢俦。","今年朝天入五凤，红缨宝玦连钱重。","晓随鸾声撼玉珂，九陌风微尘不动。","天子命下巡吾州，辉光重整金络头。","吁嗟吾州本狭促，迮径宁当千里足。","行行前驾肃且闲，郡人遥望只旌竿。","驰道父老应开颜，区区狐豕谁敢前。","桑条吐叶青郁郁，满路春尘绕车毂。","使君不惜驱驰劳，无令暴吏登民屋。","出门一送五马行，我马踟蹰皆不鸣。","相逢同是他乡客，惆怅城边暮春别。","山亭草色细雨时，野馆梨花寒食节。","夕阳微微邺城树，寒烟漠漠淮川月。","愿言努力策霜蹄，千金重有登台期。"]},{"t":"忆昔行","f":"古风","c":["我年十一十二馀，与子握手相欢娱。","严君视我犹视子，日向庭前问诗礼。","我亦视君如弟兄，夜入同衾昼同起。","当时见子已不群，红颜如玉目有神。","花边灿灿丹凤雏，天上矫矫石麒麟。","笑予是时尚垂髫，把笔从君弄文翰。","联翩白马控只御，出入城中谁不看。","我当辞归君失欢，徘徊欲别良独难。","别来有怀徒怅望，梦绕秋风沁水寒。","杳杳云鸿异乡县，十载长安见君面。","昔别未冠今已婚，回忆少年空叹羡。","一官碌碌经三春，二十光阴似飞电。","君有长才未得施，卧龙仪凤犹栖迟。","男儿成名在少壮，感会风云须及时。","人生聚会岂常有，但愿相知不相负。","君不见古来金石交，结发寸心期白首。"]},{"t":"忆昔行","f":"七言古诗","c":["忆昔长安相会日，君方壮年我年小。","只今容颜有更变，何况世事无纷扰。","先帝衣冠半零落，十年宾友全稀少。","君今始作紫薇臣，笑我金门落魄人。","冯唐上书亦叹老，子云识字空愁贫。","艳阳三月桃李耀，君非壮年我非少。","花开酒熟君远行，可惜春风阻欢笑。","明星迢迢车关关，遥向楚水辞燕山。","但看朱绂在腰下，莫使白发生颅间。","武昌城边江色淀，襄阳汉水尤堪羡。","东行何日访鲈鱼，南飞不得随鸿雁。","少癖山水耽云松，两年楚上多行踪。","浮湘直下三千里，望岳遥瞻七七峰。","知君跌宕轻驷马，顾予岂是功名者。","安得浮沉帝座傍，会须览眺苍梧野。","苍梧风烟秋色开，武昌高楼吹笛哀。","帝乘白云去不返，仙人黄鹤何时来。","君行访古兼化俗，长楫輶轩指南极。","岸上游穿罴虎林，潭中坐傍鼋鼍国。","他时倘觅桃花源，北风为尔传消息。"]},{"t":"田子行","f":"古风","c":["君不见黄河西来北入海，千载却倒东南流。","淮水如丝纳九曲，桐柏山作昆崙丘。","我家清淮边，君家大河侧。","开辟二水今合同，人生变化无南北。","田子之生河降神，十五手掣生麒麟。","二十辞家观国宾，三十谒帝为近臣。","赤墀青琐日月上，金马银台河汉津。","自矜一身遇明主，便欲登天叩天鼓。","天门昼关守虎豹，云师屏翳西公怒。","烟气缥缈随飞龙，电光闪烁笑玉女。","太清星辰下罗列，欻忽阊阖生风雨。","丹诚不回白日照，杞国忧天独劳苦。","我持彤管只凤翎，浮沉帝傍近紫庭。","文园著书久消渴，据地酣歌常不醒。","长安少女花在侧，茂陵美妾空娉婷。","汉皇不好相如赋，方朔谁知是岁星。","爱君襟期特奇迈，谏垣给舍持风采。","平生古今开万卷，摇笔风云动五彩。","致君尧舜岂无术，许身稷卨终难改。","袖中一扎谏猎书，三岁磨灭未见采。","鍊石何时更补天，衔沙枉自思填海。","君不见楚人当时不识玉，海客无心采明月。","明珠暗投反按剑，白璧三献还遭刖。","连城高价后始定，照乘奇光有时发。","凤凰不及鸱鸮鸣，驽骀却笑骅骝拙。","君不见长孺从来叹积薪，公孙布衣为汉臣。","千秋开口取卿相，董生白头甘贱贫。","万言不如一言重，直弦曲钩安可论。","贾生何能善绛灌，任安徒事卫将军。","我令与子俱落魄，过饮悲歌嘅今昔。","咸阳酒客五花马，邯郸博徒千金掷。","古来豪侠亦可喜，可怜圣贤皆厄塞。","豫章干云世希用，龙泉贯斗人难识。","神骏翻为辕下驹，冥鸿已愧笼中翼。","出门与子常相忆，清淮大河见颜色。"]},{"t":"少谷子行","f":"古风","c":["少谷子在武夷之山，二十抱策叩燕关。","朝排阊阖暮湖海，九霄万里身翻攀。","岂徒声名冠帝里，要使踪迹穷人寰。","朅来京华始一识，意气形神两相得。","肺腑真成水石痼，词章亦带烟霞色。","龙姿鹤性不易驯，海思江清浩无极。","顷将东游观岱宗，便欲下泛沧溟中。","鼍风奔浪岩洞黑，鳌日压山楼观红。","南浮红淮览吴越，复工会稽探禹穴。","去鸟晴生雁宕云，飞虹夜蹑天台雪。","波涛窈渺岑崿移，遍访名山入武夷。","仗剑不忧百怪出，采芝或得群仙随。","只今妙年始三十，辞官读书志何逸。","九曲烟花对草堂，三山萝月开芸室。","已看凤凰在千仞，回首骅骝空万匹。","八月高城气稍劲，流萤木叶交相映。","燕山游子落日吟，海滨归客秋风兴。","他日遥寻少谷峰，武夷莫作终南径。"]},{"t":"九川行","f":"古风","c":["君不见自从天地开，天下之水皆西来。","黄河昆崙一线出，下转秦甸轰奔雷。","长江广汉两荡潏，浊泾清渭中萦回。","帝遣九龙下治此，江汉安流泾渭理。","华岳中断仙掌高，却放黄河行万里。","九龙蜿蜒上天去，至今犹馀九川水。","秦中云雨四时遍，北地尘沙几回徙。","我来长安不见九，川水得见九川子。","九川子是非常人，朝辞川上麋鹿群，夕盒青琐为帝臣。","已从华衮补日月，况执彤管排风云。","长风西来吹北极，西望川流渺何极。","野岸空悬舟楫心，塞林暮绕波涛色。","吁嗟江汉犹阻兵，中原不见黄河清。","虺蛇豺虎满道路，黄埃浊浪无人行。","九川子，何不更鞭九龙起，坐视天下横流水。"]},{"t":"送叶生还闽中兼怀郑继之","f":"七言律诗","c":["叶生行吟燕中市，葛巾麻鞋岁将晚。","两都为客今始归，五岳寻仙不辞远。","江南画舸春柳低，海上茅堂白云满。","谷口如逢郑子真，为道栖迟未应返。"]},{"t":"送林利正同知之潮阳","f":"七言古诗","c":["忆在成均共携手，泉山门下相知久。","万里恩情若父兄，十年道义惭师友。","君才岂孤一第名，佩刀今作岭南行。","挂帆夜宿天边树，伐鼓朝登海上城。","燕京相逢颜色好，相逢何难别草草。","过家登堂寿礼毕，道予问讯泉山老。"]},{"t":"金陵歌送李先生","f":"七言古诗","c":["李公为舅有吕甥，甥舅四海皆知名。","吕君关西昨日去，公自金陵来复行。","金陵江水无断绝，金陵之山高巀巀。","龙虎千年抱帝京，星辰万里罗天阙。","白鹭洲前芳草歇，清江浦上看明月，燕山北望花如雪。"]},{"t":"今昔行送何燕泉","f":"古风","c":["君不见燕泉何子生南岳，十八名声动江海。","年今四十少方伯，富贵由来重文采。","金章紫绶乃自致，黑发红颜未曾改。","忆初射策逢先皇，我为进士子为郎。","芳花醉踏清沙苑，春树迎开画省堂。","每投桃李报琼玖，多谢相知更相厚。","倚玉元非异姓兄，断金况是同心友。","宁知世事多变更，岐路人间各分手。","四海风尘半甲兵，十年意气还杯酒。","子方出守紫薇垣，予亦栖迟金马门。","黄金尽识故交态，白璧翻思明主恩。","中原送别哀离乱，汝水嵩川客心断。","行马秋临清洛流，战场暮吊黄河岸。","蓟桑青青燕草碧，梁王城边杏花白。","功勋名位行有期，慷慨为子歌今昔。"]},{"t":"醉歌赠子容使湖南便道归省兼讯献吉","f":"古风","c":["徐卿此行壮观莫与伍，东将入吴西入楚。","都门怅饮慨今昔，酒酣拔剑为汝歌起舞。","圣朝分封重茅土，词林礼桨超前古。","冠冕诸邦拱至尊，册书十道开天府。","匡庐峰南绕江汉，洞庭武昌半楼观。","寿酒花开海上堂，使舟草满湘西岸。","忆卿翻飞霄汉里，结交岂少青云士。","眼中何人最知己，十年之交吾与李。","李生近买阳羡田，又欲鼓柁襄江船。","风尘落日倘相遇，为我问讯江湖前。"]},{"t":"薛生行","f":"古风","c":["君不见少府忘年交祢衡，中郎倒屣迎王粲。","坐间宾客尽倾倒，海内贤豪流英盼。","古人爱才今不如，薛生岂得无嗟叹。","昨来布衣见天子，日向长安乘款段。","公卿门前耻干谒，东归把钓黄河岸。","年少今看万卷开，远游自负三山愿。","丈夫有才须用世，未许终身随草蔓。","闲居好著子虚篇，行路长歌白石烂。"]},{"t":"晚过田水南有赠","f":"古风","c":["田郎闭门著书今几卷，我欲与子数相见。","谑浪虽称青琐贤，经过罕识黄门面。","长安雨积鞍马稀，堂下苔生集秋燕。","四海何人问草玄，一经徒使桓谭羡。"]},{"t":"延津歌送韩令","f":"七言律诗","c":["延津寇过馀少男，延津县令莫停骖。","双凫直向黄河北，一雁先飞清卫南。","黄河岸边不种麦，浊浪滔天多贾客。","城中少男尔勿愁，县令到时为买牛。"]},{"t":"谷进士宴归图歌","f":"七言古诗","c":["五城十楼春窈窕，九衢夜半人行少。","月高醉客金鞭垂，花簇银鞍弄騕袅。","我皇九载罗豪英，坐收四百皆才名。","四百人中见谷生，绿袍白面谁不惊。","谷生自昔中州士，布衣三来谒天子。","十年读书梁王台，一日走马长安市。","长安钟鼓声入云，相逢却避新郎君。","赤鲲在天振羽翼，神骏得路超凡群。","呜呼此图人共羡，已识君身不贫贱。","万言莫忘北阙书，千载常记南宫宴，呜呼此图人共羡。"]},{"t":"远游篇送杨中舍承家云南省墓","f":"古风","c":["君不见昆明池，去京一万里。","山盘海曲在天上，日转星旋罗地底。","生神发秀千百年，太宰源流自兹始。","七岁辞家朝帝京，登台践斗荣身名。","水木更起丘原情，请帝帝遣中书行。","中书此行天子重，赤车驷马都人送。","岳楼昼锦湖光开，京口春帆江色动。","潇湘鼋鼍经水国，衡巫瘴疠云来黑。","铜柱标南问南纪，锦官城西指西域。","挥毫凭轼惊蛮夷，却似太宰中书时。","相如使蜀人同羡，迁史浮湘志自奇。","忆昔滇中为使者，黔公宴我滇山下。","酒罢曾弯壮士弓，赋成尚倚将军马。","今日看君万里归，山川草木倍光辉。","公卿礼数古来少，父子声名天下稀。","五华冈头日朝放，点苍山北云如障。","远游可乐须皂还，帝里亲闱两相望。"]},{"t":"裕州行","f":"七言古诗","c":["今年春夏雨不绝，黄河以南渐杀麦。","裕州城中十万家，自经寇盗惟黄沙。","名商大贾岁不集，新丝旧谷嗟何及。","郝侯五马天上来，褰帷露冕开风霾。","教农服田贾服贾，只有牛马无豺虎。"]},{"t":"石川子歌","f":"古风","c":["石川之水，东流入东海。","涛雷赣雪几荡啮，白石烂烂色不改。","泰山嵯峨青石室，楼阁窈窕云雾密。","悬峰窗牖瞰海底，红轮倒影扶桑日。","波上三山渺安在，海灵冥冥现百怪。","蛟螭九首盘为梁，神仙万古长相待。","石川子，七年葺茅卧烟岛，餐藜被褐身怀宝。","海东隐沦见面难，地北潜夫著书早。","自从召起绾银章，常梦山中把瑶草。","白雨青萝昼自垂，沙风赤叶秋空扫。","京华相遇谪仙才，笑解金龟沽绿醅。","花边昔放双凫去，云里今骑一鹤来。","蒋琬元知非百里，李渤终为谏官起。","冥鸿逝鹄须尔期，天路云衢自兹始。","君不见鲁门海鸟本避灾，国人祀之反求福。","虽有钟鼓罗玉馔，惊鸣骇顾安能食。","男儿固要为龙蛇，胡为屈身终日随尘沙。"]},{"t":"杏林曲","f":"古风","c":["君不见萧御医，何年种杏成杏林，霞蒸日烂开芳甸。","门庭垂实虎昼守，飞花九陌人人羡。","菊泉橘井俱仙灵，岂如万树春风散。","今皇御医皆不贱，麒麟绯袍常引见。","奉诏时翻本草经，承恩数锡仙桃宴。","君今一身官未尊，白头抱艺趋金门。","轻财重义世罕比，起死回生不自论。","林中有草金光映，服食可以延寿命。","萧君萧君进此药，令我皇帝万岁无疾病。"]},{"t":"周仪宾朝天歌","f":"七言古诗","c":["周君来从大梁发，摇鞭却指秦楼月。","燕山腊尽春未生，可怜裘马冲霜雪。","忆昨云霄谒帝关，春卿引见紫宸班。","天门九重罗虎豹，一月不得朝龙颜。","馆甥帝室恩数少，尚女王家礼非小。","中山更传闻乐对，陈王亦进通亲表。","伊昔梁王全盛时，车骑从官皆汉仪。","遣使常闻八珍送，入朝数赐飞龙骑。","百馀年间事势殊，诸侯出或乘驴车。","朱门宾从想冠剑，白头王孙行路衢。","君归为我一问讯，梁园赋客今何如。"]},{"t":"送五清先生赴浙江提学歌","f":"古风","c":["天台文宿冲紫霄，先生奉敕驰星轺。","越山桃李花万树，春色早渡钱塘潮。","忆昨先生遭斥逐，漂泊湖湘望巴蜀。","九江鸿雁春冥冥，七泽龙蛇昼盘曲。","洞庭天高急霜霰，冰河雪岸开燕甸。","北来骢马一日闻，倾都走识先生面。","十年卜筑楚村墟，万里今瞻汉宫殿。","当朝门生贵不少，先皇学士人犹见。","金门谁留供奉班，银鱼旧锡恩荣宴。","长安春回独回首，翠烟渐入龙池柳。","蓟门禹穴自此分，送饯先生百壶酒。","丈夫轗轲心不疑，贤圣流离古来有。","已看身作指南车，况复名高悬北斗。","隋珠和璧世珍重，眼前点毁终难动。","圣人不久奏云门，海内近亦求梁栋。","琴瑟须聆清庙音，豫章且待明堂用。","我闻衡岳与天参，七十二峰江汉南。","不然从此可栖息，无使天柱石鼓空巉岩。"]},{"t":"赠范君","f":"七言古诗","c":["桂阳之山石巃嵷，四时云气流杉松。","江开秀色蟠三楚，天削芙蓉罗七峰。","翩翩烟雾下凤鷟，往往霹雳随蛟龙。","钟奇产异理亦有，黄金丹沙间琼玖。","何况人杰非地灵，硕士名儒映先后。","君山燕泉各一时，晚逢范君亦其偶。","范君古貌更好古，问之君山乃其祖。","学海遥闻前辈风，辞场独觉良工苦。","君为进士宰江县，颇厌簿书耽笔砚。","神龙未应困泥滓，骅骝会自追风霓。","君山十年绝相见，见君如见君山面。","燕京四月花满甸，邂逅不得同游宴。","花间送尔双凫翔，庐山高高横玉梁。","云停雁过一回首，月明琴静谁举觞。","我自辞家来帝乡，宿宾旧友稀登堂。","怅望南邦思桂阳，怠今道故增悲伤。"]},{"t":"相逢行赠孙从一","f":"古风","c":["长安风吹万物柳，与君走马相逢久。","昨朝邂逅尊酒间，二十年来一回首。","我官十年前，君官十年后。","眼底相看已壮龄，世间万事真翻手。","忆初少小来柬曹，君家兄弟同游遨。","尚书庭前两玉树，白日灿烂秋风高。","尔时见君气已豪，花颜云发青锦袍。","石麟在天动鳞甲，赤凤排云生羽毛。","只今骨格殊恒调，倾都见者嗟英妙。","恨不置之玉堂宾，谁令久待金门诏。","永嘉山水称绝奇，且与谢客同襟期。","花里开帘仙吏出，松间著屐山人随。","尚书风义古无比，如君更是尚书子。","尚书东山閒白云，高卧不为苍生起。","汉庭我亦东方生，怅望名山无限情。","海云浩歌起春色，送尔万里东南行。"]},{"t":"李大夫行","f":"古风","c":["君不见大梁李进士，年未三十官大夫。","金钟翠釜识国器，汗血飞黄看过都。","昨来走马长安道，一日声名尽倾倒。","墨卿学士兢迎致，摇笔登坛为挥扫。","卢前王后不足论，曹刘沈谢升堂早。","我方避世金门前，君独时时问草玄。","金声一掷天台赋，凤沼常留春草篇。","忆年二十当弱冠，结交四海皆豪彦。","文章天上借吹嘘，杯酒人中回顾盼。","十年流落失边李，词场寂寞希篇翰。","自从去岁得李薛，令我倡叹增颜色。","对坐相看两凤毛，破围实藉千军力。","安阳崔史文绝伦，意气颇与二子亲。","苏台徐卿爱才者，曲卷往往停车轮。","斯文在天未坠地，我辈努力追前人。","波颓澜倒挽一发，鲸翻鳖掷争嶙峋。","薛生归钓黄河岸，君亦遥维沔川缆。","霄汉终还五马车，江湖暂解双龙剑。","古来丈夫或未偶，畏途轗轲无不有。","李广羞过灞上亭，贾生愁醉长沙酒。","倘遇冯唐老见君，一言更荐云中守。"]},{"t":"海山谣寿李宗伯","f":"古风","c":["一鹤东北飞，徘徊若返顾。","仙人乘之海外来，衣裳窈窕流云雾。","碧海三山列仙囿，贝宫嵯峨罗万牖。","上临紫极蹑三台，下见瑶京开北斗。","手发玉缄龙虎文，再拜远为尚书寿。","尚书岩岩霍岳姿，身长八尺扬脩眉。","夜悬赤舄星辰侧，昼入银台献纳司。","先皇旧臣尽云卧，尔时出入名声播。","二十馀年列九卿，近日新街参八座。","海内清心秪独知，当朝苦节谁人过。","海门波涛春吐吞，中有桃树盘石根。","千年柯干撑日月，万里枝叶垂昆崙。","观图愿君寿与比，长为梁梀留乾坤。"]},{"t":"河嵩篇寿张母","f":"七言律诗","c":["梁王古城河水头，北堂坐对嵩山丘。","云间二室三花树，天上昆崙九曲流。","绛霄宝婺光射地，星宿潜通河岳气。","缄书烂熳歌白云，长安远附青鸾使。"]},{"t":"古愚翁挽词","f":"古风","c":["古龙啾啾啼剑井，井底秋泉七星冷。","漪兰堂上瑟不鸣，悽调空怀金石声。","剑亦不复得，瑟亦不复闻，悠悠何处寻封君。","何处寻封君，林壑幽蒐风雨黑。","锡山崔嵬暮峰影，吴江惨澹秋波色。","江之南，山之北，松梧几树封君宅，来往徘徊叹行客。"]},{"t":"哭幼女行","f":"七言古诗","c":["二十生男不解爱，颇厌世间儿子态。","年来抱女心甚怜，却悔从前空慷慨。","女生一岁眉目扬，笑指兄姊罗成行。","镜里娇啼映窗牖，床前学步牵衣裳。","春风吹蒐蒐不住，来从何来去何去。","锦褓曾占梦月时，玉钱又哭埋香处。","乾坤得失安有凭，昨日桨极今哀生。","常怪他人不快意，乃知我辈真钟情。","皇天能生亦能死，造物弄人每如此。","云散云凝亦偶然，花开花谢缘何事。","妇人性痴还过伤，奔走叫号如病狂。","作诗示妻兼自解，转见人间父母肠。"]},{"t":"冯都督歌","f":"古风","c":["都督猛气世不多，一日百战千里过。","贼头累累十马驮，东至沧海南黄河。","宋门西平传凯歌，洛水转斗风扬波。","虏营昼雨淋滂沱，面贯双箭犹挥戈。","君不见诸将归来金满室，生封万户食千邑，都督河头死为伯。"]},{"t":"三山春宴图歌","f":"七言古诗","c":["自有三山镇京口，形势跨绝东南山。","江吞海吐互变见，参天峙地何巑岏。","凭风倒影万楼阁，动摇缥缈虚无间。","色开岛上金银阙，气接天中龙虎关。","我从唐翁画图见，大夫指点三山宴。","仙人骖鸾倏来往，烟鬟雾佩流云霰。","江桃千春一放花，海桑亘古终难变。","开图为雁长生词，却讶丹青山水奇。","白浪闪灼金芙蓉，青天静拭青琉璃。","蓬莱下用六鳌载，缑岭遥将双凤骑。","地灵生人本非偶，祷尼降岳理亦有。","大夫家住三山口，綵衣归来奉翁母，愿言寿比三山久。"]},{"t":"王都谏画鹰歌","f":"古风","c":["蒋生画鹰笔势何昂藏。","塞林海障产真骨，欻尔飞立都谏之高堂。","千年古色动崖壑，一匹素练开风霜。","都谏常称蒋生笔，此鹰神骏困无匹。","乍见遥惊俊思生，细观转觉奇姿出。","人间鸷鸟各异种，纷纷搏击相矜宠。","饱飏饥附更谁熊，掣臂翻鞲空自勇。","此鹰不遂群雁飞，亦似都谏独立霄汉当天阍。","羽毛森然振赤日，意气矫欲排翔云。","君不见郊原白日荆棘簇，射猎无人敢驰突。","树里鸱鸢尚九霄，草中狐兔仍三窟。","尔鹰尔鹰，安得一起乘高秋。","恶鸟不呜兽辟易，再使郊原麟凤游。"]},{"t":"题袁惟武鹰熊图","f":"七言古诗","c":["林良画笔真绝伦，苍鹰玄熊俱有神。","白头翁鸟更相共，毛羽遥看欲飞动。","空山古林霜色高，秋天骨势何其豪。","猛气应知万鸟避，威风顿使群狸号。","画史当年元有意，袁君意气还相似。","执节宁辞皓首心，承家况是青云器。","图龙写凤皆可羞，此幅未许千金酬。","世间玩物不足贵，要见英雄到白头。"]},{"t":"赤壁图","f":"七言古诗","c":["周郎舳舻大江半，曹氏旌旗眼中暗。","当时万马下中原，江水千年馀断岸。","黄州逐客玉堂仙，停舟到此悲秋天。","龙争虎斗慨往事，酹月酬风怀昔贤。","古人今人皆已矣，吁嗟丹青乃谁子，赤壁之山只如此。"]},{"t":"刘武选百鸟图","f":"楚辞体","c":["呜呼凤凰不可见，人间百鸟空啁啾。","西飞鹖雀亦五色，满眼谁别枭鸾俦。","刘侯此图爱者众，画手莫识元与宋。","粉绘剥落绢素新，万羽千毛尚飞动。","侯言此画先人传，珍藏未肯充南贡。","十袭翻令锦绣轻，百年转见丹青重。","顷来数相见，手携登我堂。","开图见百鸟，从此双凤凰。","鹂黄乌黑隐可辨，行凫立鹭遥相望。","延颈战翼各拱向，宛如万国臣妾朝天王。","君不见蜀道阻绝，岐山已颓。","潇湘无人，衡岳崔嵬。","竹实未结，桐花不开。","鹧鸪怨，杜鹃哀，凤兮何时来。"]},{"t":"画竹","f":"七言古诗","c":["殷君示我林垍竹，临风写雨夺天巧。","尺缣苍筤只两根，气势已觉千林少。","虬蟠凤起倏有神，出云入雾何缥缈。","闻君鲁门西草堂，万竿白日森烟霜。","怪道君身瘦如竹，只对此君不食肉。"]},{"t":"雷黄门凯旋图歌","f":"七言古诗","c":["汉家贼盗临京都，西冲河塞东海隅，虎豹奔突豺狼呼。","天子九重怒按剑，将军五道催飞符。","黄门铁鞚按营垒，监视将军奉天子，征者不忧居者喜。","晓战遥随金鼓前，昼行独拥旌旗里。","烟沙忽传畿甸清，黄门奏捷旋神京，将军归来天子迎。","册书十万纳御府，勋级三千罗紫庭。","封侯拜将珥貂列，白金绯衣照云月，黄门功多不自说。","受爵元看陆机小，却赏谁知鲁连洁。","高堂白日披图新，戎衣惨澹犹风尘，坐令慷慨悲今辰。","书生从此识汗马，丈夫常忆画麒麟。"]},{"t":"吕黄门画竹歌","f":"古风","c":["黄门持此竹，云是温徽笔。","初闻一叶扫风雨，迥出千竿贯霜日。","层沙曲涧开烟湍，高天云影楼榭寒。","黄门峻节与之比，手排阊阖呈琅玕。","琅玕摧折凤不食，咆哮虎豹天门黑。","鸱鸣鴂啼百草死，谁看青青满林色。","君收此幅今西行，雷电随入蒲州城。","龙盘嶰谷山中石，更待伶伦截凤笙。"]},{"t":"彭中丞四民图歌","f":"七言古诗","c":["渔舟暝入桃花浔，春山如闻樵采音。","高原犁锄被烟雨，书阁窈窕穿松林。","中丞雅爱山水障，清晨自挂高堂上。","绿树逶迤转众流，白云合汨开层嶂。","万里宁论战伐功，百年宛见升平象。","忆昨寇盗日横行，中原白骨哀苍生。","携男抱女路断绝，痛哭不见天边城。","渔奔樵窜学士徙，纵有陇亩无人耕。","至尊九重忧旰食，命公杀贼贼始平。","近郊无复戎马迹，比屋仍传鸡犬声。","明公壮年心许国，何况此身际日月。","二载驱驰扫汉南，一时谈笑清河北。","出阃三分大将旗，来朝独拥诸军节。","乐土重开白日光，普天不动黄尘色。","即今西戎忽复骄，朝廷亲遣霍嫖姚。","已闻土鲁还金印，不见中丞下赤霄。","形像云台犹未画，姓名麟阁早须标。","开图更赋出车什，四海甲兵从此销。"]},{"t":"桃源图歌","f":"古风","c":["昔我游武陵，坐石窥花源。","岸坼丹洞閟，风回绿萝翻。","崩崖奔古月，沓嶂响哀猿。","行车一以过，始知人境諠。","真阳仙令欲南往，手持新画来相访。","武陵山水久不睹，今晨置我高堂上。","岩穴如闻鸡犬声，村墟但见桑麻长。","髣髴潭水滨，点缀桃花春。","山川似晋代，衣服犹秦人。","回首茫然一烟雾，寻源谁复知真处。","投簪福地终有期，画中先认桃花树。"]},{"t":"吴伟江山图歌","f":"古风","c":["吴伟老死不可见，人间画史空嗟羡。","吾观此卷江山图，飘然意象临虚无。","想彼濡毫拂绢素，酒酣落笔神骨露。","万里青天动海岳，空堂白日流云雾。","洲倾岸侧波岭衔，岛屿倒影翻源潭。","江边万舸一时发，中流飒飒开风帆。","崩涛涌浪势难久，渔子舟人各回首。","去雁遥知七泽中，落花误认桃源口。","烟峰苍茫貌二叟，面发衣冠颇粗丑。","石林沙草恣点染，舒卷沧洲在吾手。","忆昨弘治间，伟艺实绝伦。","供奉曾逢万乘主。","召邀数过诸侯门。","京师豪贵竞迎致，失意往往遭呵嗔。","由来能事负性气，轗轲贫贱终其身。","呜呼吴生岂复作，身后丹青转零落。","残山剩水片纸贵。","百金购之不一得。","此卷流传天地间，我即见汝真颜色。"]},{"t":"张季升望云图歌","f":"七言律诗","c":["黄门身在青云上，眼中白云日南望。","白云飞入楚山里，封君之堂应在此。","俞卿善画更能赋，画间青琐开缣素。","晴窗落笔白云生，写出黄门万里情。"]},{"t":"胡人猎图歌","f":"七言古诗","c":["边沙萧萧天北风，高林昼屯鞍马雄。","胡人装束身手健，真与此图形貌同。","冬寒猎傍长城窟，城下平原日将没。","呼鹰放犬无不为，数骑弯弓竞驰突。","月高琵琶海西城，拂庐雪乾氍毹轻。","金钟虏酒亦易醉，玉踠胡骝骄不行。","白发老胡黄战裙，抽箭仰视天山云。","众中若认射雕手，汉家谁是李将军。"]},{"t":"画马行","f":"古风","c":["画马如画龙，纵横变化当无穷。","吾观月山子，落笔窥神工。","曾向天闲貌十马，十马意态无一同。","此马传来几百年，古绢犹开沙漠风。","树里河流新过雨，簇簇草芽寒刺水。","圉人双牵临水边，草色离离乱云绮。","令人疑到渥洼傍，波底风雷斗龙子。","细看不是白鼻騧，恐是当朝狮子花。","紫燕纤离各惆怅，其馀驽劣何足誇。","忆昔爱马不惜千金货，君王勤政楼头坐。","胡奴黄衫双绣靴，厩中骑出楼前过。","红帕初笼汗血香，玉鞭轻拂桃花破。","吁嗟玩物竟何益，遗迹徒使丹青播。","只今烽炮西北来，沙场未闻千里才。","千里才，固有时，回头为问御者谁。","君看赤骥与骐驎，挽车太行岭。","心期田子方，踟蹰驾辕顷。","霜凋苜蓿汉郊冷，骨折秋风自嘶影。","君不见古人养马如养士，一饱能酬千里志。","今人养马如养豚，厩下常堆蒺藜刺。","古之良马何代无，可笑今人空按图。"]},{"t":"画鹤篇","f":"古风","c":["昔闻少保写青田，古墨千年人不传。","郎君此幅何时得，萧飒秋堂扫烟色。","雪翎风翼如有神，万里出海谁能驯。","我初见此鸟，重是仙人禽。","朝饮玉河湄，暮宿玄圃林。","回首寒江凫与雁，日晚哀鸣羡霄汉。"]},{"t":"赤壁图歌","f":"七言古诗","c":["老暪横槊江之皋，眼中吴越一秋毫。","吴人彀弩来江左，江头鸣笳昼举火。","旌旗飘扬北风前，舳舻化作江中烟。","英雄一去音尘灭，断水残山吊词客。","白雪堂寒草烟暮，黄泥坂下临皋路。","酒酣唤客吹玉箫，江风山月不待招。","昔时霸业那足数，鹤梦悠悠眇千古。","回首东坡百世人，图画苍茫空有神。"]},{"t":"画山水","f":"七言古诗","c":["蜀溪茧纸明如练，并州剪刀碧云断。","泥金作绘谁所为，华堂粉壁光凌乱。","枳花竹叶春江曲，江头无人水空绿。","逶迤石径林中出，草碧沙明净江日。","欲觅秦人武陵下，不见溪边种桃者。","高楼窈窕锁烟雾，只疑行尽潇湘路。","潇湘却忆旧时游，纸上烟波生暮愁。"]},{"t":"画菊歌","f":"古风","c":["杨郎画菊只三本，千花万草无颜色。","夏卿墨竹差可比，陶生桂树何须得。","徐君向我誇所有，阁中携此更携酒。","翠幔披云出院迟，金杯映日凭阑久。","深黄秾紫杂烟皋，想见五色临挥毫。","丛篁琐碎白昼静，锦石烂熳霜天高。","楚江茅堂若在眼，凤闼彤闱对秋晚。","白葛飘零处士稀，朱弦寂寞佳人远。","寒香晚节真可怜，惜哉杨郎不在前。","开窗为我拂绢素，落笔点缀黄金钱。","徐君徐君珍重此，君不见天寒岁暮百草死，绮罗无地看桃李。"]},{"t":"题文与可画竹上有东坡山谷题识","f":"古风","c":["客从南方来见予，手持锦轴长丈馀，云是与可之画苏黄书。","中堂展玩思超忽，四百年来真故物。","败素飘零色已改，古墨惨澹神犹发。","文生此竹世希有，一枝不异双琼玖。","冥冥烟干动石壁，瑟瑟风叶临窗牖。","笔下何须扫万竿，胸中已自横千亩。","眉山长公元擅场，豫章太史谁可当。","片言相推四海重，只字尚使千年藏。","客从何处得此幅，令我嗟叹久怜惜。","苏黄不作与可死，人间书画无真迹，劝君宝此勿轻掷。"]},{"t":"题黄车驾画竹","f":"古风","c":["画竹忌屈不忌直，息斋由来有笔力。","今之画图几百年，人间尚自留真墨。","空堂昼挂风雨寒，明灭纤雾生微澜。","细观见竹不见画，何时石上削此三琅玕。","八闽高士黄司马，平生好文兼爱画。","碧草停珂夏省中，白云捲幔晴窗下。","每逢宾客出评品，遂使破素增高价。","开图似惜孤鸾丛，胡为写置荆棘中。","君不见洞庭之上潇湘岸，翠筱脩篁沙草乱，凤凰不栖鹧鸪怨。"]},{"t":"吴伟飞泉画图歌","f":"七言古诗","c":["长安独过田子舍，留我一玩飞泉画。","绝壁如闻风雨来，晴天安得蛟龙挂。","吴生跌宕得画理，潦草落笔皆可喜。","飞泉却出汨嶂间，山即真山水真水。","客堂六月生昼寒，耳中髣髴高江滩。","源潭窈窕不可测，波浪汹涌多奇观。","泉边二老颜色异，偶坐似是庄与惠。","万里谁论到海心，百年讵识临渊意。","伟哉田子今儒宗，文标南指匡庐峰。","不须对此更惆怅，会观瀑布青天上。","杉风松日隔缥缈，云泷雪赣何雄壮，我常梦往神空向。","岂无吴生好手笔，为我写寄庐山障。"]},{"t":"画鱼","f":"七言古诗","c":["大鱼昂藏若人立，冲波跋浪风江急。","傍观二鲤各有神，倏忽波涛随出入。","中堂鬐鬣动杳冥，坐久始识为丹青。","青天万里拂绢素，笔力咫尺开沧溟。","禹门天池云雾里，白昼雷霆行地底，何人有力移置此。","酒酣相视一改容，只愁化作三蛟龙。"]},{"t":"题大司马王晋溪先生十牛图","f":"古风","c":["君不见将军台阁龙图张，何人画牛司马堂。","十牛战角垂其耳，挂之中堂见者喜。","风林烟草恣牧放，水涉沙眠无触觗。","黄犍黑牯觔肉真，司马堂中安用此。","岂知此物公所珍，展画似对桃林春。","高亭青松拂赤日，南山白日消黄尘。","攻驹不羡三千牝，考牧还歌九十犉。","尚书况登本兵部，天营十二屯貔虎。","南征北伐运筹策，破虏擒戎在樽俎。","已看神武藉经纶，要使苍生有环堵。","苍生十年望苏息，海内荒城久荆棘。","犁锄未慰三农心，输挽空嗟万夫力。","我知明公分主忧，坐清寇盗安王侯。","沙场之地皆田畴，尽却战马归耕牛。","君不见中堂此图日张挂，丹青照耀麒麟画。"]},{"t":"观吴进士舞剑歌","f":"古风","c":["我来江夏吴郎宅，夜观吴郎舞剑起。","古匣尘埃铁生绣，玉珥金环为予理。","灯前照耀只宝刀，蛟龙盘拿雷怒号。","仰瞻南斗有紫气，却顾东海无波涛。","吴郎别我适南国，万里开樽动颜色。","我亦将之五岳游，须尔仗剑芟虺域。","不然持此击名王，况今关塞风尘黄。","酒酣自觉神益扬，左挥右霍秋月光。","吴郎蛇矛更精突，墙头角弓力十斛。","平生豪侠真可怜，耳熟白眼看青天。","嗟哉此宅不足展君舞，室卑地窄难回旋。"]},{"t":"柳絮歌","f":"古风","c":["长安三月百花残，满城飞絮何漫漫。","千门万户东风起，陌上河边春色阑。","美人高楼锁深院，白花濛濛落如霰。","晴窗窈窕朝日迟，乱入帘栊趁双燕。","游丝相牵时袅袅，委地飘廊不须扫。","君不见江头绿叶吹香绵，随波化作浮萍草。"]},{"t":"明月篇","f":"古风","c":["长安月，离离出海峤。","遥见层城隐半轮，渐看阿阁衔初照。","潋滟黄金波，团圆白玉盘。","青天流景披红蕊，白露含辉汎紫兰。","紫兰红蕊西风起，九衢夹道秋如水。","锦幌高褰香雾开，琐闱斜映轻霞举。","雾沉霞落天宇开，万户千门月明里。","月明皎皎陌东西，柏寝岧峣望不迷。","侯家台榭光先满，戚里笙歌影乍低。","濯濯芙蓉生玉沼，娟娟杨柳覆金堤。","凤凰楼上吹箫女，蟋蟀堂中织锦妻。","别有深宫闭深院，年年岁岁愁相见。","金屋萤流长信阶，绮栊燕入昭阳殿。","赵女通宵侍御床，班姬此夕悲团扇。","秋来明月照金微，榆黄沙白路逶迤。","征夫塞上怜行影，少妇窗前想画眉。","上林鸿雁书中恨，北地关山笛里悲。","书中笛里空相忆，几见盈亏泪沾臆。","红闺貌减落春华，玉门肠断逢秋色。","春华秋色递如流，东家怨女上妆楼。","流苏帐捲初安镜，翡翠帘开自上钩。","河边织女期七夕，天上嫦娥奈九秋。","七夕风涛还可渡，九秋霜露迥生愁。","九秋七夕须臾易，盛年一去真堪惜。","可怜扬彩入罗帏，可怜流素凝瑶席。","未作当垆卖酒人，难邀隔座援琴客。","客心对此叹蹉跎，乌鹊南飞可奈何。","江头商妇移船待，湖上佳人挟瑟歌。","此时凭阑垂玉箸，此时灭烛敛青蛾。","玉箸青蛾苦缄怨，缄怨含情不能吐。","丽色春妍桃李蹊，迟辉晚媚菖蒲浦。","与君相思在二八，与君相期在三五。","空持夜被贴鸳鸯，空持暖玉擎鹦鹉。","青衫泣掩琵琶弦，银屏忍对箜篌语。","箜篌再弹月已微，穿廊入闼霭斜辉。","归心日远大刀折，极目天涯破镜飞。"]},{"t":"邯郸行","f":"古风","c":["邯郸道上车马多，行人夜火渡漳河。","邯郸女儿年十五，能弹琵琶善歌舞。","青灯朱户夜当垆，垆头酒熟唤客沽。","玉壶青丝为君系，不妨醉向邯郸途。","君不见邯郸市，昔日繁华安可拟。","鸣鸾佩玉青云间，斗鸡走马红尘里。","平原门前客如云，千载凄凉竟何是。","黄金白璧成飞灰，歌楼舞榭空流水。","伤心万事俱可嗟，草长丛台白日斜。","废苑当时在何处，旧宫今目作谁家。","古来富贵俱寂寞，有酒樽前胡不乐。"]},{"t":"苦热行简问陶良伯","f":"古风","c":["六月二十火云发，京师毒热胜吴下。","清晨衣冠不敢出，对食欲餐汗满把。","闭门袒跣真发狂，隐几寤寐何由假。","风云昨日忽入城，疾雷破墙雨破瓦。","此地楼台更郁蒸，西山殿阁室潇洒。","姑苏才人玉堂客，邻近不得同杯斝。","因君欲访姑苏台，台下清江千尺泻。","上有万竿脩竹林，干云蔽日森炎夏。","君不见九衢亭午日如赭，鸟飞投林兽奔野，红尘骑马何为者。"]},{"t":"修竹篇","f":"古风","c":["君不见真翁堂下竹贯日，干云千尺高亭亭。","万木避霜色飒飒，空岩回翠涛平生。","直节本无偶，手栽琅玕种琼玖。","风月何曾忘此君，松梅况自称三友。","东曹郎君翁所奇，节概更与翁名齐。","神龙昔向沧波化，彩凤今从玉树栖。","高堂兹辰开寿箓，却洗金盘对春竹。","霓旌昼下仙人车，云管宵停嬴女曲。","翁家旧住上林西，托根白近蓬莱池。","雪崖冰柱映楼阁，雨露常沾万岁枝。"]},{"t":"七夕词","f":"七言古诗","c":["双星渡河月西没，悲参怨商愁夜独。","霄阑箕斗自低昂，心怜情恨看七襄。","人生失意无贱贵，寒机织妇鸳鸯思，金屏玉瑟宫娥泪。"]},{"t":"同崔吕孙三内翰集徐子瞻辰楼","f":"七言律诗","c":["秋日徐君北楼上，北楼岧峣连北斗。","窗牖临观日下花，阑干坐拂天中柳。","南州孺子美如玉，北门词客同杯酒。","咫尺金门接玉堂，碧霄共立空翘首。"]},{"t":"晚雨君卿招不赴","f":"七言律诗","c":["骑马出门还复入，六月阴晴不可卜。","檐前星出乍有无，城上雨来时断续。","炎天留客夜苦短，燕地近秋暑偏酷。","何人同对寸中花，忆尔独伴啼乌宿。"]},{"t":"观石鼓歌","f":"七言古诗","c":["我来太学谒孔庙，下观戟门石鼓陈。","之罘诅楚几埋没，此石照耀垂千春。","苔昏藓涩读难下，虫彫鸟剥细不分。","古画诘曲蛟龙隐，石气惨淡烟雾氛。","周王功勋史籀笔，数石散落岐阳滨。","中兴气象岂复睹，大篆意格谁曾闻。","先秦文字稍近古，两汉摹拓多失真。","六朝以来尚靡丽，钟王往往称通神。","唐韩宋轼递歌叹，长篇险韵何悲辛。","大观之间入汴国，君王好艺崇斯文。","高驼巨舰远载玫，金填玉嵌传相珍。","靖康乘舆忽播荡，保和玩物随烟尘。","神驱鬼守散复聚，至宝岂得空沉沦。","文皇北来定燕鼎，不置太庙留成均。","博士无烦上书请，诸生颇得亲讲询。","虚廊画壁安置稳，大厦长檐覆盖新。","不随钟鼎怨磨灭，已与琬琰争嶙峋。","平生博览爱古迹，世上墨本徒纷纭。","此虽残缺岁已久，尚觉只字轻千缗。","璧池日月动华衮，奎阁星斗罗贞珉。","呜呼孔庙在万世，此石与庙长无湮。"]},{"t":"同李进士观铜雀砚歌","f":"古风","c":["君不见邺中魏帝无宫殿，千秋遗瓦磨为砚。","墨客骚人空叹嗟，朱薨绮构谁曾见。","李君好古精鉴别，冬天拂拭开烟雪。","虚堂叩之哀玉昔，泥沙洗出黄金屑。","广州紫石鸲鹆眼，歙山龙尾何希罕。","濡藻光回星汉垂，蟠花背刻龟螭断。","共忆高台罗绮春，翠眉艳骨飞黄尘。","提携故物悲年代，感慨新章泣鬼神。","君不见临漳此物难复睹，河沉岸坼求者苦。","县人相传为赝古，呜呼日掘西陵土。"]},{"t":"太白山歌","f":"七言古诗","c":["我闻太白横西域，百里苍苍见寒色。","灵源万古谁穷探，雷雨窈冥岩洞黑。","中峰迢迢直上天，瑶宫玉殿开云烟。","千盘万折不到顶，石壁铁锁空高悬。","阴崖皑皑积古雪，绝壑长松几摧折。","鸟道斜穿剑阁云，龙潭倒映峨嵋月。","高僧出世人不知，飞仙凌空笙鹤随。","洞天福地在只尺，怅望尘海令心悲。"]},{"t":"子昂画马歌","f":"古风","c":["学士宋王孙，画马皆龙姿。","曾写飞黄出天厩，尚留云影落瑶池。","池头马官锦靴裤，缓鞚长牵时拂顾。","万里精神开绢素，百年毛鬣生风雾。","吁嗟内乘无人识，想见奔腾过都国。","翠仗朱轩数往来，金羁玉勒增颜色。","只今天子罢南征，又闻东巡辽海城。","安得四马忽然生，登台一顾千金轻，天上常随八骏行。"]},{"t":"避雨山合舍望见蒲圻县","f":"五言律诗","c":["向晚蒲圻道，遥闻鸡犬喧。","斜光入深巷，疏雨过闲门。","县市浑依水，人烟只类村。","萧条灯火夕，沽酒共谁论。"]},{"t":"景港渡","f":"五言律诗","c":["秋临景港渡，澄波生绿苔。","舟移远岸动，帆挂好风来。","斜日画旂捲，中流清吹哀。","榜人歌未罢，前导已相催。"]},{"t":"辰溪县","f":"五言律诗","c":["早发辰溪渡，清川喜泛舟。","山城欹粉堞，江驿映朱楼。","雨骤沙颓岸，天寒冰露洲。","蛮音闻渐异，迢递动乡愁。"]},{"t":"沅水驿四首 其一","f":"五言律诗","c":["小驿孤城外，阴森草树幽。","晚凉凭水榭，秋雨坐江楼。","绝域鸿难到，空山客独愁。","夜深归渡少，渔火照汀舟。"]},{"t":"沅水驿四首 其二","f":"五言律诗","c":["去国日以远，登楼思故乡。","雨来江气白，日出市烟黄。","岛屿秋逾静，轩窗晚更凉。","凭高凝伫久，槐影下微阳。"]},{"t":"沅水驿四首 其三","f":"五言律诗","c":["长剑向灯看，休歌行路难。","岩窗悬石溜，江槛杀风湍。","城古蒹葭夕，堂空蟋蟀寒。","几回青琐闼，朝罢想鸣鸾。"]},{"t":"沅水驿四首 其四","f":"五言律诗","c":["江上西风起，萧条暮雨频。","山楼连堞垒，郡路入荆榛。","怀古过沅水，悲秋吊楚臣。","芷香堪采掇，思寄日边人。"]},{"t":"沅州道中四首 其一","f":"五言律诗","c":["山行多雅兴，十里几人家。","林叶垂朱实，蹊藤落紫花。","缘崖防转石，傍岸畏颓沙。","不见前溪堡，遥闻奏暮笳。"]},{"t":"沅州道中四首 其二","f":"五言律诗","c":["岁月惊长道，风尘惜旧绨。","钩云盘曲磴，沿月溯回溪。","南国疲征敛，西戎厌鼓鼙。","山深正愁绝，落日鹧鸪啼。"]},{"t":"沅州道中四首 其三","f":"五言律诗","c":["共说关门险，岧峣不可攀。","山峰藏曲折，涧道泻潺湲。","绝壁人愁下，长林鸟倦还。","官程元有限，行旅敢辞艰。"]},{"t":"沅州道中四首 其四","f":"五言律诗","c":["向夕人烟近，肩舆历翠微。","驿花明去节，山雾上征衣。","果熟收梨枣，蔬香煮蕨薇。","开樽对佳客，且喜吏人稀。"]},{"t":"清浪","f":"五言律诗","c":["驻旌清浪卫，半日费攀跻。","窗迥开千嶂，城高控九溪。","征徭无楚户，耕种有蛮妻。","愁问滇南道，迢迢隔岭西。"]},{"t":"李参谋府二首 其一","f":"五言律诗","c":["参谋开夕宴，邀我坐深更。","暇日游观少，清时号令平。","旌旗巡哨堡，鼓角启严城。","莫笑书生腐，樽前解论兵。"]},{"t":"李参谋府二首 其二","f":"五言律诗","c":["高衙赫弘厂，镇坐抚南蛮。","画戟环千士，雕甍插万山。","秋高鼍鼓振，风静虎旗闲。","闻道西戎乱，将军莫破颜。"]},{"t":"镇远三首 其一","f":"五言律诗","c":["古郡青山下，经过驻使车。","土官迎诏拜，蛮客望城遮。","叠嶂营孤垒，清江绕百家。","晚来官署里，独坐咏皇华。"]},{"t":"镇远三首 其三","f":"五言律诗","c":["寥落古城池，斜光照戍旗。","关临苗子砦，洞入长官司。","殊俗终难近，蛮音久易知。","踟蹰暮江上，又是仲秋时。"]},{"t":"查城十五夜对月五首 其一","f":"五言律诗","c":["中秋看月色，移席近前楹。","河汉三更没，关山万里明。","风烟依独戍，砧杵闭空城。","此夜高堂上，多应念远征。"]},{"t":"查城十五夜对月五首 其二","f":"五言律诗","c":["天上何所有，团团白玉盘。","可怜秋半月，只是客中看。","影直朱楼午，轮高青嶂寒。","美人何处共，光彩隔云端。"]},{"t":"查城十五夜对月五首 其三","f":"五言律诗","c":["驿舍山东下，闲吟月出歌。","婆娑笼夕桂，窈窕入云萝。","玉魄中天满，清辉近水多。","广寒高几许，台殿锁嫦娥。"]},{"t":"查城十五夜对月五首 其四","f":"五言律诗","c":["小市无兼味，邻家酒亦悭。","佳期三五夕，远客万重山。","霄汉分秋色，风尘照旅颜。","去年当此夜，坐对紫薇间。"]},{"t":"查城十五夜对月五首 其五","f":"五言律诗","c":["我爱秋宵永，西林待月斜。","百年几圆缺，今夜倍光华。","兄姊俱殊土，田庐有旧家。","金波如客泪，独洒向天涯。"]},{"t":"安南","f":"五言律诗","c":["崎岖踰岭路，到郭已昏钟。","城险苗难近，关高贾不通。","郊烟秋牧马，崖日暖收蜂。","民俗殊中域，生涯亦颇同。"]},{"t":"送孙教谕","f":"五言律诗","c":["三年别燕市，万里喜相寻。","禄少供亲膳，官清任士林。","板舆迎白发，芹舍拥青衿。","莫谓蟠龙久，风云起碧岑。"]},{"t":"永宁舟中","f":"五言律诗","c":["霜降水还漕，舟行不觉劳。","顺风欹浪疾，乱石下滩高。","渔舫依红蓼，人家住白茅。","乡园待归客，应已熟香醪。"]},{"t":"江门","f":"五言律诗","c":["小店江门市，孤舟闻暮砧。","远沙含细雨，缺岸隐疏林。","旅宿青枫晚，人烟翠狱深。","渐临巴蜀道，一慰望乡心。"]},{"t":"滟滪","f":"五言律诗","c":["霜落夔门树，寒江滟滪孤。","狂澜须此障，砥柱赖谁扶。","入峡愁孤客，当关用一夫。","何劳念西域，千载固舆图。"]},{"t":"峡中","f":"五言律诗","c":["自昔偏安地，于令息战侵。","江穿巫峡隘，山凿鬼门深。","浊浪鱼龙黑，寒天日月阴。","夜猿啼不尽，凄断故乡心。"]},{"t":"旅行","f":"五言律诗","c":["日暮行湘水，春深别上都。","系舟南斗近，倚剑北云孤。","骨肉千行泪，风尘万里躯。","王孙江上草，何处采蘼芜。"]},{"t":"滹沱河上","f":"五言律诗","c":["长堤枕春郭，断岸入残晖。","栖鸟张灯起，惊凫解缆飞。","古人堪堕泪，吾道岂常非。","未识临河意，中流击枻归。"]},{"t":"渡淮","f":"五言律诗","c":["津口风翻旆，春阴郁未开。","淮流冲古岸，沙店倚长台。","鸟向平芜下，人随返照回。","未忘舟楫兴，临路独迟徊。"]},{"t":"赠刘大参","f":"五言律诗","c":["自识文翁化，佳声满大藩。","野人看露冕，稚子望行轩。","草色青春细，棠阴白昼繁。","东风应有意，先到宛陵原。"]},{"t":"寄阴舍人","f":"五言律诗","c":["卧病春城暮，相思汝水浔。","紫薇鸾掖远，碧草凤池深。","鸣佩他年梦，看花此日心。","故知俱散尽，北望一沾巾。"]},{"t":"雨霁","f":"五言律诗","c":["断雨悬深壁，馀雷振远空。","苍林横落日，碧涧下残虹。","万井波光静，千家树色同。","何因共朋好，归咏舞雩风。"]},{"t":"雨","f":"五言律诗","c":["独坐浮云起，徘徊夕照孤。","长风生远树，细雨入平芜。","暗牖飞虫落，高林宿鸟呼。","昭回曾有倡，此日慰田夫。"]},{"t":"鸣蝉","f":"五言律诗","c":["仲夏鸣蝉集，窗临碧树阴。","清心吾爱尔，长日自悲吟。","露叶朝栖静，风林夕响沉。","偶通观物理，幽意坐来深。"]},{"t":"送孙太守","f":"五言律诗","c":["五马朝天日，倾城出饯时。","倪宽行考最，何武去留思。","碧草朱轮动，青云皂盖移。","圣朝崇汉吏，功业正当期。"]},{"t":"五月望月食","f":"五言律诗","c":["月食逢中夏，山城黯黯阴。","孤灯今夕泪，哀角万方心。","雾嶂看初灭，风帘望转沉。","清光无远复，斋坐及更深。"]},{"t":"葵","f":"五言律诗","c":["春后群花尽，孤葵且自芳。","弱茎依井上，劲干拂檐长。","卫足全生理，倾心倚太阳。","幸因佳客至，采掇荐中堂。"]},{"t":"立秋寄献吉","f":"五言律诗","c":["山城一叶下，水榭已迎秋。","夜迥商风至，天空大火流。","稍苏司马病，翻遣宋生愁。","日暮关河外，思君重倚楼。"]},{"t":"寄樊国宾","f":"五言律诗","c":["不见樊卿久，空怜岁月长。","爱书王逸少，癖画米元章。","业绍青缃旧，名沾玉牒香。","十年相会地，烧烛对秋堂。"]},{"t":"沱西别业","f":"五言律诗","c":["使君方拥郡，别业枕沱湄。","城倚章华殿，山藏大禹祠。","赌棋怜谢传，看画忆王维。","未是悬车日，烟云入梦思。"]},{"t":"东昌公哀词 其一","f":"五言律诗","c":["壮志空寥廓，中年与世辞。","露寒青草梦，风惨紫荆悲。","入政光前辈，传经实我师。","大苏碑不忝，惭继子由词。"]},{"t":"东昌公哀词 其二","f":"五言律诗","c":["岳城淹六纪，东郡未经年。","别驾王祥胜，弹琴子贱贤。","一官犹黑发，万事已黄泉。","铭石看遗绩，凄凉太史篇。"]},{"t":"东昌公哀词 其三","f":"五言律诗","c":["江海悠悠逝，那堪死别情。","向平婚未毕，皂宰宦初成。","夜雨原花落，秋风墓草生。","九京何日返，空复望佳城。"]},{"t":"东昌公哀词 其四","f":"五言律诗","c":["复魄黄河远，归程汝路偏。","素车临故域，华表立新阡。","室女啼秋夕，乡人吊墓田。","萧条风雨候，愁绝对床年。"]},{"t":"东昌公哀词 其五","f":"五言律诗","c":["一自封泉室，偏惊节序除。","白杨悲北郭，青草蔓飞墟。","天地存亡里，江湖涕泪馀。","寂寥身后事，不忍读遗书。"]},{"t":"中元夜月","f":"五言律诗","c":["片月东城上，长风度早秋。","光临青嶂发，影抱碧潭流。","灏气沉沙浦，馀辉恋水楼。","何人更吹笛，关塞不胜愁。"]},{"t":"西郭","f":"五言律诗","c":["西郭栖迟地，寒山夕景繁。","鸡豚归故道，鸟雀下秋园。","开户林风入，沿坡草露翻。","香粳夜来熟，岁暮足盘飧。"]},{"t":"穫稻","f":"五言律诗","c":["穫稻妻孥喜，中宵尚筑场。","但堪供俯仰，那复问仓厢。","合亩黄云盛，翻匙白雪香。","更须催酿酒，溪上鲤鱼长。"]},{"t":"梦何粹夫","f":"五言律诗","c":["内翰同乡客，新知交更深。","春从都下别，秋向梦中寻。","图史留东观，词章侍上林。","中宵忆颜色，慰我索居心。"]},{"t":"晚归自溪上","f":"五言律诗","c":["秋到城西树，缘溪落叶多。","数家连水竹，一径入烟萝。","废井寒螀聚，閒窗暮雀过。","濯缨闻孺子，灯下亦悲歌。"]},{"t":"客至","f":"五言律诗","c":["蓬门断来往，草径自荒芜。","有客何方至，呼儿问浊酤。","弹琴待风月，把酒话江湖。","更枉新诗赠，长吟兴不孤。"]},{"t":"登楼二首 其一","f":"五言律诗","c":["眇眇凭高暮，凄凄景物閒。","秋阴生巨壑，云气度西山。","一郡寒烟畔，千门落照间。","此时瞻北极，万里欲飞攀。"]},{"t":"登楼二首 其二","f":"五言律诗","c":["缥缈东楼上，长凭兴不悭。","病来疏眺望，秋至废跻攀。","日落河山暮，风回草树斑。","夜残犹未倦，坐待月临关。"]},{"t":"同沈清溪夜坐二首 其一","f":"五言律诗","c":["细雨侵高树，空堂散郁蒸。","诗成挥彩笔，话久话青灯。","凤字惭稽叔，龙门愧李膺。","瑶琴多古操，数为拂朱绳。"]},{"t":"同沈清溪夜坐二首 其二","f":"五言律诗","c":["移席留长坐，更深雨渐繁。","竹寒庭鹤警，灯静壁蛩喧。","舟楫淹归计，琴书代晤言。","知君多雅兴，常过蒋生园。"]},{"t":"雨夜似清溪二首 其二","f":"五言律诗","c":["微雨初摇飏，风吹洒更长。","冥冥来石壁，飒飒近秋堂。","萤火流深堑，鸬鹚下浅塘。","吴歈当此夕，哀切兴难忘。"]},{"t":"雨后邀马君卿","f":"五言律诗","c":["寂寂扬雄宅，琴书谁与同。","青山过片雨，白日抱残虹。","尘榻还堪卧，清樽未可空。","相看城郭暮，那忍负秋风。"]},{"t":"雨中和清溪","f":"五言律诗","c":["濛雨萧条至，悲风日暮多。","积阴生径草，永夜落庭柯。","宅愧高人隐，门劳长者过。","白鸥如有意，相逐下烟波。"]},{"t":"清溪草堂 其一","f":"五言律诗","c":["草阁临溪上，幽期孰与论。","白沙连曲岸，秋水到閒门。","槛外常垂钓，舟中数举樽。","风情有如此，不异浣花村。"]},{"t":"清溪草堂 其二","f":"五言律诗","c":["夜夜闻清濑，朝朝见碧浔。","百年应有寄，终日自长吟。","宿桨依沙树，开窗散渚禽。","生涯众人事，不独爱幽深。"]},{"t":"清溪草堂 其三","f":"五言律诗","c":["隐者常稀阔，幽居独羡君。","汀洲起渔唱，篱落傍鸥群。","水接吴门树，窗生禹洞云。","更传诗句好，还似沈休文。"]},{"t":"清溪草堂 其四","f":"五言律诗","c":["太湖湖上地，闻占好园池。","有业堪投老，无官可避时。","渡传桃叶咏，门听竹枝词。","何日山阴棹，溪堂见戴逵。"]},{"t":"怀高铁溪先生四首 其一","f":"五言律诗","c":["积雨空林畔，庭除烟雾昏。","佳人不我至，樽酒向谁论。","野树斜连屋，秋山遥对门。","何时孤兴发，骑马到荒村。"]},{"t":"怀高铁溪先生四首 其二","f":"五言律诗","c":["吾慕高夔府，风流汉长卿。","新诗裁锦字，丽赋掷金声。","早谢人间事，幽通物外情。","相违动旬月，何日见黄生。"]},{"t":"怀高铁溪先生四首 其三","f":"五言律诗","c":["磊落真邦彦，襟期亦我师。","右丞元好画，谢传未忘棋。","花鸟留新兴，云山待妙词。","小堂能枉驾，一为细论诗。"]},{"t":"怀高铁溪先生四首 其四","f":"五言律诗","c":["僻居临水次，竹树稍深幽。","对景非无酒，登高亦有楼。","好风吹永夜，片月度清秋。","不见孤舟至，令人忆子猷。"]},{"t":"八月丁日","f":"五言律诗","c":["孔庭严祀典，冠冕萃吾乡。","霄汉回清乐，星辰入画裳。","万年仍俎豆，千仞自宫墙。","此日斯文地，瞻依病未忘。"]},{"t":"初度","f":"五言律诗","c":["此日逢初度，悲怀却自宽。","久为京洛客，初乞茂陵官。","堂上慈颜喜，灯前稚子欢。","一杯承膝下，愿得岁相看。"]},{"t":"阴","f":"五言律诗","c":["惨澹长阴合，苍茫四望同。","地秋还易雨，树晚故多风。","楼阁山寒里，衣裳水气中。","农家务收穫，早为豁层空。"]},{"t":"吾州","f":"五言律诗","c":["辽邈吾州地，名从申伯来。","通淮一水下，入楚万峰开。","旧国无遗庙，寒城有废台。","秋郊独临眺，怀古意悲哀。"]},{"t":"北望","f":"五言律诗","c":["北望风尘里，遥思日月边。","山河临地极，楼观倚星躔。","翠羽开诸国，金瓯至万年。","自从归病后，常梦五云前。"]},{"t":"赠张合之秀才二首 其一","f":"五言律诗","c":["张子元奇士，携书过我林。","激昂高论气，落魄远游心。","一饭山家晚，孤灯夜雨深。","城边有岐路，送尔独长吟。"]},{"t":"赠张合之秀才二首 其二","f":"五言律诗","c":["匹马何时出，还家此日心。","卞生怀楚璧，郭隗待燕金。","雄剑青云志，哀弦白雪吟。","功名少年在，不必泪沾襟。"]},{"t":"雷","f":"五言律诗","c":["不见苍山破，虚闻巨壑驰。","烈声回地底，馀响落天涯。","魍魉何由避，蛟龙得自随。","中宵沛云雨，威泽正当时。"]},{"t":"月二首 其一","f":"五言律诗","c":["宛宛秋山月，今宵尚未圆。","光生万里外，影对一樽前。","城静虚弓倚，楼高破镜悬。","草堂风露下，终夜不成眠。"]},{"t":"月二首 其二","f":"五言律诗","c":["片月中秋近，辉光一岁无。","天清惊塞雁，夜冷落枫乌。","不寐知宵永，无言对影孤。","更深何处没，万里堕江湖。"]},{"t":"三关","f":"五言律诗","c":["楚塞三关隘，云峰入望重。","何年戎马地，空有昔人踪。","积水沉秋堞，长烟带古烽。","乾坤当失据，饕餮任群凶。"]},{"t":"九月","f":"五言律诗","c":["九月清霜下，中林蕙草寒。","暮霞多变态，秋色不宜看。","丘壑容吾拙，乾坤敢自安。","古来俱涕泪，况复岁华残。"]},{"t":"樊秀才园内菊","f":"五言律诗","c":["樊生园内菊，相对小塘西。","露蕊凄凄放，风枝袅袅低。","栽依石竹下，发与畹兰齐。","明日重阳酒，殷勤为尔携。"]},{"t":"九日同马君卿任宏器登高四首 其二","f":"五言律诗","c":["远地宜登望，秋光薄暮浓。","楼高窥万井，潭迥落千峰。","花为重阳发，人怀百岁逢。","同游俱俊彦，尊酒得从容。"]},{"t":"九日同马君卿任宏器登高四首 其三","f":"五言律诗","c":["病思逢佳节，孤怀忆远游。","河山还似昔，烟树不胜秋。","故国浮云去，高台日暮愁。","牛山元有恨，休讶泪长流。"]},{"t":"九日同马君卿任宏器登高四首 其四","f":"五言律诗","c":["向夕枫林爽，行吟未拟回。","明霞积水外，落日古城隈。","鼓角秋深怨，风霜岁晚催。","莫将迟暮意，孤负菊花杯。"]},{"t":"登钓台","f":"五言律诗","c":["野阔穷秋出，云寒望未开。","万峰遥驻马，残日更登台。","水落龙蛇蛰，沙空雁鹜来。","孤怀对摇落，吟罢有馀哀。"]},{"t":"孟冬","f":"五言律诗","c":["孟冬严气至，坐见物华微。","古树犹秋色，寒山半夕晖。","江湖深欲冻，鸿雁各知归。","羸病便深卧，从兹日掩扉。"]},{"t":"寄孙世其举人","f":"五言律诗","c":["得意西风里，宾筵听鹿鸣。","此生看事业，今日重科名。","锦树连江路，秋花照楚城。","北来休太晚，慰我隔年情。"]},{"t":"除架","f":"五言律诗","c":["苦叶萧疏久，秋匏亦委沙。","家人空抱蔓，山鸟莫啼花。","零落亲寒事，蹉跎感物华。","衰荣转相代，何必恨生涯。"]},{"t":"十月","f":"五言律诗","c":["十月苍山静，孤村带郭长。","卜居怜此地，高枕复吾乡。","野雾沉寒日，城阴迟早霜。","一年看欲暮，酒熟共谁将。"]},{"t":"怀孟望之","f":"五言律诗","c":["消息三秋隔，虚瞻鸿雁群。","长安望不极，落日起浮云。","奉使何时出，吟诗谁共闻。","岂知离索久，病思日纷纷。"]},{"t":"寒","f":"五言律诗","c":["水郭逢寒早，城阴惨澹中。","远山常雾雨，衰柳更天风。","病骨思狐貉，愁颜付酒筒。","关河待冰雪，何处有途穷。"]},{"t":"残菊","f":"五言律诗","c":["寒丛后摇落，冬至亦蹉跎。","病叶强相守，孤英无奈何。","园篱空自爱，霜霰暮还多。","幸有馀香在，深杯为尔歌。"]},{"t":"韩席二佥宪见过留饮","f":"五言律诗","c":["野外惭供给，台端枉驾来。","河鱼还自取，樽酒为君开。","落木寒风急，孤城暮雨催。","相逢孟冬节，翘首待阳回。"]},{"t":"晴","f":"五言律诗","c":["冬郊零雨霁，烟郭望初分。","独树馀寒照，平沙足晚云。","风鸢高不下，野鹤迥难群。","夕坐亲杯酒，长歌还自闻。"]},{"t":"雪柬沈马任三子","f":"五言律诗","c":["黯黯山云起，茅斋傍水涯。","一冬才见雪，十月已开花。","雾袅寒城霰，风吹野岸沙。","同游词赋客，骑马入谁家。"]},{"t":"喜望之至以诗迎之","f":"五言律诗","c":["经岁青山下，空吟求友诗。","故人天上至，慰我病中思。","腊近冰霜苦，春回草木知。","小堂终日待，枉驾莫教迟。"]},{"t":"再别清溪子","f":"五言律诗","c":["冬馆萧条别，开樽为尔吟。","岸梅催客鬓，江柳送归心。","南国浮云暮，孤城积霰阴。","逢春湖雁起，休滞北来音。"]},{"t":"得钱水部书","f":"五言律诗","c":["故人俱落魄，水部近何如。","河上三年别，天涯十月书。","烟波愁望里，风雨梦魂馀。","更枉怀人作，长吟泪满裾。"]},{"t":"怀沈子","f":"五言律诗","c":["沈生南国去，别我独悽然。","落月清江树，归人何处船。","十年安陆舍，数口太湖田。","想到乡园日，生涯亦可怜。"]},{"t":"别望之","f":"五言律诗","c":["相送不得远，临水一悲歌。","行云暮不止，游子意如何。","楚塞风烟迥，燕关雨雪多。","春还问消息，尺素莫蹉跎。"]},{"t":"洪法寺别锦夫邃伯","f":"五言律诗","c":["古寺垂杨里，楼台照落晖。","重来旧游地，却与故人违。","云树千山暗，风花三月飞。","未将湖海泪，空洒路傍衣。"]},{"t":"寄孙世其","f":"五言律诗","c":["世路渺难定，相期未有涯。","昔为燕地客，常到楚人家。","系马中堂树，听莺上苑花。","故园看北斗，肠断忆京华。"]},{"t":"酬葛时秀","f":"五言律诗","c":["罢归翻自喜，旧业有青山。","积雨稀来客，孤云独往还。","良朋枉高倡，抚卷一开颜。","何日还乘兴，题诗到竹间。"]},{"t":"怀叶时华","f":"五言律诗","c":["佳人湖上住，亭榭迥堪怜。","手把青荷叶，行吟绿水边。","客皆莲社友，人是竹林贤。","欲系空庭马，闻君高树蝉。"]},{"t":"雨夜","f":"五言律诗","c":["云薄高城上，孤亭郡郭西。","暗中萤火度，灯下草虫啼。","零落同游客，凄凉旧雨题。","高歌视雄剑，慷慨为谁携。"]},{"t":"游贤隐寺次马君卿韵","f":"五言律诗","c":["系马长松下，风烟几日留。","天高还薄暮，地迥更逢秋。","孤嶂开僧舍，千峰绕佛楼。","自能来白社，不用远公求。"]},{"t":"与孙世其晚坐","f":"五言律诗","c":["留客江村暮，开尊对浦沙。","池心上孤月，树杪落残霞。","地僻唯宜竹，秋高未有花。","琴书堪晤语，随意宿山家。"]},{"t":"十四夜","f":"五言律诗","c":["水际浮云起，孤城日暮阴。","万山秋叶下，独坐一灯深。","白露蒹葭落，西风蟋蟀吟。","关山今夜月，横笛有哀音。"]},{"t":"雨中","f":"五言律诗","c":["一室高原次，遥天起夕风。","雨来河树外，日沉山雾中。","凫雁秋沙静，鸡豚委巷通。","白云望不尽，相对意无穷。"]},{"t":"寄雷长史","f":"五言律诗","c":["不见雷夫子，相望岁半馀。","王门盛宾客，仙府足图书。","贾傅才谁敌，相如病独居。","怜君兼吏隐，休忆锦江鱼。"]},{"t":"宿胡山人家","f":"五言律诗","c":["骑马侵晨出，看山至日昏。","鸣鸡千嶂里，高树一家村。","白石斜通径，清泉直到门。","秪疑人世外，别自有乾坤。"]},{"t":"登坚山寺","f":"五言律诗","c":["西峰插天起，绝顶寺门开。","云里一僧住，山中无客来。","落花平讲席，积草遍香台。","我欲闻清梵，焚香坐不回。"]},{"t":"寄焦太史蕴德","f":"五言律诗","c":["抱璞声名旧，逢时意气殊。","麒麟出天厩，騕袅在云衢。","世史称司马，英词继董孤。","遥知东观里，终日会文儒。"]},{"t":"寄马君卿进士","f":"五言律诗","c":["怜君得意日，骑马向春风。","通籍金门里，分曹画省东。","宫袍唐进士，陛戟汉郎中。","辞赋相如妙，声名谁与同。"]},{"t":"寄阮行人","f":"五言律诗","c":["夫子风流士，高怀近若何。","张骞能奉使，阮籍自行歌。","文字留中岳，楼船渡大河。","梁都看不远，枉驾几时过。"]},{"t":"寄张季升给事","f":"五言律诗","c":["独立当霄汉，清誉在处闻。","朝趋青琐闼，日侍御垆薰。","温室千年树，蓬莱五色云。","同年还愧我，天上早离群。"]},{"t":"寄孟望之","f":"五言律诗","c":["昔在长安日，相看慰别颜。","君行太行谷，多亦下燕关。","春去无消息，秋来书未还。","可怜骨肉梦，常越万重山。"]},{"t":"寄戴仲鹖进士","f":"五言律诗","c":["戴生久离别，宦况近何如。","白日閒官舍，青云近帝居。","明时难自晦，直道未应疏。","问我生涯事，山中懒著书。"]},{"t":"怀李献吉二首 其一","f":"五言律诗","c":["闻君在罗网，古道正难行。","无使传消息，凭谁问死生。","东方元太岁，李白是长庚。","才大翻流落，安知造物情。"]},{"t":"怀李献吉二首 其二","f":"五言律诗","c":["冠盖京华地，斯人独可哀。","神龙在泥淖，朱凤日摧颓。","世路无知己，乾坤孰爱才。","梁园别业在，何日见归来。"]},{"t":"九日同诸友登贤隐山五首 其一","f":"五言律诗","c":["九日西山上，登临思渺然。","高城过一雁，疏柳歇繁蝉。","胜概仍佳节，同游似往年。","休将竹叶盏，空对菊花前。"]},{"t":"九日同诸友登贤隐山五首 其二","f":"五言律诗","c":["古寺来游日，高秋云物清。","楼台芇里目，时序百年情。","野树斜侵郭，河流曲抱城。","明年当此际，谁与共题名。"]},{"t":"九日同诸友登贤隐山五首 其三","f":"五言律诗","c":["野望秋无赖，西风城树凋。","浮云满天地，落日更萧条。","醉舞随长剑，哀歌逐短箫。","龙山高兴者，千载竟难招。"]},{"t":"九日同诸友登贤隐山五首 其四","f":"五言律诗","c":["野寺空崖里，高台旧国傍。","山川待我辈，风日媚重阳。","云峤秋临迥，松林暮倚长。","由来宋玉意，摇落自悲伤。"]},{"t":"九日同诸友登贤隐山五首 其五","f":"五言律诗","c":["薄暮经行处，千岩落照深。","孤松秀云壑，众草莽寒林。","故里登高兴，平居怀旧吟。","风前一感慨，不异古人心。"]},{"t":"望京师寄王职方","f":"五言律诗","c":["北望依南斗，长安万里愁。","西风入上苑，杨柳落金沟。","云近蓬莱阁，天回太液流。","仙郎归尽省，高咏接同游。"]},{"t":"九日怀铁溪","f":"五言律诗","c":["独忆高夔府，何时骑马来。","一秋常卧病，九日废登台。","寂寞传杯手，凄凉作赋才。","陶家园内菊，风雨为谁开。"]},{"t":"两后次孟望之二首 其一","f":"五言律诗","c":["断雨藏深浦，残云霁晚空。","人家乱水外，野艇夕阳中。","风急鸣江鹳，天高落塞鸿。","沧浪浩歌起，身世羡渔翁。"]},{"t":"两后次孟望之二首 其二","f":"五言律诗","c":["万里看无际，高秋接素氛。","沙村昏片雨，石壁断孤云。","鸿雁常求侣，凫鸥不离群。","寒山有落木，风起暮缤纷。"]},{"t":"霜节","f":"五言律诗","c":["鼓角苍山畔，孤城此岁残。","回风夜不止，清霜日以繁。","未惜琼树晚，还悲瑶草寒。","阳春在何日，幽谷待鸣鸾。"]},{"t":"为王子悼亡","f":"五言律诗","c":["玉魄无消息，星辰隔紫泉。","舞鸾沉宝镜，飞凤落金钿。","不待中郎贵，空传上妇贤。","平生浣沙处，流水恨潺湲。"]},{"t":"送柴先生之霍丘访朱调元","f":"五言律诗","c":["客里黄金尽，天边逐岁华。","寒灯具行李，早饭出山家。","东路蘼芜满，西风杨柳斜。","朱君旧相识，见尔惜生涯。"]},{"t":"送孙世其举人归华容二首 其一","f":"五言律诗","c":["似尔聪明少，吾生望未涯。","孤城常作客，九月始还家。","暮雨沉关树，寒风落渚花。","洞庭秋色里，为我吊长沙。"]},{"t":"送孙世其举人归华容二首 其二","f":"五言律诗","c":["尔去荆州府，孤帆几日开。","山过宋玉宅，江到楚王台。","落雁冲人起，浮云度水来。","悲怀兼别绪，岁暮若为裁。"]},{"t":"万岁节","f":"五言律诗","c":["北望看辰极，孤城首重回。","祥云九重殿，仙露万年杯。","凤辇通宵备，龙旂拂曙开。","侍臣金鉴录，谁有九龄才。"]},{"t":"任宏器过访","f":"五言律诗","c":["磊落同乡友，相寻到水涯。","山中沽白酒，篱下觅黄花。","积水寒天阔，连峰夕照斜。","兴来高咏起，挥翰满烟霞。"]},{"t":"上祖茔","f":"五言律诗","c":["故域西山绕，佳城望转幽。","松寒迷唳鹤，草暖集眠牛。","不见丘原起，空怀霜露愁。","诸孙时扫谒，哀泪洒松楸。"]},{"t":"上亡兄墓","f":"五言律诗","c":["阡兆还经岁，音容不可追。","几时门吏散，今日路人悲。","壑有藏舟处，林馀挂剑枝。","哀哀怜小弟，难忘鹡鸰诗。"]},{"t":"访贾西谷","f":"五言律诗","c":["儒宫入古桧，泮水静尘埃。","偶到闲官舍，能孤远客杯。","开门黄叶落，展席清风来。","更喜庭前菊，寒花日暮开。"]},{"t":"西郊秋兴十首 其一","f":"五言律诗","c":["立马西郊地，悲风惨澹生。","白杨落古墓，黄叶下孤城。","流水年年去，浮云日日行。","沧浪清若许，聊可濯吾缨。"]},{"t":"西郊秋兴十首 其二","f":"五言律诗","c":["谷口风兼雨，茅斋淰淰秋。","寒烟浮岛屿，白水乱汀洲。","散地耽高卧，何时作远游。","近来疏懒甚，一月罢登楼。"]},{"t":"西郊秋兴十首 其五","f":"五言律诗","c":["村居元旧业，草舍僻临城。","久雨苍苔积，闲门扫更生。","窥人一鸟下，见客众鸡鸣。","翻怪巢由辈，空多世上名。"]},{"t":"西郊秋兴十首 其六","f":"五言律诗","c":["萧条万峰里，门巷静无哗。","积草惟三径，垂杨自一家。","寒云抱古木，晚日媚残花。","岁事看如此，能教负物华。"]},{"t":"西郊秋兴十首 其七","f":"五言律诗","c":["寂寞高台畔，空令故国存。","古人不可见，遗迹更堪论。","云度孤城夕，天车积水昏。","兴亡向来事，无处问乾坤。"]},{"t":"西郊秋兴十首 其十","f":"五言律诗","c":["古人歌舞地，今日几豪华。","世事那能定，吾生讵有涯。","秋虫不去户，寒雁各依沙。","独少高阳侣，时时过酒家。"]},{"t":"贾长教舍白菊","f":"五言律诗","c":["君家白玉朵，不数黄金花。","淡淡含秋色，亭亭傲岁华。","闲云依槛静，明月傍坛斜。","偶坐题诗去，寒香为尔誇。"]},{"t":"雪","f":"五言律诗","c":["一雪今冬早，霏霏白满沙。","随风斜著树，带雨不成花。","曲槛寒仍袅，空庭晚更加。","城中一万户，歌舞是谁家。"]},{"t":"寄赠庄国宾","f":"五言律诗","c":["上馆宜才子，佳名玉叶光。","文章夺云锦，衣服惹天香。","下笔惊鹦鹉，吹箫跨凤凰。","淮王门下客，冠盖日相望。"]},{"t":"至日二首 其一","f":"五言律诗","c":["一卧乡园晚，频看物候新。","冰霜寒近腊，梅柳暗催春。","直道何时泰，生涯旧业贫。","萧条一杯酒，愁绝对佳辰。"]},{"t":"至日二首 其二","f":"五言律诗","c":["冉冉天时逼，悠悠人事催。","坐观群物变，又见一阳回。","远树朝晖发，孤城冻雾开。","长安望不见，回首独馀哀。"]},{"t":"长安月","f":"五言律诗","c":["万里长安月，曾看照绮罗。","徘徊留舞席，宛转逐游珂。","锦幌披青雾，朱楼拂绛河。","佳人独愁思，终夕抱云和。"]},{"t":"登钓台四首 其一","f":"五言律诗","c":["岁暮荒台上，孤高望不穷。","乱山浮落日，远水抱寒空。","野鹭时亲客，江鸿晚避风。","终期谢城市，来此伴渔翁。"]},{"t":"登钓台四首 其二","f":"五言律诗","c":["出郭冬初暮，登台日已曛。","碧潭寒吐月，孤嶂晚生云。","名姓嫌人识，悲歌欲自闻。","沙鸥莫飞去，应共尔为群。"]},{"t":"登钓台四首 其三","f":"五言律诗","c":["古人栖隐地，今日我重来。","寂寞千山里，烟波万古台。","岩寒苍桂落，沙晚白鸥回。","慷慨无人测，长歌不放杯。"]},{"t":"登钓台四首 其四","f":"五言律诗","c":["薄暮登台罢，云山兴不忘。","门人携酒至，日落更传觞。","一水星河渺，孤烟岛屿长。","不愁归路晚，明月在沧浪。"]},{"t":"送柴先生二首 其一","f":"五言律诗","c":["迢递京华路，怜君岁暮行。","一尊淮水上，疋马楚王城。","白首家无定，黄金药未成。","蓬瀛如可涉，约尔共逃名。"]},{"t":"送柴先生二首 其二","f":"五言律诗","c":["季夏辞燕地，经冬滞汝湄。","孤城一相送，岐路不胜悲。","为客江湖远，求仙岁月迟。","世途来不易，相见更何时。"]},{"t":"送慈溪刘伯雨之南京尚宝卿","f":"五言律诗","c":["甸隔金陵迥，天流银汉斜。","江山回帝宅，牛斗上仙槎。","拔擢符台始，声名礼部遐。","行看好春色，留赏旧京花。"]},{"t":"荅望之二首 其一","f":"五言律诗","c":["念汝书难达，登楼望欲迷。","天寒一雁至，日暮万行啼。","饥馑饶群盗，徵求及寡妻。","江湖更摇落，何处可安栖。"]},{"t":"荅望之二首 其二","f":"五言律诗","c":["日落荒山畔，孤城更可伤。","生涯仍寂寞，世事转仓皇。","百口同饥馑，千村尽虎狼。","知君怜老父，南望白云长。"]},{"t":"雪中简贾长教","f":"五言律诗","c":["云雪孤城暗，深杯谁共挥。","雾中千树失，天上百花飞。","湿益青毡冷，光连素璧辉。","知君郢中曲，高调和人稀。"]},{"t":"寄周明府","f":"五言律诗","c":["旧业燕京下，何方更卜家。","知君能大隐，城市即烟霞。","商谷多芝草，淮山有桂花。","相招空梦寐，岐路满天涯。"]},{"t":"赠韩亚卿返湖南二首 其一","f":"五言律诗","c":["斧钺辞燕阙，襜帷驻楚宫。","使星天汉上，卿月洞庭中。","刘晏经邦计，萧何饷士功。","归朝论事业，不愧古人风。"]},{"t":"赠韩亚卿返湖南二首 其二","f":"五言律诗","c":["送节初临夏，回旌已逼年。","驰驱千里使，经济万人传。","发变江湖上，身归日月边。","淮西困饥馑，侧望达尧天。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其一","f":"五言律诗","c":["憔悴东都士，吾师更可嗟。","三年为逐客，万里未还家。","暮阻巴山雪，春行楚岸花。","江湖无路觅，流涕望天涯。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其二","f":"五言律诗","c":["昔遇南来客，曾传北寄声。","飘零携百口，留滞傍孤城。","泽畔骚人兴，周南太史情。","天高地仍远，御谤竟谁明。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其三","f":"五言律诗","c":["洞庭西去路，消息几回闻。","地僻难逢雁，天长秪见云。","白蘋悲楚客，班竹怨湘君。","宋玉哀师意，空传九辩文。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其四","f":"五言律诗","c":["夫子先辞国，嗟予亦罢官。","生涯同去住，世事各悲欢。","楚地江湖阔，巴山道路难。","白头慈母在，雨雪更愁寒。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其五","f":"五言律诗","c":["迹为羁栖久，身因放逐劳。","五溪淹日月，三峡尚波涛。","梦里摧双翼，愁边见二毛。","清风引归袂，名共蜀山高。"]},{"t":"得五清先生消息尚客澧州怅然有怀作诗六首 其六","f":"五言律诗","c":["儒行荆人识，文章澧郡传。","夷方仍俎豆，客路半舟船。","太守迎徐稚，诸生仰郑玄。","独怜门下士，何日进彭宣。"]},{"t":"寄杭东卿","f":"五言律诗","c":["海内宾朋隔，天边涕泪遥。","一书无计达，万里更能招。","碧树东南地，寒江日夜潮。","石梁如可度，仙路坐相邀。"]},{"t":"送罗秀才归省","f":"五言律诗","c":["汝念高堂母，还家秋色深。","遥知倚闾望，应慰断机心。","落月清淮朗，浮云楚塞阴。","西风吹匹马，惆怅送归吟。"]},{"t":"寄张提学伯纯","f":"五言律诗","c":["旧属朝端望，俱称柱下才。","九霄骢马出，千仞凤凰来。","河洛经中岳，星辰动外台。","山城有桃李，花向几时开。"]},{"t":"闻陆舍人子引罢官兼怀徐舍人德章","f":"五言律诗","c":["惜尔官难达，文章本凤毛。","投簪归海岸，挂席趁江涛。","张翰元思鲙，任公且钓鳌。","南逢徐孺子，应话旧同袍。"]},{"t":"喜刘朝信过饮三首 其一","f":"五言律诗","c":["坐惜芳菲晚，何人到野中。","相邀一尊酒，来对百花丛。","翡翠鸣春日，游丝堕碧空。","谁知艳阳节，烂醉与君同。"]},{"t":"喜刘朝信过饮三首 其二","f":"五言律诗","c":["西郭栖迟地，春风亦可怜。","落花寒食雨，高柳夕阳天。","岸帻行林侧，移樽坐水边。","啼莺如有意，数傍舞衣前。"]},{"t":"喜刘朝信过饮三首 其三","f":"五言律诗","c":["烟树孤城外，风花野水滨。","群鸥不避客，双燕亦留人。","况值清明后，酣歌烂熳春。","相看三月暮，过我勿言频。"]},{"t":"怀王舍人文熙","f":"五言律诗","c":["自我还乡里，无书到野亭。","江湖春浩浩，鸿雁日冥冥。","苑内花空发，池边草自青。","宁知同省客，万里各飘零。"]},{"t":"寄梁宗烈","f":"五言律诗","c":["怜君下第日，即我挂冠时。","岐路千行泪，浮云万里悲。","天高南海柱，地远曲江祠。","处处豺狼斗，相逢未可期。"]},{"t":"送公顺赴湖南有怀旧游","f":"五言律诗","c":["雄胜称三楚，兹游不可无。","入溪身更远，望岳兴难孤。","江汉元朝海，楼台半入吴。","十年历览地，梦绕岳阳湖。"]},{"t":"公顺阻雨又赠","f":"五言律诗","c":["孤城三日住，客子意何穷。","水国春多雨，江沙晚更风。","宦情临汉上，乡梦到秦中。","几欲相拚过，清尊未得同。"]},{"t":"刘朝信读书山寺","f":"五言律诗","c":["嗜静山中寺，藏修此度年。","白云千嶂里，清夜一灯悬。","书卷留孤客，盘飧傍老禅。","何时骑马至，访尔古松边。"]},{"t":"赠玺师","f":"五言律诗","c":["羡尔离群友，明心到洒然。","乾坤卓锡外，日月转轮前。","觉路开无极，迷川度有缘。","黄金留净界，万世此灯传。"]},{"t":"寿徐广文","f":"五言律诗","c":["七十六年过，悠悠湖海人。","青松高比节，黄鹤健如身。","子有徐卿贵，官同郑老贫。","春花岁满眼，常得醉佳辰。"]},{"t":"西谷有浙聘予喜其得胜游因话浙中之胜","f":"五言律诗","c":["君向杭城去，兹游似马迁。","应传越客酒，先泛楚人船。","入郭湖天迥，观潮海月圆。","因君话禹穴，高兴亦飘然。"]},{"t":"送高子登赴试","f":"五言律诗","c":["倚马高槐下，行歌夕更繁。","夏云连楚甸，秋月满梁园。","题柱名千里，登台策万言。","云鸿天路永，今日看飞翻。"]},{"t":"与徐生","f":"五言律诗","c":["念汝多风骨，论文亦有神。","常怀万里志，须爱百年身。","涉海方知水，为山不让尘。","眼前书史在，无限古今人。"]},{"t":"送徐生赴试","f":"五言律诗","c":["尔到梁都日，西风发醉歌。","秋深花近苑，夜过月临河。","姓拟传霄汉，身应谢薜萝。","佳音附来雁，报我莫蹉跎。"]},{"t":"送张秀才还固安","f":"五言律诗","c":["十月燕山雪，孤城易水风。","旅蒐迷白草，乡泪剧丹枫。","万里书生笔，千钧壮士弓。","论文更好武，何地汝成功。"]},{"t":"赠葛时秀","f":"五言律诗","c":["磊落元高士，飞腾且壮年。","骅骝万里路，鹏鹗九秋天。","白璧先淹楚，黄金晚入燕。","春花烂熳日，定醉曲江边。"]},{"t":"奉寄泉山先生","f":"五言律诗","c":["馆阁三朝旧，江湖万里长。","北山高硉矹，南斗极光芒。","皓首归难挽，苍生意未忘。","春风旧桃李，何日傍门墙。"]},{"t":"为李秀才寿母","f":"五言律诗","c":["寒岁开筵处，佳辰对碧山。","梅花似白发，萱草亦朱颜。","志与和熊苦，身因驾鹿闲。","百年应自慰，常见舞衣斑。"]},{"t":"送别刘朝信","f":"五言律诗","c":["万里向天涯，孤城对日斜。","云山共此别，世路独长嗟。","暮雪燕关树，春风汉苑花。","知君骑马地，名姓满京华。"]},{"t":"寄任宏器","f":"五言律诗","c":["白发三年客，沧江万里船。","相思一回首，怀抱即依然。","碧草成诗梦，桃花入醉眠。","高车易倾覆，何以广文毡。"]},{"t":"送熊举人","f":"五言律诗","c":["岁暮尔何适，天涯谁共过。","敝裘冲雨雪，匹马向关河。","季子黄金尽，安仁白发多。","灯前解雄剑，长夜一悲歌。"]}]};